// Content for Equal & Confident (node g50, ages 18-22, Chapter 6): NEW v2 build to GDD 50 (mechanic-embodying),
// taking the gender-equality & allyship work of the teen years into adult arenas where it bites: the seminar
// room, the internship, the first job, public life (Thread E · Gender & Respect, Leadership & Confidence domain).
// Reworks the old ModesEngine build onto the shared v2 engine. 84 researched, India-grounded scenarios across
// claim-your-voice → lead-the-room → spot-counter-bias → be-the-ally → equality-lifts-everyone → tools-and-help,
// each encoded as one of the shared v2 play actions (branch / strike-rewrite / sort / reflect / role-play / spot
// / match): no binary "tap the right card". Lead: branch (your move), strike-rewrite (bust the myth), role-play
// (say the line). Five modes: claim your voice (speak, contribute, don't be talked over), lead the room
// (leadership without a title), spot & counter bias (interruptions, the 'bossy' double-bind, office housework;
// UN&RE), be the ally (active allyship across genders), tools & help. Builds women's confidence and leadership
// while engaging men as allies; EQUALITY LIFTS EVERYONE (not zero-sum). Evenhanded, never anti-boy; confidence
// framed inclusively. Harassment routes to rights/redress (POSH, covered in g51) and help (181, POSH Internal
// Committees). India: women sharply under-represented in workforce and leadership; campus and workplace bias and
// harassment are real. Builds on g33 (Lead the Way) & g26 (Equalize); pairs g51; feeds Chapters 7-8 (g55, g62).
// gameId "equal-confident".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"ec-001","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"If I haven't got a fully-formed point, I shouldn't speak up.\"","myth":{"un":"I shouldn't speak unless my point is fully formed.","re":"Your half-formed thought is often as valuable as anyone's; you belong in the conversation.","why":"Plenty of people speak freely with rougher ideas."},"relearn":"You belong in the conversation; a half-formed thought is still worth voicing.","persona":"any","source":"belonging in the room"},
  {"id":"ec-002","cat":"claim-your-voice","type":"role-play","hook":"You get talked over mid-point in a seminar.","setup":"Reclaim the floor, calmly. Say:","yourLine":[{"text":"\"I'd like to finish my point, thanks, as I was saying...\"","best":true},{"text":"Go quiet and let it slide"}],"relearn":"You can calmly reclaim the floor when you're talked over.","persona":"Aarti","source":"reclaiming your point"},
  {"id":"ec-003","cat":"claim-your-voice","type":"branch","hook":"You have a question but worry it'll sound 'stupid' in front of everyone.","options":[{"text":"Ask it; others are usually wondering the same","consequence":"You add value and model courage.","outcome":"brave","best":true},{"text":"Stay silent to avoid judgement","consequence":"The 'obvious' question is usually on others' minds too; asking it helps everyone."}],"debrief":"The question you're afraid to ask is often the one the whole room needs.","relearn":"Ask the question you're afraid of; others usually share it.","persona":"Deepak","source":"asking questions"},
  {"id":"ec-004","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"I should soften everything I say with 'sorry' and 'just'.\"","myth":{"un":"I should pad everything with 'sorry' and 'just'.","re":"You can state your point directly; over-apologising shrinks your message.","why":"Confident, clear phrasing carries your idea further."},"relearn":"State your point directly; over-apologising shrinks your message.","persona":"any","source":"confident phrasing"},
  {"id":"ec-005","cat":"claim-your-voice","type":"role-play","hook":"You want to contribute an idea in a meeting full of louder voices.","setup":"Step in clearly. Say:","yourLine":[{"text":"\"I've got an idea I'd like to add here.\"","best":true},{"text":"Wait for a perfect gap that never comes"}],"relearn":"Step in clearly to add your idea; don't wait for a perfect gap.","persona":"any","source":"stepping in"},
  {"id":"ec-006","cat":"claim-your-voice","type":"sort","hook":"Sort: claims your voice, or shrinks it?","items":[{"id":"a","text":"Stating your idea plainly"},{"id":"b","text":"Trailing off and apologising"},{"id":"c","text":"Finishing your sentence"},{"id":"d","text":"Letting interruptions win"},{"id":"e","text":"Re-tabling a skipped idea"},{"id":"f","text":"Going quiet when one person frowns"}],"bins":[{"id":"claims","label":"Claims it","valence":"pos"},{"id":"shrinks","label":"Shrinks it","valence":"neg"}],"key":{"a":"claims","b":"shrinks","c":"claims","d":"shrinks","e":"claims","f":"shrinks"},"relearn":"Stating ideas plainly, finishing your point and re-tabling claims your voice; trailing off and yielding shrinks it.","persona":"any","source":"voice habits"},
  {"id":"ec-007","cat":"claim-your-voice","type":"branch","hook":"You're nervous about speaking but have something worth saying.","options":[{"text":"Speak anyway; courage grows by doing","consequence":"You build the muscle of using your voice.","outcome":"growing","best":true},{"text":"Wait until you 'feel ready'","consequence":"Speaking despite nerves builds the muscle; waiting to feel ready usually means staying silent."}],"debrief":"Confidence is built by speaking before you feel ready, not after.","relearn":"Speak even when nervous; confidence grows by doing.","persona":"any","source":"courage muscle"},
  {"id":"ec-008","cat":"claim-your-voice","type":"reflect","hook":"Lensy: your voice and ideas belong in every room you're in. Let that settle?","prompt":"What do you think?","options":["Yes","I belong here","My voice counts"],"affirm":"You belong in the room and your voice counts; never let anyone make you doubt that.","relearn":"Your voice and ideas belong in every room you're in.","persona":"any","source":"you belong"},
  {"id":"ec-009","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"If a woman is quiet in meetings, she has nothing to add.\"","myth":{"un":"If a woman's quiet in meetings, she has nothing to add.","re":"Many capable people are talked over or hold back; the room should make space, not assume emptiness.","why":"Silence is often the room's fault, not the person's."},"relearn":"Many capable people are talked over; the room should make space, not assume they have nothing.","persona":"any","source":"making space"},
  {"id":"ec-010","cat":"claim-your-voice","type":"role-play","hook":"A quieter teammate keeps getting cut off when they start to speak.","setup":"Open space for them. Say:","yourLine":[{"text":"\"Hang on, I think Priya was about to say something, let's hear it.\"","best":true},{"text":"Let the interruptions continue"}],"relearn":"Open space for a teammate who keeps getting cut off.","persona":"Rohan","source":"making space for others"},
  {"id":"ec-011","cat":"claim-your-voice","type":"branch","hook":"Your idea is brushed aside, then praised when a louder colleague repeats it.","options":[{"text":"Calmly note it was your idea and build on it","consequence":"You reclaim your credit gracefully.","outcome":"credited","best":true},{"text":"Seethe quietly and say nothing","consequence":"Calmly noting it was your idea, and building on it, reclaims credit without drama."}],"debrief":"You can reclaim credit for your idea gracefully, without conflict.","relearn":"If your idea is re-credited, calmly note it was yours and build on it.","persona":"any","source":"reclaiming credit"},
  {"id":"ec-012","cat":"claim-your-voice","type":"reflect","hook":"Lensy: speaking up gets easier each time you do it. Worth practising?","prompt":"What do you think?","options":["Yes","Practice helps","Easier each time"],"affirm":"Each time you use your voice, the next time gets a little easier; it's a practice.","relearn":"Speaking up gets easier each time you practise it.","persona":"any","source":"practice"},
  {"id":"ec-013","cat":"claim-your-voice","type":"branch","hook":"You want to apply for a role but don't meet every single requirement.","options":[{"text":"Apply anyway; you rarely need 100%","consequence":"You don't count yourself out.","outcome":"applied","best":true},{"text":"Skip it because you lack one thing","consequence":"People who apply at 60% of the criteria get roles; don't count yourself out over one gap."}],"debrief":"Many qualified people, especially women, count themselves out by waiting to meet 100%; apply anyway.","relearn":"Apply even if you don't meet every requirement; you rarely need 100%.","persona":"Aarti","source":"the confidence gap"},
  {"id":"ec-014","cat":"claim-your-voice","type":"sort","hook":"Sort: a confidence-builder, or a confidence-drainer?","items":[{"id":"a","text":"Preparing one point to make"},{"id":"b","text":"Assuming you'll embarrass yourself"},{"id":"c","text":"Remembering past wins"},{"id":"d","text":"Replaying every awkward moment"},{"id":"e","text":"Practising the line beforehand"},{"id":"f","text":"Comparing yourself to the loudest person"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"drains","label":"Drains it","valence":"neg"}],"key":{"a":"builds","b":"drains","c":"builds","d":"drains","e":"builds","f":"drains"},"relearn":"Preparing, recalling wins and rehearsing builds confidence; assuming embarrassment, replaying flaws and harsh comparison drains it.","persona":"any","source":"confidence habits"},
  {"id":"ec-015","cat":"lead-the-room","type":"strike-rewrite","hook":"\"Leadership requires a title or position.\"","myth":{"un":"Leadership requires a title or position.","re":"Leadership is initiative and lifting others; you can lead from any seat.","why":"The most useful leadership often has no title."},"relearn":"Leadership is initiative and lifting others; you can lead from any seat.","persona":"any","source":"no title needed"},
  {"id":"ec-016","cat":"lead-the-room","type":"branch","hook":"A group project is drifting and no one's taking charge.","options":[{"text":"Step up: suggest a plan and get people involved","consequence":"You lead without a title.","outcome":"leading","best":true},{"text":"Wait for someone official to lead","consequence":"Stepping up with a plan and involving people is leadership, even without a title."}],"debrief":"Taking initiative when there's a gap is exactly what everyday leadership looks like.","relearn":"Take initiative when there's a gap; that's leadership.","persona":"Deepak","source":"initiative"},
  {"id":"ec-017","cat":"lead-the-room","type":"role-play","hook":"A teammate's good idea is going unheard.","setup":"Lift them up. Say:","yourLine":[{"text":"\"I think Sara's idea is really strong, can we come back to it?\"","best":true},{"text":"Push your own idea instead"}],"relearn":"Lifting others' ideas is a powerful, generous form of leadership.","persona":"any","source":"lifting others"},
  {"id":"ec-018","cat":"lead-the-room","type":"sort","hook":"Sort: everyday leadership, or just bossiness?","items":[{"id":"a","text":"Helping the team find a direction"},{"id":"b","text":"Bossing people around for control"},{"id":"c","text":"Giving credit generously"},{"id":"d","text":"Taking all the credit"},{"id":"e","text":"Inviting a quiet member to weigh in"},{"id":"f","text":"Talking over anyone who pushes back"}],"bins":[{"id":"leadership","label":"Leadership","valence":"pos"},{"id":"bossy","label":"Just bossy","valence":"neg"}],"key":{"a":"leadership","b":"bossy","c":"leadership","d":"bossy","e":"leadership","f":"bossy"},"relearn":"Finding direction, crediting and inviting input is leadership; controlling and credit-grabbing is just bossiness.","persona":"any","source":"leadership vs bossy"},
  {"id":"ec-019","cat":"lead-the-room","type":"branch","hook":"You could lead quietly by example, or feel you must be the loudest.","options":[{"text":"Lead in your own style; quiet leadership counts","consequence":"You lead authentically.","outcome":"authentic","best":true},{"text":"Force a loud style that isn't you","consequence":"Quiet, by-example leadership counts as much as loud; lead in your own authentic style."}],"debrief":"Leadership comes in many styles; quiet, steady, by-example leadership is just as real.","relearn":"Lead in your own style; quiet leadership counts as much as loud.","persona":"Zoya","source":"leadership styles"},
  {"id":"ec-020","cat":"lead-the-room","type":"reflect","hook":"Lensy: lifting others up is one of the most respected forms of leadership. Agree?","prompt":"What do you think?","options":["Yes","Lift others","Respected"],"affirm":"Leaders who lift others are the ones people most want to follow; it's true strength.","relearn":"Lifting others up is one of the most respected forms of leadership.","persona":"any","source":"lift to lead"},
  {"id":"ec-021","cat":"lead-the-room","type":"branch","hook":"Taking the lead on something risks failing publicly.","options":[{"text":"Step up anyway; leading means taking that risk","consequence":"You grow as a leader.","outcome":"brave","best":true},{"text":"Avoid leading to stay safe","consequence":"Leadership involves risking visible failure; stepping up anyway is how you grow into it."}],"debrief":"Real leadership means accepting the risk of a visible stumble; that's part of the role.","relearn":"Step up to lead even when it risks public failure.","persona":"any","source":"leading risk"},
  {"id":"ec-022","cat":"lead-the-room","type":"role-play","hook":"You want to encourage a hesitant friend to take a leadership chance.","setup":"Back them. Say:","yourLine":[{"text":"\"You'd be great at this, I'll back you, go for it.\"","best":true},{"text":"Say nothing and let them shrink back"}],"relearn":"Encouraging others into leadership is leadership in itself.","persona":"any","source":"encouraging leaders"},
  {"id":"ec-023","cat":"lead-the-room","type":"sort","hook":"Sort: builds you as a leader, or undercuts it?","items":[{"id":"a","text":"Owning your mistakes"},{"id":"b","text":"Blaming the team when it fails"},{"id":"c","text":"Sharing the credit"},{"id":"d","text":"Hogging the spotlight"},{"id":"e","text":"Asking for help when you're stuck"},{"id":"f","text":"Pretending you have every answer"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"undercuts","label":"Undercuts it","valence":"neg"}],"key":{"a":"builds","b":"undercuts","c":"builds","d":"undercuts","e":"builds","f":"undercuts"},"relearn":"Owning mistakes, sharing credit and asking for help build you; blaming and spotlight-hogging undercut it.","persona":"any","source":"leader habits"},
  {"id":"ec-024","cat":"spot-counter-bias","type":"strike-rewrite","hook":"\"An assertive woman is 'bossy'; an assertive man is a leader.\"","myth":{"un":"Assertive women are 'bossy'; assertive men are leaders.","re":"That double standard is the bias; the same assertiveness is leadership in anyone.","why":"Calling it 'bossy' only for women is the unfairness."},"relearn":"The 'bossy' double standard is the bias; assertiveness is leadership in anyone.","persona":"any","source":"the double-bind"},
  {"id":"ec-025","cat":"spot-counter-bias","type":"spot","persona":"any","source":"spotting bias","relearn":"Default note-taking to women and interrupting them more are everyday biases.","hook":"Spot the two everyday biases.","scene":[{"id":"a","text":"A woman asked to take the notes by default","trick":true},{"id":"b","text":"Rotating note-taking fairly","trick":false},{"id":"c","text":"A woman interrupted more than the men","trick":true},{"id":"d","text":"Everyone heard out to the end of their point","trick":false},{"id":"e","text":"The agenda set by whoever's chairing this week","trick":false}],"why":"Defaulting note-taking to women and interrupting them more are everyday biases; rotating and hearing all out aren't."},
  {"id":"ec-026","cat":"spot-counter-bias","type":"strike-rewrite","hook":"\"Taking notes and organising is just naturally the women's job.\"","myth":{"un":"Taking notes and organising is naturally women's work.","re":"'Office housework' should be shared, not defaulted to women; it's unglamorous and rarely gets you promoted.","why":"Defaulting it to women holds their careers back."},"relearn":"'Office housework' should be shared, not defaulted to women.","persona":"any","source":"office housework"},
  {"id":"ec-027","cat":"spot-counter-bias","type":"sort","persona":"any","source":"bias vs fair","relearn":"Interrupting women more and mis-crediting their ideas is bias; the fair twins aren't.","hook":"Sort: an everyday bias, or fair treatment?","items":[{"id":"a","text":"Interrupting women more than men"},{"id":"b","text":"Letting everyone finish their point"},{"id":"c","text":"Crediting a woman's idea to a man"},{"id":"d","text":"Crediting ideas to whoever had them"},{"id":"e","text":"Reading her tone harder than his"},{"id":"f","text":"Judging both on the same work"}],"bins":[{"id":"bias","label":"Bias","valence":"neg"},{"id":"fair","label":"Fair","valence":"pos"}],"key":{"a":"bias","b":"fair","c":"bias","d":"fair","e":"bias","f":"fair"}},
  {"id":"ec-028","cat":"spot-counter-bias","type":"role-play","hook":"You see a colleague's idea get re-credited to someone louder.","setup":"Call it in, kindly. Say:","yourLine":[{"text":"\"Just to credit it properly, that was actually Meena's idea earlier.\"","best":true},{"text":"Let the wrong person take the credit"}],"relearn":"Kindly re-credit an idea to the person who actually had it.","persona":"Rohan","source":"crediting fairly"},
  {"id":"ec-029","cat":"spot-counter-bias","type":"strike-rewrite","hook":"\"Calling out bias always means a big confrontation.\"","myth":{"un":"Calling out bias always means a big confrontation.","re":"You can 'call it in', kindly and often privately, giving people a chance to change.","why":"Calling in changes behaviour without humiliating anyone."},"relearn":"You can 'call it in' kindly and privately, not just call out; it gives a chance to change.","persona":"any","source":"call in vs call out"},
  {"id":"ec-030","cat":"spot-counter-bias","type":"spot","persona":"any","source":"manterruption","relearn":"Repeatedly cutting women off and re-crediting their points are interruption-bias patterns.","hook":"Spot the two interruption-bias patterns.","scene":[{"id":"a","text":"A woman cut off mid-sentence, repeatedly","trick":true},{"id":"b","text":"A back-and-forth where all finish","trick":false},{"id":"c","text":"Her point ignored, then praised from a man","trick":true},{"id":"d","text":"The chair bringing her back in to finish","trick":false},{"id":"e","text":"Her name kept on the idea she raised","trick":false}],"why":"Repeatedly cutting a woman off and re-praising her point from a man are interruption-bias patterns; the rest aren't."},
  {"id":"ec-031","cat":"spot-counter-bias","type":"spot","persona":"any","source":"rebalancing","relearn":"Letting admin default to women, and piling more on her, are the red flags.","hook":"Spot the two moves that keep office housework on women.","scene":[{"id":"a","text":"Suggesting the admin rotates among everyone","trick":false},{"id":"b","text":"Letting it always land on the women","trick":true},{"id":"c","text":"Volunteering to take the notes this time","trick":false},{"id":"d","text":"Piling the cleanup onto her, 'she's good at it'","trick":true},{"id":"e","text":"A shared rota everyone signs up to","trick":false}],"why":"Letting admin default to women and piling more on her keep it gendered; rotating and volunteering rebalance it."},
  {"id":"ec-032","cat":"spot-counter-bias","type":"sort","persona":"any","source":"countering well","relearn":"Calling in kindly and naming patterns counters bias; humiliating doesn't.","hook":"Sort: countering bias well, or making it worse?","items":[{"id":"a","text":"Calling it in privately and kindly"},{"id":"b","text":"Publicly humiliating someone"},{"id":"c","text":"Naming the pattern calmly"},{"id":"d","text":"Staying silent every time"},{"id":"e","text":"Re-crediting her idea to her"},{"id":"f","text":"Mocking them in the group chat"}],"bins":[{"id":"well","label":"Counters it well","valence":"pos"},{"id":"worse","label":"Worse / unhelpful","valence":"neg"}],"key":{"a":"well","b":"worse","c":"well","d":"worse","e":"well","f":"worse"}},
  {"id":"ec-033","cat":"spot-counter-bias","type":"branch","hook":"You catch yourself about to call a woman colleague 'bossy' for being assertive.","options":[{"text":"Check the bias and reframe it as leadership","consequence":"You catch your own double standard.","outcome":"self-aware","best":true},{"text":"Use the label anyway","consequence":"Catching the 'bossy' double standard in yourself, and reframing it as leadership, is real growth."}],"debrief":"Spotting and checking your own biases is as important as spotting others'.","relearn":"Catch your own 'bossy' double standard and reframe it as leadership.","persona":"any","source":"checking yourself"},
  {"id":"ec-034","cat":"spot-counter-bias","type":"reflect","hook":"Lensy: once you can see the everyday biases, you can't unsee them, and you can counter them. Powerful?","prompt":"What do you think?","options":["Yes","I see it now","I can counter it"],"affirm":"Seeing the patterns is the first power; countering them is the second, and you have both now.","relearn":"Once you see everyday biases, you can name and counter them.","persona":"any","source":"seeing it"},
  {"id":"ec-035","cat":"be-the-ally","type":"strike-rewrite","hook":"\"Allyship just means believing in equality.\"","myth":{"un":"Allyship just means believing in equality.","re":"Allyship is action: amplify, interrupt the interruption, share the load, back people up.","why":"Belief without action changes nothing in the room."},"relearn":"Allyship is action: amplify, interrupt the interruption, share the load.","persona":"any","source":"allyship is action"},
  {"id":"ec-036","cat":"be-the-ally","type":"role-play","hook":"A colleague's point keeps getting overlooked in a meeting.","setup":"Amplify them. Say:","yourLine":[{"text":"\"I want to build on what Anjali said, it's an important point.\"","best":true},{"text":"Stay quiet and move on"}],"relearn":"Amplify a colleague by repeating and crediting their point.","persona":"Rohan","source":"amplification"},
  {"id":"ec-037","cat":"be-the-ally","type":"branch","hook":"You notice the same person always gets interrupted.","options":[{"text":"Interrupt the interruption and hand it back to them","consequence":"You use your voice for someone else.","outcome":"ally","best":true},{"text":"Stay out of it","consequence":"Interrupting the interruption and handing the floor back is concrete allyship."}],"debrief":"Interrupting the interruption is one of the most effective everyday ally moves.","relearn":"Interrupt the interruption and hand the floor back to the person.","persona":"any","source":"interrupt the interruption"},
  {"id":"ec-038","cat":"be-the-ally","type":"sort","hook":"Sort: active allyship, or just performance?","items":[{"id":"a","text":"Amplifying and crediting others"},{"id":"b","text":"Posting a slogan, doing nothing"},{"id":"c","text":"Sharing the office housework"},{"id":"d","text":"Claiming to be an ally for praise"},{"id":"e","text":"Mentoring a junior, no fanfare"},{"id":"f","text":"Adding 'ally' to your bio, nothing else"}],"bins":[{"id":"active","label":"Active allyship","valence":"pos"},{"id":"performance","label":"Performance","valence":"neg"}],"key":{"a":"active","b":"performance","c":"active","d":"performance","e":"active","f":"performance"},"relearn":"Amplifying, crediting, sharing the load and mentoring is active allyship; slogans, praise-seeking and a bio tag are performance.","persona":"any","source":"active vs performative"},
  {"id":"ec-039","cat":"be-the-ally","type":"strike-rewrite","hook":"\"A man speaking up for equality is unmanly or not his place.\"","myth":{"un":"A man speaking up for equality is unmanly or not his place.","re":"Men leading on equality is strength, and everyone's job; allyship suits all genders.","why":"Equality needs allies from every group."},"relearn":"Men leading on equality is strength and everyone's job.","persona":"Rohan","source":"men as allies"},
  {"id":"ec-040","cat":"be-the-ally","type":"role-play","hook":"A friend makes a sexist 'joke' in your group.","setup":"Call it in, lightly but clearly. Say:","yourLine":[{"text":"\"That one's not really on, mate, let's not.\"","best":true},{"text":"Laugh along to keep the peace"}],"relearn":"Calling in a sexist 'joke' lightly but clearly is everyday allyship.","persona":"Rohan","source":"calling in jokes"},
  {"id":"ec-041","cat":"be-the-ally","type":"branch","hook":"A colleague is being talked over and dismissed in a meeting you're in.","options":[{"text":"Back them up out loud and redirect to them","consequence":"You lend your voice as support.","outcome":"backed","best":true},{"text":"Feel bad but say nothing","consequence":"Backing them up out loud and redirecting to them turns sympathy into real allyship."}],"debrief":"Visible, in-the-moment backing is what allyship actually looks like.","relearn":"Back someone up out loud when they're dismissed; that's allyship.","persona":"any","source":"backing up"},
  {"id":"ec-042","cat":"be-the-ally","type":"sort","hook":"Sort: an ally move, or a bystander move?","items":[{"id":"a","text":"Redirecting credit to its owner"},{"id":"b","text":"Watching bias and saying nothing"},{"id":"c","text":"Sharing a chance with someone overlooked"},{"id":"d","text":"Assuming someone else will speak up"},{"id":"e","text":"Handing the floor back to who was cut off"},{"id":"f","text":"Telling yourself it's not your place"}],"bins":[{"id":"ally","label":"Ally move","valence":"pos"},{"id":"bystander","label":"Bystander","valence":"neg"}],"key":{"a":"ally","b":"bystander","c":"ally","d":"bystander","e":"ally","f":"bystander"},"relearn":"Redirecting credit, sharing chances and handing the floor back are ally moves; watching, assuming and 'not my place' are bystanding.","persona":"any","source":"ally vs bystander"},
  {"id":"ec-043","cat":"be-the-ally","type":"role-play","hook":"A queer colleague is being subtly sidelined by the group.","setup":"Include them, actively. Say:","yourLine":[{"text":"\"Ravi, you know this area well, what's your take?\"","best":true},{"text":"Go along with the sidelining"}],"relearn":"Actively include someone being sidelined; inclusive allyship spans all identities.","persona":"Zoya","source":"inclusive allyship"},
  {"id":"ec-044","cat":"be-the-ally","type":"reflect","hook":"Lensy: using your voice for someone who's being overlooked costs little and means a lot. Worth doing?","prompt":"What do you think?","options":["Yes","Worth it","Use my voice"],"affirm":"Lending your voice to someone overlooked is small for you and huge for them; always worth it.","relearn":"Using your voice for someone overlooked costs little and means a lot.","persona":"any","source":"the cost"},
  {"id":"ec-045","cat":"be-the-ally","type":"branch","hook":"You hold some advantage in a room, others junior or overlooked.","options":[{"text":"Use your standing to open doors for them","consequence":"You turn advantage into allyship.","outcome":"opener","best":true},{"text":"Keep the advantage to yourself","consequence":"Using your standing to open doors for others turns advantage into real allyship."}],"debrief":"Allyship often means spending a little of your own standing to lift someone else.","relearn":"Use any standing you have to open doors for others.","persona":"any","source":"using advantage"},
  {"id":"ec-046","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Equality means men lose.\"","myth":{"un":"Equality means men lose.","re":"Equality lifts everyone; it's not zero-sum, men gain freedom from rigid roles too.","why":"Fairness expands the pie, not divides it."},"relearn":"Equality lifts everyone; it's not zero-sum, and men gain too.","persona":"any","source":"not zero-sum"},
  {"id":"ec-047","cat":"equality-lifts-everyone","type":"match","hook":"Match each equality outcome to whether it's a win or a loss for all.","relearn":"Freeing men from rigid roles and merit-judging are equality wins; wasted talent and bias are losses.","persona":"any","source":"equality wins","pairs":[{"left":"Men freed from 'never show emotion'","right":"A win for everyone"},{"left":"People judged on real merit","right":"A win we all share"},{"left":"Talent wasted by bias","right":"A loss for everyone"},{"left":"Diverse teams deciding better","right":"A gain the whole team feels"},{"left":"Capable people held back","right":"A loss the group bears"}]},
  {"id":"ec-048","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Caring about equality is a women's issue only.\"","myth":{"un":"Equality is a women's issue only.","re":"Everyone benefits from equality, and everyone has a part in building it.","why":"Rigid roles cost all genders."},"relearn":"Equality benefits everyone, and everyone has a part in building it.","persona":"Rohan","source":"everyone's issue"},
  {"id":"ec-049","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: a fairer room, team or workplace is genuinely better for everyone in it. Agree?","prompt":"What do you think?","options":["Yes","Better for all","Fairer is better"],"affirm":"Fairer teams are happier and more effective; equality is a gain for everyone, not a trade-off.","relearn":"A fairer room or workplace is better for everyone in it.","persona":"any","source":"better for all"},
  {"id":"ec-050","cat":"equality-lifts-everyone","type":"branch","hook":"Someone frames a push for equality as 'an attack on men'.","options":[{"text":"Reframe it: equality lifts everyone, it's not against anyone","consequence":"You defuse the zero-sum framing.","outcome":"reframed","best":true},{"text":"Accept the 'us vs them' framing","consequence":"Reframing equality as lifting everyone, not attacking anyone, defuses the false zero-sum story."}],"debrief":"Equality is for everyone, not against anyone; reframing the zero-sum story matters.","relearn":"Reframe equality as lifting everyone, not as an attack on any group.","persona":"any","source":"reframing zero-sum"},
  {"id":"ec-051","cat":"equality-lifts-everyone","type":"sort","hook":"Sort: a true belief about equality, or a zero-sum myth?","items":[{"id":"a","text":"Diverse teams tend to do better"},{"id":"b","text":"Equality is a threat to men"},{"id":"c","text":"Everyone gains from fairness"},{"id":"d","text":"It's a fixed pie to fight over"},{"id":"e","text":"Men gain freedom from rigid roles"},{"id":"f","text":"Fairness for women is a loss for men"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Diverse teams winning and everyone gaining are true; 'a threat to men' and 'fixed pie' are myths.","persona":"any","source":"equality facts"},
  {"id":"ec-052","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: building a fairer world is something you do with people, not against them. Carry that?","prompt":"What do you think?","options":["Yes","With, not against","Together"],"affirm":"Equality is built with people, across every gender; that 'together' spirit is what makes it work.","relearn":"Equality is built with people, across genders, not against anyone.","persona":"any","source":"together"},
  {"id":"ec-053","cat":"tools-and-help","type":"match","persona":"any","source":"the toolkit","hook":"Match the move to the bias it counters.","pairs":[{"left":"Amplify and credit","right":"Stolen or ignored ideas"},{"left":"Interrupt the interruption","right":"Being talked over"},{"left":"Rotate the admin","right":"Office housework on one person"},{"left":"Call it in kindly","right":"An everyday sexist dig"},{"left":"Drop the double standard","right":"A woman called 'bossy'"}],"relearn":"Amplifying, interrupting interruptions, rotating admin, calling in and dropping the double standard each counter a specific bias."},
  {"id":"ec-054","cat":"tools-and-help","type":"sort","persona":"any","source":"the toolkit","hook":"Sort: in the confidence & call-in toolkit, or not?","items":[{"id":"a","text":"Reclaiming your point calmly"},{"id":"b","text":"Shrinking and apologising"},{"id":"c","text":"Calling bias in, kindly"},{"id":"d","text":"Humiliating someone publicly"},{"id":"e","text":"Amplifying and crediting a colleague"},{"id":"f","text":"Going quiet to keep the peace"}],"bins":[{"id":"toolkit","label":"In the toolkit","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"toolkit","b":"not","c":"toolkit","d":"not","e":"toolkit","f":"not"},"relearn":"Reclaiming, calling bias in kindly and amplifying are in the toolkit; shrinking, humiliating and going quiet aren't."},
  {"id":"ec-055","cat":"tools-and-help","type":"branch","hook":"A colleague is being harassed and unsure it 'counts' or what to do.","options":[{"text":"Support them and point to redress (POSH committee, 181)","consequence":"You connect them to real recourse.","outcome":"supported","best":true},{"text":"Tell them to just put up with it","consequence":"Harassment is never the price of a job; point to POSH redress and 181."}],"debrief":"Harassment has real redress, the POSH Internal Committee and helpline 181; it's never something to endure.","relearn":"Harassment isn't the price of a job; point to POSH redress and 181.","persona":"Mehta","source":"harassment redress"},
  {"id":"ec-056","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Harassment is just part of having a job; you put up with it.\"","myth":{"un":"Harassment is just part of having a job.","re":"Harassment is never the price of a job; there are rights and redress (POSH, Internal Committees, 181).","why":"The law and your workplace owe you safety."},"relearn":"Harassment is never the price of a job; there are rights and redress (POSH, 181).","persona":"any","source":"never the price"},
  {"id":"ec-057","cat":"tools-and-help","type":"match","persona":"any","source":"help routes","hook":"Match the need to where help lives (India).","pairs":[{"left":"Workplace/campus harassment","right":"Your office Internal Committee"},{"left":"A woman in distress","right":"Women Helpline 181"},{"left":"Knowing your rights in depth","right":"Know Your Rights (g51)"},{"left":"Backing in the room","right":"A trusted ally colleague"},{"left":"It's weighing on you","right":"A campus counsellor"}],"relearn":"Internal Committee for harassment, 181 for distress, g51 for rights, plus allies and a counsellor for support."},
  {"id":"ec-058","cat":"tools-and-help","type":"reflect","hook":"Lensy: claim your voice, lead, spot bias and be the ally, you can change the rooms you're in. Feel it?","prompt":"What do you think?","options":["Yes","I can change the room","Equipped"],"affirm":"Voice, leadership, bias-spotting and allyship are exactly the tools to make any room fairer.","relearn":"Claim your voice, lead, spot bias and be the ally, you can change the rooms you're in.","persona":"any","source":"equipped"},
  {"id":"ec-059","cat":"tools-and-help","type":"spot","persona":"any","source":"building the room","hook":"Spot the 2 lines that undermine an equal, confident room.","scene":[{"id":"a","text":"\"Let's hear everyone's point\"","trick":false},{"id":"b","text":"\"She's just being bossy\"","trick":true},{"id":"c","text":"\"Credit whoever had the idea\"","trick":false},{"id":"d","text":"\"Leave notes to her, she's better\"","trick":true},{"id":"e","text":"\"Let her finish before you jump in\"","trick":false}],"why":"The 'bossy' label and defaulting notes to her undermine; hearing everyone and crediting fairly build it.","relearn":"'Hear everyone' and 'credit fairly' build an equal room; the 'bossy' label and defaulting admin undermine it."},
  {"id":"ec-060","cat":"tools-and-help","type":"reflect","hook":"Lensy: which 'equal & confident' move will you carry into work and life?","prompt":"Pick one.","options":["Claim my voice","Lead from any seat","Call bias in","Be an active ally"],"affirm":"Carry that one into every room, and you make work and life fairer for everyone, yourself included.","relearn":"Claim your voice, lead from any seat, call bias in, and be an active ally.","persona":"any","source":"carry forward"},
  {"id":"ec-061","cat":"claim-your-voice","type":"branch","hook":"A senior dismisses your suggestion in front of the team.","options":[{"text":"Stand by it calmly and offer your reasoning","consequence":"You hold your ground respectfully.","outcome":"steady","best":true},{"text":"Immediately back down and apologise","consequence":"Standing by your idea with reasoning, calmly, beats instantly backing down to a dismissal."}],"debrief":"You can hold your ground respectfully even when someone senior dismisses you.","relearn":"Stand by a good idea calmly, even when someone senior dismisses it.","persona":"Aarti","source":"holding ground"},
  {"id":"ec-062","cat":"lead-the-room","type":"strike-rewrite","hook":"\"Real leaders never ask for help or admit doubt.\"","myth":{"un":"Real leaders never ask for help or admit doubt.","re":"Good leaders ask for help and own uncertainty; it builds trust, not weakness.","why":"Pretending to know everything erodes a team."},"relearn":"Good leaders ask for help and admit doubt; it builds trust.","persona":"any","source":"humble leadership"},
  {"id":"ec-063","cat":"spot-counter-bias","type":"spot","persona":"any","source":"promotable work","relearn":"Watch who gets the high-visibility, promotable work, not just the admin.","hook":"Spot the two equity issues in who gets which work.","scene":[{"id":"a","text":"Women rarely getting high-visibility projects","trick":true},{"id":"b","text":"Projects allocated on fit and fairness","trick":false},{"id":"c","text":"The promotable work going to one group","trick":true},{"id":"d","text":"Visible roles rotated across the team","trick":false},{"id":"e","text":"Stretch work offered to whoever wants it","trick":false}],"why":"Women rarely getting visible projects and promotable work pooling in one group are equity issues; fair, rotated allocation isn't."},
  {"id":"ec-064","cat":"be-the-ally","type":"branch","hook":"You're praised for an idea a junior colleague actually gave you.","options":[{"text":"Redirect the credit to them, publicly","consequence":"You model honest allyship.","outcome":"honest","best":true},{"text":"Quietly accept the praise","consequence":"Redirecting credit to the junior colleague who had the idea is honest, powerful allyship."}],"debrief":"Giving credit where it's due, especially to juniors, is allyship and integrity at once.","relearn":"Redirect credit to the person who actually had the idea.","persona":"any","source":"credit honesty"},
  {"id":"ec-065","cat":"claim-your-voice","type":"role-play","hook":"You want to negotiate for a fairer role or recognition.","setup":"Advocate for yourself plainly. Say:","yourLine":[{"text":"\"I've delivered X and Y; I'd like us to talk about my role and recognition.\"","best":true},{"text":"Hope someone notices without you asking"}],"relearn":"Advocate for yourself plainly; don't rely on being noticed.","persona":"Aarti","source":"self-advocacy"},
  {"id":"ec-066","cat":"equality-lifts-everyone","type":"branch","hook":"Your friend group treats 'equality talk' as killing the vibe.","options":[{"text":"Keep it light but model fairness anyway","consequence":"You shift the norm without preaching.","outcome":"norm-shift","best":true},{"text":"Drop it to fit in","consequence":"Keeping it light while modelling fairness shifts the group's norm without preaching."}],"debrief":"Modelling fairness casually shifts a group's norms more than lecturing does.","relearn":"Model fairness casually to shift group norms, without preaching.","persona":"Rohan","source":"shifting norms"},
  {"id":"ec-067","cat":"lead-the-room","type":"reflect","hook":"Lensy: the leaders worth following make others feel bigger, not smaller. Be that kind?","prompt":"What do you think?","options":["Yes","Make others bigger","That kind"],"affirm":"Leaders who make others feel bigger are the ones who build real, lasting teams.","relearn":"The best leaders make others feel bigger, not smaller.","persona":"any","source":"the best leaders"},
  {"id":"ec-068","cat":"spot-counter-bias","type":"role-play","hook":"A colleague keeps being asked to fetch coffee and take notes, always her.","setup":"Rebalance it out loud. Say:","yourLine":[{"text":"\"Let's rotate the notes, I'll take them this time.\"","best":true},{"text":"Let it keep landing on her"}],"relearn":"Volunteer to rebalance the office housework out loud.","persona":"Rohan","source":"rebalancing housework"},
  {"id":"ec-069","cat":"be-the-ally","type":"sort","hook":"Sort: makes you a better ally, or undermines it?","items":[{"id":"a","text":"Listening to those affected"},{"id":"b","text":"Centring yourself as the hero"},{"id":"c","text":"Following their lead"},{"id":"d","text":"Speaking over the people you're helping"},{"id":"e","text":"Asking what support they want"},{"id":"f","text":"Taking over their fight without asking"}],"bins":[{"id":"better","label":"Better ally","valence":"pos"},{"id":"undermines","label":"Undermines it","valence":"neg"}],"key":{"a":"better","b":"undermines","c":"better","d":"undermines","e":"better","f":"undermines"},"relearn":"Listening, following their lead and asking what they want makes a better ally; centring yourself or taking over undermines it.","persona":"any","source":"good allyship"},
  {"id":"ec-070","cat":"claim-your-voice","type":"reflect","hook":"Lensy: your confidence isn't arrogance, it's taking up the space you're entitled to. Reframe it?","prompt":"What do you think?","options":["Yes","My space","Not arrogance"],"affirm":"Confidence is simply claiming your rightful space; it isn't arrogance, and you're entitled to it.","relearn":"Confidence isn't arrogance; it's taking the space you're entitled to.","persona":"any","source":"confidence reframe"},
  {"id":"ec-071","cat":"spot-counter-bias","type":"sort","persona":"any","source":"subtle bias","relearn":"Assuming the man is senior and judging her tone harder are biases.","hook":"Sort: a subtle bias, or a neutral act?","items":[{"id":"a","text":"Assuming the man is the senior one"},{"id":"b","text":"Asking who's leading the project"},{"id":"c","text":"Judging a woman's tone more harshly"},{"id":"d","text":"Giving feedback on the work itself"},{"id":"e","text":"Expecting her to organise the lunch"},{"id":"f","text":"Rotating who books the room"}],"bins":[{"id":"bias","label":"Subtle bias","valence":"neg"},{"id":"neutral","label":"Neutral","valence":"neutral"}],"key":{"a":"bias","b":"neutral","c":"bias","d":"neutral","e":"bias","f":"neutral"}},
  {"id":"ec-072","cat":"be-the-ally","type":"branch","hook":"You want to be an ally but worry about 'getting it wrong'.","options":[{"text":"Act, listen, and adjust if you slip; trying beats freezing","consequence":"You become a real, learning ally.","outcome":"learning","best":true},{"text":"Do nothing to avoid mistakes","consequence":"Acting, listening and adjusting beats freezing; allies learn by trying, not by staying silent."}],"debrief":"Imperfect, learning allyship beats perfect inaction; act, listen, and adjust.","relearn":"Act as an ally, listen, and adjust if you slip; trying beats freezing.","persona":"any","source":"learning ally"},
  {"id":"ec-073","cat":"lead-the-room","type":"branch","hook":"You can take a visible leadership role that stretches you.","options":[{"text":"Say yes and grow into it","consequence":"You expand what you're capable of.","outcome":"growth","best":true},{"text":"Decline, assuming you're not ready","consequence":"Saying yes and growing into a stretch role beats declining on the assumption you're not ready."}],"debrief":"Stretch leadership roles grow you; you rarely feel fully ready, and that's normal.","relearn":"Say yes to stretch leadership roles; you grow into them.","persona":"Aarti","source":"stretch roles"},
  {"id":"ec-074","cat":"equality-lifts-everyone","type":"role-play","hook":"A mate says feminism is 'anti-men'.","setup":"Reframe it warmly. Say:","yourLine":[{"text":"\"It's about fairness for everyone, honestly, men included, it's not against us.\"","best":true},{"text":"Argue aggressively or just agree"}],"relearn":"Reframe equality as fairness for everyone, men included, not anti-men.","persona":"Rohan","source":"reframing for peers"},
  {"id":"ec-075","cat":"claim-your-voice","type":"sort","hook":"Sort: helps you be heard, or fades you out?","items":[{"id":"a","text":"Speaking early in a discussion"},{"id":"b","text":"Waiting until the very end, unheard"},{"id":"c","text":"Building on others, then adding yours"},{"id":"d","text":"Pre-apologising for your idea"},{"id":"e","text":"Leading with your main point"},{"id":"f","text":"Mumbling so no one's put out"}],"bins":[{"id":"heard","label":"Helps you be heard","valence":"pos"},{"id":"fades","label":"Fades you out","valence":"neg"}],"key":{"a":"heard","b":"fades","c":"heard","d":"fades","e":"heard","f":"fades"},"relearn":"Speaking early, building on others and leading with your point gets you heard; waiting, pre-apologising and mumbling fades you out.","persona":"any","source":"being heard"},
  {"id":"ec-076","cat":"spot-counter-bias","type":"strike-rewrite","hook":"\"If she really had the talent, the bias wouldn't hold her back.\"","myth":{"un":"If she had the talent, bias wouldn't hold her back.","re":"Bias holds back talented people all the time; that's exactly why it's worth countering.","why":"Talent doesn't cancel structural barriers."},"relearn":"Bias holds back talented people; that's why it's worth countering, not proof of less talent.","persona":"any","source":"bias is real"},
  {"id":"ec-077","cat":"be-the-ally","type":"reflect","hook":"Lensy: being an ally is a daily practice of small actions, not a badge you wear. Agree?","prompt":"What do you think?","options":["Yes","Daily practice","Not a badge"],"affirm":"Allyship lives in small daily actions, not in a label; that's what makes it real.","relearn":"Allyship is a daily practice of small actions, not a badge.","persona":"any","source":"daily practice"},
  {"id":"ec-078","cat":"lead-the-room","type":"match","hook":"Match the leadership move to its effect on a team.","relearn":"Inviting quieter people in and crediting openly grows a fair team; domination shrinks it.","persona":"any","source":"team building","pairs":[{"left":"Inviting quieter people in","right":"Grows a fair team"},{"left":"Crediting contributions openly","right":"Builds trust"},{"left":"Letting the loudest dominate","right":"Shrinks the team"},{"left":"Owning a wrong call","right":"Earns respect"},{"left":"Backing a hesitant member","right":"Builds their courage"}]},
  {"id":"ec-079","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"Taking up space confidently isn't 'ladylike'.\"","myth":{"un":"Taking up space confidently isn't 'ladylike'.","re":"Everyone, of any gender, is entitled to take up space and be heard.","why":"'Ladylike' shouldn't mean small or silent."},"relearn":"Everyone is entitled to take up space and be heard, regardless of gender.","persona":"Aarti","source":"taking up space"},
  {"id":"ec-080","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: the generation that makes equality normal at work and home changes everything after. Be part of it?","prompt":"What do you think?","options":["Yes","Count me in","Change everything"],"affirm":"Normalising equality at work and home is how your generation changes the ones that follow.","relearn":"Making equality normal at work and home changes everything after.","persona":"any","source":"the vision"},
  {"id":"ec-081","cat":"be-the-ally","type":"role-play","hook":"You witness everyday sexism and feel the urge to stay silent.","setup":"Use a simple call-in line. Say:","yourLine":[{"text":"\"Hey, that's not really fair, can we keep it respectful?\"","best":true},{"text":"Say nothing and look away"}],"relearn":"A simple, calm call-in line is enough to interrupt everyday sexism.","persona":"any","source":"the call-in line"},
  {"id":"ec-082","cat":"tools-and-help","type":"sort","persona":"any","source":"real vs optics","hook":"Sort: a reliable way to build real equality, or just optics?","items":[{"id":"a","text":"Changing how credit and tasks are shared"},{"id":"b","text":"A one-off slogan campaign"},{"id":"c","text":"Mentoring overlooked people"},{"id":"d","text":"Talking equality but acting the same"},{"id":"e","text":"Tracking who gets the visible work"},{"id":"f","text":"A poster nobody's behaviour follows"}],"bins":[{"id":"real","label":"Real change","valence":"pos"},{"id":"optics","label":"Just optics","valence":"neg"}],"key":{"a":"real","b":"optics","c":"real","d":"optics","e":"real","f":"optics"},"relearn":"Sharing credit and tasks, mentoring and tracking visible work are real change; slogans, posters and unchanged behaviour are optics."},
  {"id":"ec-083","cat":"lead-the-room","type":"branch","hook":"You're leading and notice you keep hearing only the confident few.","options":[{"text":"Deliberately invite the quieter voices in","consequence":"You lead more inclusively.","outcome":"inclusive","best":true},{"text":"Just go with whoever speaks up","consequence":"Deliberately inviting quieter voices in leads more inclusively than only hearing the confident few."}],"debrief":"Inclusive leaders actively draw out the quieter voices, not just the loud ones.","relearn":"As a leader, deliberately invite the quieter voices in.","persona":"any","source":"inclusive leading"},
  {"id":"ec-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: equal and confident, your voice, your leadership, your allyship, carry all three forward?","prompt":"What will you carry?","options":["My voice","My leadership","Spotting bias","My allyship"],"affirm":"Carry your voice, leadership, bias-radar and allyship, and you make every room you enter fairer.","relearn":"Carry your voice, your leadership, your bias-radar and your allyship forward.","persona":"any","source":"carry forward"},
  {"id":"ec-900","cat":"be-the-ally","type":"strike-rewrite","hook":"\"Being an ally means I should speak FOR women, not let them speak.\"","myth":{"un":"A good ally speaks for women instead of letting them speak.","re":"A good ally makes space so they're heard, then steps back; you pass the mic, you don't take it.","why":"Allyship amplifies the person, it doesn't replace their voice."},"relearn":"Allyship passes the mic and makes space; it doesn't speak over the people you're backing.","persona":"any","source":"pass the mic"},
  {"id":"ec-901","cat":"be-the-ally","type":"strike-rewrite","hook":"\"If I'm not the target, it's not my problem to raise.\"","myth":{"un":"If the bias isn't aimed at me, it's not mine to raise.","re":"Allies with no stake in it often carry less risk speaking up, so your voice can land where hers can't.","why":"Not being the target is exactly why your backing helps."},"relearn":"Not being the target is why your voice can land safely; speak up anyway.","persona":"Rohan","source":"whose problem"},
  {"id":"ec-902","cat":"be-the-ally","type":"strike-rewrite","hook":"\"Allyship is a women's-day post and a panel once a year.\"","myth":{"un":"Allyship is a women's-day post and one yearly panel.","re":"Allyship is what you do on the ordinary days nobody's watching: in the meeting, the chat, the hiring call.","why":"The unwatched moments are where allyship is real."},"relearn":"Real allyship is the ordinary unwatched days, not the once-a-year post.","persona":"any","source":"ordinary days"},
  {"id":"ec-903","cat":"be-the-ally","type":"strike-rewrite","hook":"\"If she didn't ask me to step in, I shouldn't.\"","myth":{"un":"If she didn't ask me to step in, I shouldn't.","re":"You can back her in the moment and check in after; just ask quietly what kind of support she'd want next time.","why":"Reading the room plus a quiet check-in beats freezing."},"relearn":"Back her in the moment, then quietly ask what support she'd want next time.","persona":"any","source":"did she ask"},
  {"id":"ec-904","cat":"be-the-ally","type":"strike-rewrite","hook":"\"Once I've apologised for a slip-up, the ally work is done.\"","myth":{"un":"Once I've apologised for a slip, my ally work is done.","re":"An apology is step one; allies change the behaviour next time, not just say sorry for this time.","why":"Saying sorry without changing anything teaches nothing."},"relearn":"An apology is only step one; allyship changes the behaviour, not just words.","persona":"any","source":"after sorry"},
  {"id":"ec-905","cat":"be-the-ally","type":"strike-rewrite","hook":"\"Calling something out always means a big public scene.\"","myth":{"un":"Calling bias out always means a loud public scene.","re":"A quiet word after the meeting, or a private message, often changes more and costs the person less face.","why":"Calling in privately gives a real chance to change."},"relearn":"You can call bias in quietly and privately; it isn't always a public scene.","persona":"any","source":"quiet word"},
  {"id":"ec-910","cat":"be-the-ally","type":"role-play","hook":"In the WhatsApp group, someone forwards a 'women drivers' meme and others pile laughing emojis.","setup":"Cool it down without a lecture. Type:","yourLine":[{"text":"\"Eh, we can do better than these tired ones, na. Let's skip it.\"","best":true},{"text":"Add a laughing emoji so you don't seem touchy"}],"relearn":"A light, no-lecture nudge in a group chat is enough to break a sexist-meme pile-on.","persona":"Rohan","source":"group chat meme"},
  {"id":"ec-911","cat":"be-the-ally","type":"role-play","hook":"At the team lunch, two men start rating a new female intern's looks.","setup":"Shut it down, calmly. Say:","yourLine":[{"text":"\"Let's not rate colleagues like that. She's here to work, same as us.\"","best":true},{"text":"Smile awkwardly and change the topic without a word"}],"relearn":"Naming it plainly stops colleagues being rated on looks; silence lets it continue.","persona":"any","source":"lunch table"},
  {"id":"ec-912","cat":"be-the-ally","type":"role-play","hook":"In a hiring call, someone says a strong woman candidate 'might leave after marriage'.","setup":"Redirect to fairness. Say:","yourLine":[{"text":"\"We don't ask that of men. Let's judge her on the work, like everyone.\"","best":true},{"text":"Let it pass; you don't want to slow the call down"}],"relearn":"Apply the same standard to all candidates; 'might leave after marriage' is bias, not a fair test.","persona":"any","source":"hiring bias"},
  {"id":"ec-913","cat":"be-the-ally","type":"role-play","hook":"A senior keeps calling your woman manager 'beta' in front of the team.","setup":"Correct it lightly. Say:","yourLine":[{"text":"\"It's Priya ma'am, sir, she's leading this one.\"","best":true},{"text":"Say nothing; he's senior and it's awkward"}],"relearn":"A light correction restores a colleague's standing when she's talked down to.","persona":"any","source":"talked down to"},
  {"id":"ec-914","cat":"be-the-ally","type":"role-play","hook":"Your sister's in-laws expect only her to serve tea while the men sit. You're a guest.","setup":"Shift it, gently. Say:","yourLine":[{"text":"\"Bhabhi, sit, I'll bring the tea round, you've done plenty.\"","best":true},{"text":"Stay seated; it's their house, not your call"}],"relearn":"Allyship at home means picking up the unshared work, not waiting to be asked.","persona":"any","source":"tea at home"},
  {"id":"ec-915","cat":"be-the-ally","type":"role-play","hook":"A trans classmate is being deadnamed by a lab partner, 'as a joke'.","setup":"Back them, plainly. Say:","yourLine":[{"text":"\"Their name's Aanya. Let's just use it, yeah?\"","best":true},{"text":"Laugh it off so the group doesn't get tense"}],"relearn":"Using someone's real name and correcting a deadname is concrete, inclusive allyship.","persona":"Zoya","source":"deadnaming"},
  {"id":"ec-916","cat":"be-the-ally","type":"role-play","hook":"A male teammate did the slide deck; your manager thanks 'the girls' for 'making it pretty'.","setup":"Set the record straight. Say:","yourLine":[{"text":"\"Actually Arjun built that deck end to end, full credit to him.\"","best":true},{"text":"Let the wrong credit stand to avoid fuss"}],"relearn":"Correcting mis-credited work, even across gender lines, is even-handed allyship.","persona":"any","source":"wrong credit"},
  {"id":"ec-917","cat":"be-the-ally","type":"role-play","hook":"On the late shift, a woman colleague's auto hasn't come and the area's unsafe.","setup":"Offer real backup. Say:","yourLine":[{"text":"\"I'll wait with you till your ride's here, no rush.\"","best":true},{"text":"Head off; she'll probably be fine on her own"}],"relearn":"Waiting with a colleague until her ride comes is small, practical allyship.","persona":"any","source":"late shift"},
  {"id":"ec-918","cat":"be-the-ally","type":"role-play","hook":"A guy on your team brags he 'never lets his wife work'. Others nod along.","setup":"Open it up, no fight. Say:","yourLine":[{"text":"\"If she wants to work, why hold her back? Her call, na.\"","best":true},{"text":"Nod along so you don't seem preachy"}],"relearn":"A calm question can challenge a controlling norm without turning it into a fight.","persona":"Rohan","source":"never lets her"},
  {"id":"ec-920","cat":"be-the-ally","type":"branch","hook":"Your friend keeps interrupting his girlfriend mid-sentence when you all hang out.","options":[{"text":"Redirect to her now, have the honest word with him later","consequence":"You back her without a public scene.","outcome":"ally","best":true},{"text":"Ignore it; they're a couple, not your business","consequence":"Staying out of it lets the pattern carry on; a quiet word would help.","outcome":"bystander"}],"debrief":"Redirect in the moment, then have the honest word privately; allyship without a scene.","relearn":"Redirect to her in the moment and have the honest word with him privately.","persona":"any","source":"interrupting partner"},
  {"id":"ec-921","cat":"be-the-ally","type":"branch","hook":"A WhatsApp group you're in starts circulating a junior woman's private photo.","options":[{"text":"Refuse to forward, say it's not okay, and tell her","consequence":"You stop the spread and put her in the loop.","outcome":"ally","best":true},{"text":"Just delete it from your own phone","consequence":"Deleting your copy alone doesn't stop the spread; speaking up does.","outcome":"half"}],"debrief":"Don't forward, name that it's wrong, and let her know; allyship protects, it doesn't spectate.","relearn":"Refuse to forward, say it's not okay, and let the person know.","persona":"any","source":"private photo"},
  {"id":"ec-922","cat":"be-the-ally","type":"branch","hook":"Two seniors plan to give the big account to a man 'because she's expecting'.","options":[{"text":"Raise it: ask if she's been asked what she wants","consequence":"You surface the assumption made for her.","outcome":"ally","best":true},{"text":"Assume they know best and stay quiet","consequence":"Deciding for her without asking is the bias; raising it returns her choice.","outcome":"bystander"}],"debrief":"Don't let people decide for her; ask that she be asked. The choice is hers.","relearn":"Surface assumptions made for someone; ask that the person be asked what they want.","persona":"any","source":"deciding for her"},
  {"id":"ec-923","cat":"be-the-ally","type":"branch","hook":"In a group project, the one woman keeps getting handed the notes and the snack run.","options":[{"text":"Propose rotating notes and errands every meeting","consequence":"You make the admin shared, not defaulted.","outcome":"ally","best":true},{"text":"Figure she's just better at it","consequence":"Assuming she's 'naturally' the notetaker is exactly the default to break.","outcome":"bias"}],"debrief":"Office housework is rotated, not defaulted; proposing a rota is everyday allyship.","relearn":"Propose rotating notes and errands so admin is shared, not defaulted to one person.","persona":"any","source":"default notetaker"},
  {"id":"ec-924","cat":"be-the-ally","type":"branch","hook":"You manage a small team. A quiet woman engineer's ideas keep getting skipped in standup.","options":[{"text":"Invite her in by name and credit her ideas openly","consequence":"You build a room where she's heard.","outcome":"ally","best":true},{"text":"Tell her privately to be 'more assertive'","consequence":"Putting it all on her ignores the room; the room should make space.","outcome":"misplaced"}],"debrief":"As the lead, deliberately invite quieter voices and credit them; the room's job, not just hers.","relearn":"Lead by inviting quieter voices in by name and crediting them openly.","persona":"any","source":"lead invites in"},
  {"id":"ec-925","cat":"be-the-ally","type":"branch","hook":"A colleague comes out to you as gay and asks you not to tell anyone yet.","options":[{"text":"Keep it confidential and ask how you can support him","consequence":"You honour his trust and let him lead.","outcome":"ally","best":true},{"text":"Tell a mutual friend 'who'd be supportive'","consequence":"Outing him to anyone, even a kind person, takes a choice that's only his.","outcome":"breach"}],"debrief":"Coming out is his to control; keep the confidence and follow his lead on support.","relearn":"Keep a confidence, never out someone, and ask how they want to be supported.","persona":"Zoya","source":"keep the confidence"},
  {"id":"ec-926","cat":"be-the-ally","type":"branch","hook":"You're on a panel that's all men. The organiser shrugs, 'no women applied'.","options":[{"text":"Push to widen the search and suggest qualified women","consequence":"You help fix the pipeline, not excuse it.","outcome":"ally","best":true},{"text":"Accept 'none applied' and move on","consequence":"'None applied' is usually a search problem; widening it is the ally move.","outcome":"excuse"}],"debrief":"'No women applied' is a search to widen, not a verdict; offer names and reopen it.","relearn":"Widen the search and suggest qualified people rather than accepting 'none applied'.","persona":"any","source":"all-male panel"},
  {"id":"ec-927","cat":"be-the-ally","type":"branch","hook":"Your team jokes that a man who took paternity leave is 'not serious about work'.","options":[{"text":"Push back: caring for a newborn is serious, full stop","consequence":"You defend a man for sharing the care load.","outcome":"ally","best":true},{"text":"Laugh along; it's just banter","consequence":"The 'banter' polices men out of caregiving; pushing back keeps it normal.","outcome":"polices"}],"debrief":"Backing a man who shares the care load is allyship too; equality frees everyone's roles.","relearn":"Defend men who share caregiving; equal roles lift everyone, not just women.","persona":"Rohan","source":"paternity leave"},
  {"id":"ec-928","cat":"be-the-ally","type":"branch","hook":"A woman teammate confides she's being harassed by a vendor. She's scared to report.","options":[{"text":"Believe her, ask what she wants, offer to go with her","consequence":"You support her choice and don't take over.","outcome":"ally","best":true},{"text":"March off to confront the vendor yourself","consequence":"Acting without her say can raise her risk; ask what she wants first.","outcome":"overstep"}],"debrief":"Believe her, follow her lead, and offer to stand beside her, not in front of her.","relearn":"Believe someone harassed, ask what they want, and offer to go with them.","persona":"any","source":"believe her"},
  {"id":"ec-940","cat":"be-the-ally","type":"sort","hook":"Lensy: drop each into the bin. Real ally move, or just looking like one?","items":[{"id":"a","text":"Crediting a colleague's idea by name"},{"id":"b","text":"Adding your logo to a women's-day banner"},{"id":"c","text":"Mentoring a junior through a stretch task"},{"id":"d","text":"Posting a hashtag, changing nothing"},{"id":"e","text":"Rotating who takes the notes"},{"id":"f","text":"Bragging that you 'always support women'"}],"bins":[{"id":"real","label":"Real ally move","valence":"pos"},{"id":"optics","label":"Just optics","valence":"neg"}],"key":{"a":"real","b":"optics","c":"real","d":"optics","e":"real","f":"optics"},"relearn":"Crediting, mentoring and rotating admin are real ally moves; banners, hashtags and bragging are optics.","persona":"any","source":"real vs optics"},
  {"id":"ec-941","cat":"be-the-ally","type":"sort","hook":"Lensy: sort each move. Does it back the person up, or just stand by?","items":[{"id":"a","text":"Handing the floor back to who was cut off"},{"id":"b","text":"Waiting for someone braver to step in"},{"id":"c","text":"Saying 'let her finish' in the moment"},{"id":"d","text":"Telling yourself it's not your place"},{"id":"e","text":"Refusing to forward a cruel message"},{"id":"f","text":"Watching bias, saying nothing"}],"bins":[{"id":"back","label":"Backs them up","valence":"pos"},{"id":"standby","label":"Just stands by","valence":"neg"}],"key":{"a":"back","b":"standby","c":"back","d":"standby","e":"back","f":"standby"},"relearn":"Handing the floor back and refusing to forward back people up; waiting and watching is standing by.","persona":"any","source":"back vs standby"},
  {"id":"ec-942","cat":"be-the-ally","type":"sort","hook":"Lensy: sort each line. Calling in (kind, gives a chance) or just having a go?","items":[{"id":"a","text":"\"That landed off, can we keep it respectful?\""},{"id":"b","text":"\"You're such a sexist, typical.\""},{"id":"c","text":"A quiet private word after the meeting"},{"id":"d","text":"Mocking him in front of everyone"},{"id":"e","text":"\"I don't think that's fair on her.\""},{"id":"f","text":"Cold-shouldering him for a week"}],"bins":[{"id":"callin","label":"Calling in","valence":"tell"},{"id":"havingago","label":"Just having a go","valence":"neg"}],"key":{"a":"callin","b":"havingago","c":"callin","d":"havingago","e":"callin","f":"havingago"},"relearn":"Naming it kindly and a quiet private word call bias in; name-calling and mocking just have a go.","persona":"any","source":"call in vs go at"},
  {"id":"ec-943","cat":"be-the-ally","type":"sort","hook":"Lensy: sort each. Lets the person lead, or takes over their fight?","items":[{"id":"a","text":"Asking what support she'd want"},{"id":"b","text":"Confronting her boss without telling her"},{"id":"c","text":"Following her lead on next steps"},{"id":"d","text":"Speaking over her about her own issue"},{"id":"e","text":"Offering options, letting her choose"},{"id":"f","text":"Making the story about your bravery"}],"bins":[{"id":"lead","label":"Lets her lead","valence":"pos"},{"id":"takeover","label":"Takes over","valence":"neg"}],"key":{"a":"lead","b":"takeover","c":"lead","d":"takeover","e":"lead","f":"takeover"},"relearn":"Asking, following her lead and offering choices lets her lead; confronting without asking and centring yourself takes over.","persona":"any","source":"lead vs takeover"},
  {"id":"ec-944","cat":"be-the-ally","type":"sort","hook":"Lensy: sort each. Shares the load fairly, or quietly dumps it?","items":[{"id":"a","text":"Rotating who organises the team party"},{"id":"b","text":"Always leaving cleanup to the women"},{"id":"c","text":"Taking minutes turn and turn about"},{"id":"d","text":"Defaulting snack runs to the juniors"},{"id":"e","text":"Splitting the boring admin evenly"},{"id":"f","text":"Letting one person carry every errand"}],"bins":[{"id":"shares","label":"Shares the load","valence":"pos"},{"id":"dumps","label":"Dumps it","valence":"neg"}],"key":{"a":"shares","b":"dumps","c":"shares","d":"dumps","e":"shares","f":"dumps"},"relearn":"Rotating parties, minutes and admin shares the load; defaulting cleanup, snacks and errands to one group dumps it.","persona":"any","source":"share vs dump"},
  {"id":"ec-945","cat":"be-the-ally","type":"sort","hook":"Lensy: sort each. Includes everyone, or quietly leaves people out?","items":[{"id":"a","text":"Using a colleague's correct name"},{"id":"b","text":"Planning every team event at a bar"},{"id":"c","text":"Asking the new joiner for their take"},{"id":"d","text":"Inside jokes that freeze out the quiet ones"},{"id":"e","text":"Looping in the remote teammate"},{"id":"f","text":"Talking only to the senior men"}],"bins":[{"id":"includes","label":"Includes everyone","valence":"pos"},{"id":"excludes","label":"Leaves out","valence":"neg"}],"key":{"a":"includes","b":"excludes","c":"includes","d":"excludes","e":"includes","f":"excludes"},"relearn":"Right names, asking newcomers and looping people in includes everyone; senior-only chat leaves people out.","persona":"Zoya","source":"include vs exclude"},
  {"id":"ec-946","cat":"be-the-ally","type":"sort","hook":"Lensy: sort each. A men-as-allies strength, or a tired excuse?","items":[{"id":"a","text":"Sharing the care load at home openly"},{"id":"b","text":"\"It's not a man's place to speak on this\""},{"id":"c","text":"Backing a woman colleague's idea out loud"},{"id":"d","text":"\"I don't want to overstep\" as a dodge"},{"id":"e","text":"Mentoring across genders, no strings"},{"id":"f","text":"\"Equality's not my issue\""}],"bins":[{"id":"strength","label":"Ally strength","valence":"pos"},{"id":"excuse","label":"Tired excuse","valence":"neg"}],"key":{"a":"strength","b":"excuse","c":"strength","d":"excuse","e":"strength","f":"excuse"},"relearn":"Sharing care, backing colleagues and mentoring is ally strength; 'not my place' and 'not my issue' are excuses.","persona":"Rohan","source":"strength vs excuse"},
  {"id":"ec-960","cat":"be-the-ally","type":"spot","hook":"Lensy: in this meeting, spot the two bystander moves that let bias slide.","scene":[{"id":"a","text":"You redirect the question to the woman who was cut off","trick":false},{"id":"b","text":"You credit the junior whose idea got borrowed","trick":false},{"id":"c","text":"You laugh when her point is dismissed as 'emotional'","trick":true},{"id":"d","text":"You stay silent, sure someone else will say it","trick":true},{"id":"e","text":"You ask the quiet teammate for their view","trick":false}],"why":"Laughing along and staying silent are the bystander moves.","relearn":"Laughing along and staying silent let bias slide; allies back people up out loud.","persona":"any","source":"spot the bystander"},
  {"id":"ec-961","cat":"be-the-ally","type":"spot","hook":"Lensy: in this group chat, tap the two messages that cross a line.","scene":[{"id":"a","text":"\"Nice work on the demo, team.\"","trick":false},{"id":"b","text":"\"Forward her photo, it's funny.\"","trick":true},{"id":"c","text":"\"Let's not rate her looks, yeah?\"","trick":false},{"id":"d","text":"\"She only got it 'cause she's a girl.\"","trick":true},{"id":"e","text":"\"Can someone share the meeting notes?\"","trick":false}],"why":"Forwarding her photo and 'only because she's a girl' are the red flags; the rest are fine or are the ally pushing back.","relearn":"Spreading private photos and crediting bias, not merit, are red flags worth calling out.","persona":"any","source":"spot the chat red flags"},
  {"id":"ec-962","cat":"be-the-ally","type":"spot","hook":"Lensy: someone calls this 'allyship'. Tap the two moves that are really just optics.","scene":[{"id":"a","text":"Mentors a junior woman through a tough quarter","trick":false},{"id":"b","text":"Posts a long thread about how much he supports women","trick":true},{"id":"c","text":"Rotates note-taking across the team","trick":false},{"id":"d","text":"Adds 'ally' to his bio, changes nothing at work","trick":true},{"id":"e","text":"Credits her idea openly in the review","trick":false}],"why":"The thread and the bio with no change are optics.","relearn":"Threads and bio tags with no change are optics; mentoring and crediting are real allyship.","persona":"any","source":"spot the optics"},
  {"id":"ec-963","cat":"be-the-ally","type":"spot","hook":"Lensy: a friend wants to 'help' a harassed colleague. Tap the two moves that overstep her.","scene":[{"id":"a","text":"Asks her what support she'd want","trick":false},{"id":"b","text":"Confronts the harasser without telling her","trick":true},{"id":"c","text":"Offers to go with her if she reports","trick":false},{"id":"d","text":"Posts her story to 'raise awareness'","trick":true},{"id":"e","text":"Keeps what she shared in confidence","trick":false}],"why":"Confronting without asking and posting her story take her choice away.","relearn":"Confronting or posting without her say overstep; good allies ask and follow her lead.","persona":"any","source":"spot the overstep"},
  {"id":"ec-964","cat":"be-the-ally","type":"spot","hook":"Lensy: at this hostel, spot the two lines that police a man out of caregiving.","scene":[{"id":"a","text":"\"Good on you for cooking for your roommates.\"","trick":false},{"id":"b","text":"\"Changing nappies? That's the wife's job, bhai.\"","trick":true},{"id":"c","text":"\"Take the paternity leave, you've earned it.\"","trick":false},{"id":"d","text":"\"Real men don't do the dishes.\"","trick":true},{"id":"e","text":"\"Splitting chores fairly just makes sense.\"","trick":false}],"why":"'That's the wife's job' and 'real men don't do dishes' box men out of care.","relearn":"Lines that box men out of caregiving are red flags; shared roles lift everyone.","persona":"Rohan","source":"spot the role-policing"},
  {"id":"ec-965","cat":"be-the-ally","type":"spot","hook":"Lensy: in this hiring call, tap the two comments that are bias dressed as 'practical'.","scene":[{"id":"a","text":"\"Score every candidate on the same rubric.\"","trick":false},{"id":"b","text":"\"She'll leave after marriage, skip her.\"","trick":true},{"id":"c","text":"\"His portfolio is the strongest, clearly.\"","trick":false},{"id":"d","text":"\"A woman can't handle late client calls.\"","trick":true},{"id":"e","text":"\"Ask all of them about availability.\"","trick":false}],"why":"'Leave after marriage' and 'can't handle late calls' are bias.","relearn":"'Practical' guesses about marriage or capability are bias; one fair standard for all isn't.","persona":"any","source":"spot the hiring bias"},
  {"id":"ec-966","cat":"be-the-ally","type":"spot","hook":"Lensy: a teammate is 'including' a queer colleague. Tap the two moves that exclude.","scene":[{"id":"a","text":"Uses the name and pronoun they asked for","trick":false},{"id":"b","text":"Outs them to the team without asking","trick":true},{"id":"c","text":"Invites them into the discussion","trick":false},{"id":"d","text":"Makes them the butt of a 'harmless' joke","trick":true},{"id":"e","text":"Asks how they'd like to be supported","trick":false}],"why":"Outing them and joking at their expense exclude and harm.","relearn":"Outing someone or joking at their expense excludes; right names and inviting in include.","persona":"Zoya","source":"spot the exclusion"},
  {"id":"ec-967","cat":"be-the-ally","type":"spot","hook":"Lensy: in this standup, spot the two habits that quietly shrink a quieter teammate.","scene":[{"id":"a","text":"The lead asks her by name for her view","trick":false},{"id":"b","text":"Someone talks over her the second she starts","trick":true},{"id":"c","text":"Her idea is credited to whoever said it loudest","trick":true},{"id":"d","text":"The lead circles back to her unfinished point","trick":false},{"id":"e","text":"People wait for her to finish before replying","trick":false}],"why":"Talking over her and re-crediting her idea shrink her.","relearn":"Talking over someone and re-crediting their idea shrink them; make space instead.","persona":"any","source":"spot the shrink"},
  {"id":"ec-980","cat":"be-the-ally","type":"match","hook":"Lensy: match each everyday moment to the ally move that fits it.","pairs":[{"left":"She's cut off mid-sentence","right":"Hand the floor back to her"},{"left":"Her idea gets re-credited","right":"Name who actually said it"},{"left":"Notes always land on one person","right":"Propose a rota"},{"left":"A sexist joke in the group","right":"Call it in, lightly"},{"left":"A colleague comes out to you","right":"Keep it confidential"}],"relearn":"Every everyday moment has a concrete ally move; match the moment to the move.","persona":"any","source":"moment to move"},
  {"id":"ec-981","cat":"be-the-ally","type":"match","hook":"Lensy: match each ally move to why it works.","pairs":[{"left":"Amplify her point","right":"The room finally hears it"},{"left":"Call in privately","right":"Gives a real chance to change"},{"left":"Follow her lead","right":"Keeps the choice hers"},{"left":"Mentor a junior","right":"Opens a door for them"},{"left":"Share the admin","right":"Stops one person carrying it"}],"relearn":"Each ally move works for a reason; match the move to why it lands.","persona":"any","source":"move to why"},
  {"id":"ec-982","cat":"be-the-ally","type":"match","hook":"Lensy: match each ally-fail to the better move beside it.","pairs":[{"left":"Speaking for her","right":"Make space so she's heard"},{"left":"Posting a slogan only","right":"Change one real habit"},{"left":"Outing a colleague","right":"Let them choose who knows"},{"left":"Confronting without asking","right":"Ask what support she wants"},{"left":"Laughing along","right":"Say 'that's not on'"}],"relearn":"Every ally-fail has a better move; match the slip to the fix.","persona":"any","source":"fail to fix"},
  {"id":"ec-983","cat":"be-the-ally","type":"match","hook":"Lensy: match each line to the kind of move it is.","pairs":[{"left":"\"Let her finish, please.\"","right":"Backing up in the moment"},{"left":"\"Can we rotate the notes?\"","right":"Sharing the load"},{"left":"\"That was Meera's idea.\"","right":"Crediting fairly"},{"left":"\"Quick word after the call?\"","right":"Calling in privately"},{"left":"\"What would help you here?\"","right":"Following their lead"}],"relearn":"Each everyday line is a kind of ally move; match the line to the move.","persona":"any","source":"line to kind"},
  {"id":"ec-984","cat":"be-the-ally","type":"match","hook":"Lensy: match each setting to one solid ally move for it.","pairs":[{"left":"Team WhatsApp group","right":"Refuse to forward a cruel post"},{"left":"Late shift at office","right":"Wait till her ride arrives"},{"left":"All-male panel line-up","right":"Suggest qualified women"},{"left":"Family dinner at home","right":"Pick up the unshared chores"},{"left":"Hiring shortlist call","right":"Hold one fair standard"}],"relearn":"Every setting has a solid ally move; match the setting to the move that fits.","persona":"any","source":"setting to move"},
  {"id":"ec-990","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"I should wait until I'm 100% sure before I say anything in class.\"","myth":{"un":"I should only speak once I'm completely sure.","re":"You can think out loud; a tentative idea still moves the discussion forward.","why":"Most useful points start as half-formed thoughts."},"relearn":"You can think out loud; a tentative idea still belongs in the room.","persona":"any","source":"thinking out loud"},
  {"id":"ec-991","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"If nobody asks for my opinion, I shouldn't offer it.\"","myth":{"un":"I shouldn't share my view unless I'm asked.","re":"You can offer your view unprompted; you don't need permission to contribute.","why":"Waiting to be invited keeps good ideas unspoken."},"relearn":"You can offer your view unprompted; you don't need an invitation to contribute.","persona":"any","source":"no permission needed"},
  {"id":"ec-992","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"Disagreeing with the group will make me look difficult.\"","myth":{"un":"Disagreeing openly makes me 'difficult'.","re":"You can disagree respectfully; a different view is a contribution, not a problem.","why":"Groups make better calls when dissent is voiced."},"relearn":"You can disagree respectfully; a different view is a contribution, not a flaw.","persona":"any","source":"voicing dissent"},
  {"id":"ec-993","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"If I ask my professor to repeat something, I'll seem slow.\"","myth":{"un":"Asking the professor to repeat makes me look slow.","re":"You can ask for a point to be repeated; clarifying is what sharp learners do.","why":"The ones who ask usually understand the most."},"relearn":"Asking to clarify isn't weakness; it's how sharp learners learn.","persona":"Deepak","source":"asking to clarify"},
  {"id":"ec-994","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"My accent or English isn't polished, so I should stay quiet.\"","myth":{"un":"My English isn't polished enough to speak up.","re":"Your idea matters more than a perfect accent; speak in the words you have.","why":"Content carries further than polish."},"relearn":"Your idea matters more than perfect English; speak in the words you have.","persona":"Deepak","source":"content over polish"},
  {"id":"ec-995","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"In a room full of seniors, a fresher like me should just listen.\"","myth":{"un":"As the most junior person, I should only listen.","re":"You can contribute from any seat; a fresh perspective is often exactly what's missing.","why":"Newcomers spot what regulars stop noticing."},"relearn":"You can contribute from any seat; a fresh perspective is worth voicing.","persona":"any","source":"junior voice"},
  {"id":"ec-996","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"If my voice shakes when I speak, everyone will know I'm not confident.\"","myth":{"un":"A shaky voice means I'm not good enough to speak.","re":"You can speak through nerves; a shaky voice still delivers a strong point.","why":"Nervousness fades the more you do it."},"relearn":"You can speak through nerves; a shaky voice still carries a strong point.","persona":"any","source":"speaking through nerves"},
  {"id":"ec-997","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"Once I've started talking, if someone frowns I should just stop.\"","myth":{"un":"If a listener frowns, I should cut my point short.","re":"You can finish your point; one person's expression isn't a verdict on your idea.","why":"A frown can mean concentration, not disapproval."},"relearn":"You can finish your point; one frown isn't a verdict on your idea.","persona":"any","source":"finishing your point"},
  {"id":"ec-998","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"My family says assertive girls don't get along, so I should soften up.\"","myth":{"un":"Assertive girls 'don't get along', so I should shrink.","re":"You can be both warm and assertive; speaking up doesn't make you unlikeable.","why":"Respect and directness go together fine."},"relearn":"You can be warm and assertive at once; speaking up doesn't make you unlikeable.","persona":"Aarti","source":"warm and assertive"},
  {"id":"ec-999","cat":"claim-your-voice","type":"strike-rewrite","hook":"\"If I voice an idea and it gets rejected, I shouldn't have spoken at all.\"","myth":{"un":"A rejected idea means I shouldn't have spoken.","re":"You can voice ideas that don't land; contributing is how you get better, not a failure.","why":"Every confident speaker has floated ideas that went nowhere."},"relearn":"A rejected idea isn't a mistake; contributing is how your voice grows.","persona":"any","source":"rejection isn't failure"},
  {"id":"ec-1000","cat":"claim-your-voice","type":"role-play","hook":"In a project meeting, two people keep talking over your half-finished point.","setup":"Reclaim your turn, steadily. Say:","yourLine":[{"text":"\"Let me just finish the point I started, then I'd love your thoughts.\"","best":true},{"text":"Trail off and wait for them to stop"}],"relearn":"You can steadily reclaim your turn instead of trailing off.","persona":"any","source":"reclaiming your turn"},
  {"id":"ec-1001","cat":"claim-your-voice","type":"role-play","hook":"A senior repeats your idea as their own and the room nods at them.","setup":"Claim your credit, calmly. Say:","yourLine":[{"text":"\"Glad that landed, it's the point I raised earlier; here's where I'd take it next.\"","best":true},{"text":"Say nothing and let it go"}],"relearn":"You can calmly claim credit for your idea and build on it.","persona":"Aarti","source":"claiming credit"},
  {"id":"ec-1002","cat":"claim-your-voice","type":"role-play","hook":"You catch yourself starting every sentence with 'sorry, this might be silly, but...'","setup":"Drop the disclaimer. Say:","yourLine":[{"text":"\"Here's what I think we should do.\"","best":true},{"text":"\"Sorry, this is probably silly, but maybe...\""}],"relearn":"Drop the disclaimers; state your point directly.","persona":"any","source":"dropping disclaimers"},
  {"id":"ec-1003","cat":"claim-your-voice","type":"role-play","hook":"In a hostel committee meeting, a decision's being rushed before you've spoken.","setup":"Hold space for your point. Say:","yourLine":[{"text":"\"Before we lock this in, I'd like to add one thing.\"","best":true},{"text":"Let it pass and bring it up never"}],"relearn":"You can ask the room to pause so your point is heard.","persona":"any","source":"holding space"},
  {"id":"ec-1004","cat":"claim-your-voice","type":"role-play","hook":"At your internship, your manager asks 'any questions?' and you do have one.","setup":"Ask it plainly. Say:","yourLine":[{"text":"\"Yes, one: how should I prioritise these two tasks?\"","best":true},{"text":"\"No, all clear\" while still unsure"}],"relearn":"Ask the question you actually have, plainly.","persona":"any","source":"asking at work"},
  {"id":"ec-1005","cat":"claim-your-voice","type":"role-play","hook":"A classmate keeps finishing your sentences for you in the group presentation.","setup":"Take your part back, lightly. Say:","yourLine":[{"text":"\"I've got this bit, thanks; I'll take it from here.\"","best":true},{"text":"Let them keep finishing your lines"}],"relearn":"You can lightly take your part back when someone speaks over you.","persona":"any","source":"taking your part back"},
  {"id":"ec-1006","cat":"claim-your-voice","type":"role-play","hook":"In a seminar, someone says 'good question' then answers a different question than yours.","setup":"Bring it back to yours. Say:","yourLine":[{"text":"\"Thanks, though my actual question was about the second part.\"","best":true},{"text":"Nod as if that answered it"}],"relearn":"You can redirect back to the question you actually asked.","persona":"any","source":"redirecting"},
  {"id":"ec-1007","cat":"claim-your-voice","type":"role-play","hook":"Your idea was dismissed earlier; now the discussion has circled back to it.","setup":"Re-table it, with confidence. Say:","yourLine":[{"text":"\"This is the idea I raised before; I think it's worth a real look now.\"","best":true},{"text":"Assume the moment has passed"}],"relearn":"You can re-table a dismissed idea when its moment comes round.","persona":"Aarti","source":"re-tabling an idea"},
  {"id":"ec-1008","cat":"claim-your-voice","type":"role-play","hook":"You're asked to introduce yourself to a panel and your instinct is to downplay your work.","setup":"State your work plainly. Say:","yourLine":[{"text":"\"I led the campus drive and grew it to 200 volunteers.\"","best":true},{"text":"\"I just helped out with a small thing, nothing much.\""}],"relearn":"State your work plainly; don't pre-shrink your own achievements.","persona":"any","source":"owning your work"},
  {"id":"ec-1009","cat":"claim-your-voice","type":"role-play","hook":"A teammate asks for your honest opinion on a plan you have doubts about.","setup":"Give the honest version, kindly. Say:","yourLine":[{"text":"\"Honestly, I see a gap in step three; can we rework it together?\"","best":true},{"text":"\"It's fine, whatever you all think is best.\""}],"relearn":"You can give an honest opinion kindly instead of agreeing to keep the peace.","persona":"any","source":"honest opinion"},
  {"id":"ec-1010","cat":"claim-your-voice","type":"branch","hook":"You raise a point and a louder voice immediately talks over you mid-sentence.","options":[{"text":"Calmly continue: 'Let me finish, then over to you'","consequence":"You hold the floor without conflict and your point lands.","outcome":"steady","best":true},{"text":"Stop and let the louder voice carry on","consequence":"Calmly continuing holds the floor; stopping teaches the room your turn can be taken."}],"debrief":"You don't have to win volume; you can calmly hold your turn until your point is finished.","relearn":"When talked over, calmly hold your turn rather than yielding it.","persona":"any","source":"holding the floor"},
  {"id":"ec-1011","cat":"claim-your-voice","type":"branch","hook":"You have a counter-point to your professor's argument in a packed lecture.","options":[{"text":"Raise it respectfully as a genuine question","consequence":"You contribute and the discussion deepens.","outcome":"engaged","best":true},{"text":"Swallow it to avoid standing out","consequence":"Raising it respectfully deepens the discussion; swallowing it keeps a real idea unspoken."}],"debrief":"A respectful counter-point isn't disrespect; it's exactly the kind of thinking a seminar is for.","relearn":"You can voice a respectful counter-point; it's a contribution, not defiance.","persona":"any","source":"respectful challenge"},
  {"id":"ec-1012","cat":"claim-your-voice","type":"branch","hook":"In a salary or stipend talk, you're tempted to accept the first number without a word.","options":[{"text":"Ask plainly whether there's room to discuss it","consequence":"You advocate for yourself and open the conversation.","outcome":"advocated","best":true},{"text":"Accept silently so you don't seem greedy","consequence":"Asking if there's room is fair; silent acceptance leaves your value unspoken."}],"debrief":"Asking whether a number is flexible isn't greedy; it's ordinary self-advocacy.","relearn":"You can ask whether an offer is flexible; that's self-advocacy, not greed.","persona":"any","source":"negotiating"},
  {"id":"ec-1013","cat":"claim-your-voice","type":"branch","hook":"You freeze before speaking, worried your idea isn't fully worked out yet.","options":[{"text":"Share it as a draft: 'Here's a rough idea...'","consequence":"You get input and shape it together.","outcome":"shared","best":true},{"text":"Wait until it's perfect, then never share it","consequence":"Sharing a rough idea invites help; waiting for perfect usually means staying silent."}],"debrief":"Framing an idea as a draft lets you contribute now and improve it with the room's help.","relearn":"You can share an idea as a draft instead of waiting for it to be perfect.","persona":"any","source":"sharing a draft"},
  {"id":"ec-1014","cat":"claim-your-voice","type":"branch","hook":"During a group viva, the examiner keeps addressing your male teammate, not you.","options":[{"text":"Step in: 'I'll take that one, it was my section'","consequence":"You claim your part of the work clearly.","outcome":"claimed","best":true},{"text":"Let your teammate field everything","consequence":"Stepping in claims your work; staying quiet lets your contribution go unseen."}],"debrief":"When you're defaulted past, you can calmly step in and claim the part of the work that's yours.","relearn":"When attention defaults past you, you can step in and claim your work.","persona":"Aarti","source":"claiming your section"},
  {"id":"ec-1015","cat":"claim-your-voice","type":"branch","hook":"You want to volunteer to present, but three others raise hands first and you hesitate.","options":[{"text":"Raise your hand too: 'I'd like a turn as well'","consequence":"You put yourself forward and get the practice.","outcome":"forward","best":true},{"text":"Lower your hand since others want it","consequence":"Putting yourself forward gets you the practice; standing down keeps you on the sidelines."}],"debrief":"Others wanting a turn doesn't cancel yours; you can put yourself forward too.","relearn":"You can put yourself forward even when others already have.","persona":"any","source":"putting yourself forward"},
  {"id":"ec-1016","cat":"claim-your-voice","type":"branch","hook":"A WhatsApp study group is deciding the project topic and your suggestion got skipped.","options":[{"text":"Re-post it clearly: 'Adding my idea back in...'","consequence":"Your suggestion gets a fair hearing.","outcome":"reposted","best":true},{"text":"Assume nobody liked it and drop it","consequence":"Re-posting gives your idea a fair hearing; assuming rejection drops a good option."}],"debrief":"A skipped message often just got lost, not rejected; put your idea back on the table.","relearn":"You can put a skipped idea back on the table instead of assuming it was rejected.","persona":"any","source":"re-posting an idea"},
  {"id":"ec-1017","cat":"claim-your-voice","type":"branch","hook":"You're asked to give feedback to a senior on their plan, and you spotted a real flaw.","options":[{"text":"Name it respectfully with a suggested fix","consequence":"You're useful and your judgement is seen.","outcome":"useful","best":true},{"text":"Only say nice things to stay safe","consequence":"Naming the flaw with a fix is genuinely useful; only-nice feedback hides what you saw."}],"debrief":"Honest, kind feedback to a senior shows judgement; you don't have to flatter to stay safe.","relearn":"You can name a real flaw respectfully; honest feedback shows your judgement.","persona":"any","source":"upward feedback"},
  {"id":"ec-1018","cat":"claim-your-voice","type":"branch","hook":"You get an idea mid-meeting but tell yourself it's probably obvious to everyone.","options":[{"text":"Say it anyway: 'Maybe obvious, but worth saying...'","consequence":"It often wasn't obvious, and you add value.","outcome":"voiced","best":true},{"text":"Keep it in, sure it's too basic","consequence":"Saying it often surfaces something others missed; keeping it in assumes a value it hasn't earned."}],"debrief":"The 'too obvious' idea is frequently the one nobody had actually said; voice it.","relearn":"You can voice an idea you fear is 'too obvious'; it often isn't.","persona":"any","source":"the obvious idea"},
  {"id":"ec-1019","cat":"claim-your-voice","type":"branch","hook":"Family pressure says a 'good girl' stays quiet, but you want to speak at a community meeting.","options":[{"text":"Prepare one clear point and make it","consequence":"You're heard, and it gets easier next time.","outcome":"heard","best":true},{"text":"Stay silent to be the 'good girl'","consequence":"Making one clear point builds your voice; staying silent to fit a label keeps you unheard."}],"debrief":"Your right to speak in a public room isn't cancelled by an old 'good girl' script.","relearn":"You can speak in public rooms; an old 'stay quiet' script doesn't bind you.","persona":"Aarti","source":"public voice"},
  {"id":"ec-1020","cat":"claim-your-voice","type":"branch","hook":"You realise you've apologised three times in one email for things that need no apology.","options":[{"text":"Rewrite it: cut the sorries, state the ask","consequence":"Your message reads clear and confident.","outcome":"clear","best":true},{"text":"Send it as is, sorries and all","consequence":"Cutting needless sorries reads confident; leaving them in quietly shrinks your ask."}],"debrief":"Over-apologising in writing dilutes your message; a clear ask lands better.","relearn":"You can cut needless apologies from your writing; a clear ask carries further.","persona":"any","source":"confident writing"},
  {"id":"ec-1021","cat":"claim-your-voice","type":"branch","hook":"You're invited to a panel but think 'they probably asked me by mistake.'","options":[{"text":"Accept and prepare; you were asked for a reason","consequence":"You take the seat and grow into it.","outcome":"accepted","best":true},{"text":"Decline, sure you don't really belong there","consequence":"Preparing lets you grow; declining over impostor doubt forfeits a real chance."}],"debrief":"Impostor doubt isn't evidence; if you were invited, your voice was wanted there.","relearn":"You can accept a seat at the table; impostor doubt isn't proof you don't belong.","persona":"Deepak","source":"impostor doubt"},
  {"id":"ec-1022","cat":"claim-your-voice","type":"branch","hook":"You want to correct a factual error the group made, but worry about seeming pushy.","options":[{"text":"Offer the correction neutrally, with the source","consequence":"The group gets it right and trusts your input.","outcome":"trusted","best":true},{"text":"Let the error stand to avoid friction","consequence":"A neutral correction helps everyone; letting an error stand to avoid friction costs the group."}],"debrief":"A calm, sourced correction is a contribution, not pushiness; you can offer it.","relearn":"You can offer a calm, sourced correction; that's helpful, not pushy.","persona":"any","source":"calm correction"},
  {"id":"ec-1023","cat":"claim-your-voice","type":"sort","hook":"Sort: claims your voice, or hands it away?","items":[{"id":"a","text":"Finishing your sentence when cut off"},{"id":"b","text":"Trailing into '...but it's probably nothing'"},{"id":"c","text":"Stating your ask without three sorries"},{"id":"d","text":"Going silent when one person frowns"},{"id":"e","text":"Re-tabling an idea that got skipped"},{"id":"f","text":"Letting someone finish your point for you"}],"bins":[{"id":"claims","label":"Claims it","valence":"pos"},{"id":"hands","label":"Hands it away","valence":"neg"}],"key":{"a":"claims","b":"hands","c":"claims","d":"hands","e":"claims","f":"hands"},"relearn":"Finishing, stating plainly and re-tabling claim your voice; trailing off, going silent and yielding hand it away.","persona":"any","source":"voice moves"},
  {"id":"ec-1024","cat":"claim-your-voice","type":"sort","hook":"Sort: a confident opener, or a self-shrinking one?","items":[{"id":"a","text":"\"Here's what I'd suggest...\""},{"id":"b","text":"\"This is probably a stupid question...\""},{"id":"c","text":"\"I think the data points to...\""},{"id":"d","text":"\"Sorry to bother, ignore me if silly...\""},{"id":"e","text":"\"I'd like to add a point.\""},{"id":"f","text":"\"I'm no expert, but maybe, possibly...\""}],"bins":[{"id":"confident","label":"Confident","valence":"pos"},{"id":"shrinking","label":"Self-shrinking","valence":"neg"}],"key":{"a":"confident","b":"shrinking","c":"confident","d":"shrinking","e":"confident","f":"shrinking"},"relearn":"Direct openers claim your point; 'stupid question' and 'sorry, ignore me' openers shrink it before you start.","persona":"any","source":"openers"},
  {"id":"ec-1025","cat":"claim-your-voice","type":"sort","hook":"Sort: builds your speaking confidence, or drains it?","items":[{"id":"a","text":"Speaking up once early in a discussion"},{"id":"b","text":"Replaying one awkward line for hours"},{"id":"c","text":"Noting a point landed well"},{"id":"d","text":"Comparing yourself to the loudest person"},{"id":"e","text":"Practising the line before you say it"},{"id":"f","text":"Assuming everyone judged you harshly"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"drains","label":"Drains it","valence":"neg"}],"key":{"a":"builds","b":"drains","c":"builds","d":"drains","e":"builds","f":"drains"},"relearn":"Speaking early, noting wins and rehearsing build confidence; replaying flaws and harsh comparison drain it.","persona":"any","source":"confidence loop"},
  {"id":"ec-1026","cat":"claim-your-voice","type":"sort","hook":"Sort: a reason to apply now, or a false reason to wait?","items":[{"id":"a","text":"You meet the core skills"},{"id":"b","text":"You lack one 'nice to have' on the list"},{"id":"c","text":"You can learn the rest on the job"},{"id":"d","text":"You don't feel fully ready yet"},{"id":"e","text":"You've done similar work before"},{"id":"f","text":"Someone 'more qualified' might apply"}],"bins":[{"id":"apply","label":"Apply now","valence":"pos"},{"id":"wait","label":"False reason to wait","valence":"neg"}],"key":{"a":"apply","b":"wait","c":"apply","d":"wait","e":"apply","f":"wait"},"relearn":"Core skills, transferable experience and on-the-job learning say apply; 'not fully ready' is a false brake.","persona":"any","source":"apply or wait"},
  {"id":"ec-1027","cat":"claim-your-voice","type":"sort","hook":"Sort: helps your point land, or buries it?","items":[{"id":"a","text":"Leading with your main point first"},{"id":"b","text":"Burying it after a long apology"},{"id":"c","text":"Pausing instead of saying 'um, like'"},{"id":"d","text":"Mumbling so no one's put out"},{"id":"e","text":"Looking up and speaking to the room"},{"id":"f","text":"Talking to your notes the whole time"}],"bins":[{"id":"lands","label":"Helps it land","valence":"pos"},{"id":"buries","label":"Buries it","valence":"neg"}],"key":{"a":"lands","b":"buries","c":"lands","d":"buries","e":"lands","f":"buries"},"relearn":"Leading with the point, pausing and addressing the room land it; long apologies and mumbling bury it.","persona":"any","source":"delivery"},
  {"id":"ec-1028","cat":"claim-your-voice","type":"sort","hook":"Sort: a fair reason to stay quiet, or just self-silencing?","items":[{"id":"a","text":"You genuinely have nothing to add yet"},{"id":"b","text":"You're junior so you 'shouldn't'"},{"id":"c","text":"You're still listening to understand"},{"id":"d","text":"Your idea 'might sound silly'"},{"id":"e","text":"The point's already been well made"},{"id":"f","text":"A man hasn't spoken first yet"}],"bins":[{"id":"fair","label":"Fair to stay quiet","valence":"neutral"},{"id":"silencing","label":"Self-silencing","valence":"neg"}],"key":{"a":"fair","b":"silencing","c":"fair","d":"silencing","e":"fair","f":"silencing"},"relearn":"Nothing to add yet, still listening, or already-made: fair quiet. 'Too junior', 'too silly', 'wait for a man': self-silencing.","persona":"any","source":"quiet or silenced"},
  {"id":"ec-1029","cat":"claim-your-voice","type":"sort","hook":"Sort: takes up your fair space, or tramples others'?","items":[{"id":"a","text":"Stating your point, then handing over"},{"id":"b","text":"Talking over whoever's mid-sentence"},{"id":"c","text":"Asking a quiet teammate their view"},{"id":"d","text":"Repeating yourself till others give up"},{"id":"e","text":"Making your point once, clearly"},{"id":"f","text":"Dismissing replies before they finish"}],"bins":[{"id":"fair","label":"Fair space","valence":"pos"},{"id":"tramples","label":"Tramples others","valence":"neg"}],"key":{"a":"fair","b":"tramples","c":"fair","d":"tramples","e":"fair","f":"tramples"},"relearn":"Confidence takes your space and leaves room for others; talking over and steamrolling isn't confidence, it's trampling.","persona":"any","source":"fair space"},
  {"id":"ec-1030","cat":"claim-your-voice","type":"sort","hook":"Sort: a real confidence-builder you can do, or an empty quick-fix?","items":[{"id":"a","text":"Preparing one solid point before class"},{"id":"b","text":"Waiting to magically 'feel ready'"},{"id":"c","text":"Speaking up in low-stakes chats first"},{"id":"d","text":"Comparing to a highlight reel online"},{"id":"e","text":"Recalling a time you were heard"},{"id":"f","text":"Repeating 'I'm confident' but never speaking"}],"bins":[{"id":"real","label":"Real builder","valence":"pos"},{"id":"empty","label":"Empty quick-fix","valence":"neg"}],"key":{"a":"real","b":"empty","c":"real","d":"empty","e":"real","f":"empty"},"relearn":"Preparing, practising in low stakes and recalling wins build real confidence; waiting to 'feel ready' and slogans don't.","persona":"any","source":"real vs quick-fix"},
  {"id":"ec-1031","cat":"claim-your-voice","type":"reflect","hook":"Lensy: your half-formed thought is still worth saying out loud. Sit with that?","prompt":"What do you think?","options":["Yes","It still counts","I'll say it"],"affirm":"A rough, half-formed idea is still a contribution; you don't have to have it perfect to belong in the talk.","relearn":"A half-formed thought is still worth voicing.","persona":"any","source":"half-formed is fine"},
  {"id":"ec-1032","cat":"claim-your-voice","type":"reflect","hook":"Lensy: being talked over isn't a sign to give up your turn. Notice that?","prompt":"What comes up?","options":["Noticed","My turn stands","I can step back in"],"affirm":"If you're cut off, your turn doesn't vanish; you can calmly step back in and finish what you started.","relearn":"Being talked over doesn't end your turn; you can step back in.","persona":"any","source":"your turn stands"},
  {"id":"ec-1033","cat":"claim-your-voice","type":"reflect","hook":"Lensy: you don't need a perfect gap to speak; you can make one. Try believing it?","prompt":"How does that land?","options":["It lands","I can make a gap","Okay"],"affirm":"Perfect openings rarely come; a simple 'can I add something here?' makes the space you need to speak.","relearn":"You can make a gap to speak rather than wait for a perfect one.","persona":"any","source":"making a gap"},
  {"id":"ec-1034","cat":"claim-your-voice","type":"reflect","hook":"Lensy: every 'sorry' you cut makes your point a little stronger. Worth trying?","prompt":"What do you think?","options":["Worth it","I'll cut a sorry","Yes"],"affirm":"You don't owe an apology for taking up space; dropping the needless 'sorry' lets your real point stand.","relearn":"Dropping needless apologies makes your point stronger.","persona":"any","source":"fewer sorries"},
  {"id":"ec-1035","cat":"claim-your-voice","type":"reflect","hook":"Lensy: the room should make space for you, not assume you've nothing to say. Take that in?","prompt":"What comes up?","options":["Taken in","I belong","The space is mine too"],"affirm":"Quiet isn't emptiness; a fair room makes space for you, and your ideas are part of what it's for.","relearn":"The room should make space for you, not assume you have nothing to add.","persona":"any","source":"space is yours"},
  {"id":"ec-1036","cat":"claim-your-voice","type":"reflect","hook":"Lensy: your voice gets steadier every single time you use it. Let that encourage you?","prompt":"How does it sit?","options":["Encouraging","Steadier each time","Yes"],"affirm":"Confidence isn't a thing you wait to feel; it grows each time you speak, a little easier than the last.","relearn":"Your voice gets steadier each time you use it.","persona":"any","source":"steadier each time"},
  {"id":"ec-1037","cat":"claim-your-voice","type":"reflect","hook":"Lensy: you don't have to earn your seat twice just because you're the youngest. Settle into it?","prompt":"What do you think?","options":["Settled","I earned my seat","I belong here"],"affirm":"Being the newest or youngest in the room doesn't make your voice worth less; you're in the room for a reason.","relearn":"You don't have to keep re-earning your place to deserve a voice.","persona":"Deepak","source":"your seat is earned"},
  {"id":"ec-1038","cat":"claim-your-voice","type":"reflect","hook":"Lensy: an idea that didn't land isn't proof you should stay quiet. Reframe it?","prompt":"How does that feel?","options":["Reframed","Still worth speaking","Okay"],"affirm":"Ideas miss sometimes; that's how speaking works, not a sign to go silent. The next one might be the one that lands.","relearn":"An idea that didn't land isn't a reason to stop speaking.","persona":"any","source":"keep speaking"},
  {"id":"ec-1039","cat":"claim-your-voice","type":"spot","hook":"Your own self-talk before a meeting. Spot the two lines that are silencing you.","scene":[{"id":"a","text":"\"I'll lead with my main point first.\"","trick":false},{"id":"b","text":"\"My question's probably too stupid to ask.\"","trick":true},{"id":"c","text":"\"I've prepared one solid thing to say.\"","trick":false},{"id":"d","text":"\"I should wait till someone asks me.\"","trick":true},{"id":"e","text":"\"A rough idea still counts.\"","trick":false}],"why":"'Too stupid to ask' and 'wait till someone asks me' are the self-silencing lines; the rest claim your voice.","relearn":"'Too stupid to ask' and 'wait to be asked' are self-silencing scripts to drop.","persona":"any","source":"silencing self-talk"},
  {"id":"ec-1040","cat":"claim-your-voice","type":"spot","hook":"A pep email on speaking up. Spot the two tips that secretly shrink you.","scene":[{"id":"a","text":"\"State your point, then invite others.\"","trick":false},{"id":"b","text":"\"Soften everything with 'sorry, just'.\"","trick":true},{"id":"c","text":"\"Finish your sentence if cut off.\"","trick":false},{"id":"d","text":"\"Only speak once you're totally certain.\"","trick":true},{"id":"e","text":"\"A draft idea is fine to share.\"","trick":false}],"why":"'Always soften with sorry' and 'wait till certain' are the shrinking lines hiding as advice.","relearn":"'Always soften with sorry' and 'wait till certain' are bad advice that shrinks your voice.","persona":"any","source":"bad pep advice"},
  {"id":"ec-1041","cat":"claim-your-voice","type":"spot","hook":"A meeting transcript. Spot the two moments your voice is taken.","scene":[{"id":"a","text":"You: 'My data,' Colleague: 'Anyway, moving on.'","trick":true},{"id":"b","text":"Chair: 'Let's hear you finish that.'","trick":false},{"id":"c","text":"Senior repeats your idea; room credits them.","trick":true},{"id":"d","text":"Teammate: 'Good catch, that was your idea.'","trick":false},{"id":"e","text":"Chair: 'Anyone we haven't heard yet?'","trick":false}],"why":"Being cut off mid-point and having your idea re-credited are the moments your voice is taken.","relearn":"Being cut off and having your idea re-credited are voice being taken; reclaim both.","persona":"any","source":"voice being taken"},
  {"id":"ec-1042","cat":"claim-your-voice","type":"spot","hook":"Thoughts on a job posting. Spot the two talking you out of applying.","scene":[{"id":"a","text":"\"I've got the core skills.\"","trick":false},{"id":"b","text":"\"Missing one bullet, so I can't apply.\"","trick":true},{"id":"c","text":"\"I can learn the last bit on the job.\"","trick":false},{"id":"d","text":"\"Someone more polished will get it.\"","trick":true},{"id":"e","text":"\"My past project fits this well.\"","trick":false}],"why":"'Missing one bullet so I can't' and 'someone more polished will get it' are the false brakes.","relearn":"'Missing one requirement' and 'someone better will apply' are false reasons not to apply.","persona":"any","source":"application self-talk"},
  {"id":"ec-1043","cat":"claim-your-voice","type":"spot","hook":"A 'confidence' reel gives speaking tips. Spot the two that are actually arrogance, not confidence.","scene":[{"id":"a","text":"\"Make your point, then hand over.\"","trick":false},{"id":"b","text":"\"Talk over anyone slower than you.\"","trick":true},{"id":"c","text":"\"Pull a quiet teammate into the talk.\"","trick":false},{"id":"d","text":"\"Repeat yourself till they give in.\"","trick":true},{"id":"e","text":"\"Say it once, clearly, and stop.\"","trick":false}],"why":"Talking over slower people and repeating till they give in are trampling others, not confidence.","relearn":"Confidence leaves room for others; talking over and wearing people down is just trampling.","persona":"any","source":"confidence vs arrogance"},
  {"id":"ec-1044","cat":"claim-your-voice","type":"spot","hook":"A friend's 'advice' on a group project. Spot the two lines telling you to shrink.","scene":[{"id":"a","text":"\"Claim the part of the work you did.\"","trick":false},{"id":"b","text":"\"Let the loud guy talk, it's easier.\"","trick":true},{"id":"c","text":"\"Ask to present your own section.\"","trick":false},{"id":"d","text":"\"Don't correct the senior, just nod.\"","trick":true},{"id":"e","text":"\"Put a skipped idea back in.\"","trick":false}],"why":"'Let the loud guy talk' and 'don't correct, just nod' tell you to give up your voice.","relearn":"'Let the loud one talk' and 'just nod, don't correct' are advice to shrink; claim your part.","persona":"any","source":"friend's shrinking advice"},
  {"id":"ec-1045","cat":"claim-your-voice","type":"spot","hook":"Your inner monologue at an internship intro. Spot the two thoughts undercutting you.","scene":[{"id":"a","text":"\"I'll state what I led, plainly.\"","trick":false},{"id":"b","text":"\"I'll say I just helped a bit.\"","trick":true},{"id":"c","text":"\"My questions are worth asking here.\"","trick":false},{"id":"d","text":"\"I was probably picked by mistake.\"","trick":true},{"id":"e","text":"\"I'll speak up if I spot a gap.\"","trick":false}],"why":"'I just helped a bit' and 'picked by mistake' are the undercutting thoughts; the rest own your place.","relearn":"'I just helped' and 'picked by mistake' undercut you; you earned your place.","persona":"Deepak","source":"intro self-talk"},
  {"id":"ec-1046","cat":"claim-your-voice","type":"spot","hook":"A senior's tips to a nervous fresher. Spot the two that keep her quiet.","scene":[{"id":"a","text":"\"Prepare one point and lead with it.\"","trick":false},{"id":"b","text":"\"Better silent than risk a wrong answer.\"","trick":true},{"id":"c","text":"\"Ask if you didn't follow something.\"","trick":false},{"id":"d","text":"\"Wait years before you give opinions.\"","trick":true},{"id":"e","text":"\"Speaking gets easier with practice.\"","trick":false}],"why":"'Stay silent over risk' and 'wait years for opinions' keep her quiet, dressed as caution.","relearn":"'Silence beats a wrong answer' and 'wait years to speak' silence, they don't protect.","persona":"any","source":"silencing 'mentoring'"},
  {"id":"ec-1047","cat":"claim-your-voice","type":"match","hook":"Match the self-shrinking habit to the confident move that replaces it.","pairs":[{"left":"Trailing off mid-point","right":"Finishing your sentence clearly"},{"left":"Padding with 'sorry, just'","right":"Stating the ask directly"},{"left":"Waiting for a perfect gap","right":"Making a gap to speak"},{"left":"Going silent when cut off","right":"Calmly reclaiming your turn"},{"left":"Skipping a job you mostly fit","right":"Applying without every box ticked"}],"relearn":"Each shrinking habit has a confident move that replaces it; swap them one at a time.","persona":"any","source":"swap the habit"},
  {"id":"ec-1048","cat":"claim-your-voice","type":"match","hook":"Match the tricky moment to a line that reclaims your voice in it.","pairs":[{"left":"Talked over mid-sentence","right":"\"Let me just finish my point.\""},{"left":"Your idea re-credited","right":"\"That's the point I raised earlier.\""},{"left":"Decision rushed before you spoke","right":"\"Before we lock it in, one thing.\""},{"left":"Attention defaults past you","right":"\"I'll take that, it was my section.\""},{"left":"You doubt your half-idea","right":"\"Here's a rough idea to build on.\""}],"relearn":"For each moment that takes your voice, there's a calm line that reclaims it.","persona":"any","source":"moment to line"},
  {"id":"ec-1049","cat":"claim-your-voice","type":"match","hook":"Match the limiting belief to the truth that frees your voice.","pairs":[{"left":"\"Half-formed ideas don't count\"","right":"They still move the talk forward"},{"left":"\"Confidence is something you're born with\"","right":"It grows each time you speak"},{"left":"\"Assertive women are bossy\"","right":"It's the same as confidence in anyone"},{"left":"\"I need every box ticked\"","right":"You rarely do; apply anyway"},{"left":"\"Being talked over ends my turn\"","right":"You can calmly step back in"}],"relearn":"Each belief that shrinks your voice has a truer counter that frees it.","persona":"any","source":"belief to truth"},
  {"id":"ec-1050","cat":"claim-your-voice","type":"match","hook":"Match the confident phrasing to the over-apologising version it replaces.","pairs":[{"left":"\"Here's what I'd suggest.\"","right":"\"Sorry, this is probably silly...\""},{"left":"\"I'd like to add a point.\"","right":"\"Ignore me if this is dumb...\""},{"left":"\"My question's about step two.\"","right":"\"Sorry, quick stupid one...\""},{"left":"\"I disagree, and here's why.\"","right":"\"I'm no expert, but maybe...\""},{"left":"\"I led this part.\"","right":"\"I just helped a tiny bit...\""}],"relearn":"Each over-apologising opener has a direct version that carries your point further.","persona":"any","source":"direct vs apologetic"},
  {"id":"ec-1051","cat":"claim-your-voice","type":"match","hook":"Match the situation to the move that keeps your voice in the room.","pairs":[{"left":"You froze and stayed silent last time","right":"Prepare one point in advance"},{"left":"You start with self-put-downs","right":"Drop it, lead with the point"},{"left":"A skipped idea in the group chat","right":"Re-post: 'adding this back in'"},{"left":"Nerves before speaking","right":"Speak anyway; it gets easier"},{"left":"Invited to a panel, doubting it","right":"Accept; you were asked for a reason"}],"relearn":"For each barrier to speaking, there's a concrete move that keeps your voice in the room.","persona":"any","source":"barrier to move"},
  {"id":"ec-1052","cat":"claim-your-voice","type":"match","hook":"Match the office voice barrier to what to do about it.","pairs":[{"left":"Quiet teammate keeps getting cut off","right":"Open space: 'let's hear them'"},{"left":"You'd negotiate but fear seeming greedy","right":"Asking if it's flexible is fine"},{"left":"You spotted a flaw in a senior's plan","right":"Name it kindly, with a fix"},{"left":"You feel like an impostor here","right":"Doubt isn't proof you don't belong"},{"left":"Your idea got brushed aside","right":"Re-table it when it circles back"}],"relearn":"Most office voice barriers have a calm response; the barrier isn't a verdict on you.","persona":"any","source":"work voice barriers"},
  {"id":"ec-1053","cat":"claim-your-voice","type":"match","hook":"Match each confidence myth to why it's false.","pairs":[{"left":"\"Speak only when totally sure\"","right":"Thinking out loud moves talk on"},{"left":"\"A shaky voice means I'm not ready\"","right":"Nerves fade the more you speak"},{"left":"\"Juniors should only listen\"","right":"Fresh eyes spot what regulars miss"},{"left":"\"A rejected idea was a mistake\"","right":"Contributing is how your voice grows"},{"left":"\"Confidence equals being loudest\"","right":"It's claiming your fair space, calmly"}],"relearn":"Each confidence myth has a clear reason it's false; knowing it makes speaking easier.","persona":"any","source":"myth to reason"},
  {"id":"ec-1054","cat":"claim-your-voice","type":"match","hook":"Match the everyday college moment to the voice skill it asks of you.","pairs":[{"left":"Group viva, examiner skips you","right":"Step in and claim your section"},{"left":"Doubt before raising a hand","right":"Put yourself forward anyway"},{"left":"Professor answered a different question","right":"Redirect back to yours"},{"left":"Family says 'good girls stay quiet'","right":"Make one clear point in public"},{"left":"You over-apologised in an email","right":"Rewrite it: cut the sorries"}],"relearn":"Each college moment is a chance to practise one voice skill; the skill grows by doing.","persona":"any","source":"moment to skill"},
  {"id":"ec-1080","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"If women get more seats, men get fewer.\"","myth":{"un":"More seats for women means fewer for men.","re":"Fair hiring grows the talent pool, so the best people rise and teams get stronger.","why":"Merit widens, it isn't rationed."},"relearn":"Fair access grows the talent pool; it isn't a fixed set of seats men lose.","persona":"any","source":"not a fixed pie"},
  {"id":"ec-1081","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"A man who cooks or does childcare is less of a man.\"","myth":{"un":"A man who cooks or parents hands-on is weak.","re":"Sharing care frees men from a rigid role and builds closer families.","why":"Rigid 'manliness' costs men too."},"relearn":"Equality frees men from rigid roles; shared care is a gain, not a loss of status.","persona":"Rohan","source":"freedom from rigid roles"},
  {"id":"ec-1082","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Fixing bias just means lowering the bar.\"","myth":{"un":"Equality lowers the standard.","re":"Removing bias raises the bar, because talent stops being wasted on the wrong filters.","why":"Bias was the thing lowering it."},"relearn":"Countering bias raises standards; wasted talent was the real cost.","persona":"any","source":"raises the bar"},
  {"id":"ec-1083","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Men can't have a real say in equality.\"","myth":{"un":"Equality isn't men's place to work on.","re":"Everyone builds a fairer world together; men leading on fairness is strength.","why":"It's built with people, not against them."},"relearn":"Equality is built with everyone; men have a real, valued part in it.","persona":"Rohan","source":"built together"},
  {"id":"ec-1084","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Equality is just a city, English-speaking thing.\"","myth":{"un":"Equality only matters for big-city elites.","re":"Fairness lifts families in every town; a daughter's education or a son's softer role helps all.","why":"Rigid roles cost everyone, everywhere."},"relearn":"Equality lifts people in every kind of town, not just cities.","persona":"Aarti","source":"everywhere, not just cities"},
  {"id":"ec-1085","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Diversity hires can't really be the best.\"","myth":{"un":"A diverse team must mean weaker picks.","re":"Mixed teams bring more angles and decide better; that's why fair hiring wins.","why":"More perspectives, fewer blind spots."},"relearn":"Diverse teams decide better; fairness is a strength, not a compromise.","persona":"any","source":"diverse teams win"},
  {"id":"ec-1086","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Sharing credit means I get less.\"","myth":{"un":"Crediting others shrinks my own standing.","re":"Lifting teammates makes the whole team look good, and you with it.","why":"Trust and reputation aren't zero-sum."},"relearn":"Sharing credit grows the team and you; it isn't a loss.","persona":"any","source":"credit isn't zero-sum"},
  {"id":"ec-1087","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Paternity leave is just a freebie that hurts the firm.\"","myth":{"un":"Dads taking leave only costs the company.","re":"Shared parental leave keeps good people, and kids and partners both gain.","why":"Retention and families both win."},"relearn":"Shared parental leave is a gain for families and firms, not just a cost.","persona":"any","source":"shared leave wins"},
  {"id":"ec-1088","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Calling out bias just makes workplaces tense.\"","myth":{"un":"Naming bias only sours the mood.","re":"Calling bias in kindly makes a room fairer, and fairer rooms are calmer for all.","why":"Resentment grows when it's ignored."},"relearn":"A fairer room is better for everyone in it; naming bias kindly helps all.","persona":"any","source":"fairer is calmer"},
  {"id":"ec-1089","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Boys lose out when girls are encouraged too.\"","myth":{"un":"Cheering on girls leaves boys behind.","re":"Encouragement isn't rationed; a classroom that lifts everyone lifts boys too.","why":"Support grows; it isn't shared out thinly."},"relearn":"Encouraging girls doesn't take from boys; support isn't a fixed amount.","persona":"any","source":"support isn't rationed"},
  {"id":"ec-1090","cat":"equality-lifts-everyone","type":"strike-rewrite","hook":"\"Equality is a women-versus-men contest.\"","myth":{"un":"Equality pits women against men.","re":"It's people building fairness together, across genders, not a side winning.","why":"Fairness isn't a match with losers."},"relearn":"Equality is built with people across genders, never a contest against men.","persona":"any","source":"not a contest"},
  {"id":"ec-1091","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: when a man feels free to cry or ask for help, that's equality working for him too. Notice that?","prompt":"What do you think?","options":["Yes","Men gain too","Freedom for all"],"affirm":"Letting go of 'never show weakness' frees men; equality lifts every gender, not just one.","relearn":"Equality frees men from rigid roles too; it lifts everyone.","persona":"any","source":"men gain too"},
  {"id":"ec-1092","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: a team where everyone's heard usually makes better calls. Worth building?","prompt":"What do you think?","options":["Yes","Better calls","Worth it"],"affirm":"When every voice counts, teams catch more blind spots and decide better; fairness pays off for all.","relearn":"A fairer team hears everyone and decides better; equality is a shared gain.","persona":"any","source":"better decisions"},
  {"id":"ec-1093","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: you can show fairness in how you act, without a single speech. See yourself doing that?","prompt":"What do you think?","options":["Yes","Show, don't preach","I can model it"],"affirm":"Quietly sharing the load and crediting fairly shifts a room more than any lecture; just live it.","relearn":"Model fairness through what you do; it shifts norms without preaching.","persona":"any","source":"model, don't preach"},
  {"id":"ec-1094","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: 'who's the senior one here?' defaulting to the man is a habit we can drop. Drop it?","prompt":"What do you think?","options":["Yes","Drop the assumption","Check myself"],"affirm":"Noticing that default and checking it is small but real; fairer habits make a room better for all.","relearn":"Dropping the 'man is senior' default is a small move that lifts the whole room.","persona":"any","source":"drop the default"},
  {"id":"ec-1095","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: an equal home, chores and care shared, makes life lighter for everyone in it. Carry that home?","prompt":"What do you think?","options":["Yes","Lighter for all","Share at home"],"affirm":"When care and chores are shared at home, no one's stretched thin; equality lifts the household too.","relearn":"Sharing care and chores at home lifts everyone in the household.","persona":"any","source":"equal home"},
  {"id":"ec-1096","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: cheering a friend's win doesn't shrink yours. Believe that?","prompt":"What do you think?","options":["Yes","Their win helps","Not a contest"],"affirm":"Success isn't a fixed pie; lifting others lifts the whole group, and you rise with it.","relearn":"Others' success isn't your loss; lifting people lifts everyone.","persona":"any","source":"not a fixed pie"},
  {"id":"ec-1097","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: a fairer rule helps the next person who walks in, not just you. Worth setting up?","prompt":"What do you think?","options":["Yes","For who's next","Build it fair"],"affirm":"Rotating tasks or open credit outlasts you; building fairness in helps everyone who comes after.","relearn":"Fair systems you build help everyone who comes after, not just you.","persona":"any","source":"for the next person"},
  {"id":"ec-1098","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: you don't need to be perfect at this to start practising fairness today. Start anyway?","prompt":"What do you think?","options":["Yes","Start anyway","Practise it"],"affirm":"Fairness is a daily practice, not a finished badge; trying and adjusting beats waiting to be perfect.","relearn":"Equality is a daily practice; start now and adjust, you don't need to be perfect.","persona":"any","source":"practice, not perfect"},
  {"id":"ec-1099","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: a brother who shares housework gives his sister more time to study or work. Good trade?","prompt":"What do you think?","options":["Yes","Frees her time","Share the load"],"affirm":"Sharing housework at home frees a sister's hours for what she chooses; the whole family gains.","relearn":"Sharing household work frees everyone's time; equality at home lifts the family.","persona":"any","source":"frees her time"},
  {"id":"ec-1100","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: 'fair for everyone' lands better than 'you're wrong'. Lead with that?","prompt":"What do you think?","options":["Yes","Fair for all","Invite, don't blame"],"affirm":"Framing equality as fairness for everyone, not blame, brings more people in and changes more minds.","relearn":"Reframe equality as fairness for all, not blame; it brings more people in.","persona":"any","source":"invite in"},
  {"id":"ec-1101","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: when one person stops being the only one who plans every event, they breathe easier. See it?","prompt":"What do you think?","options":["Yes","Spread the load","Everyone breathes"],"affirm":"Spreading the invisible planning work means no one's quietly drowning; a fairer load helps all.","relearn":"Sharing invisible work means no one carries it alone; fairness eases everyone.","persona":"any","source":"share invisible work"},
  {"id":"ec-1102","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: a workplace that values caring, not just hustle, is kinder to men too. Want that?","prompt":"What do you think?","options":["Yes","Kinder for all","Value care"],"affirm":"When care and rest are respected, men aren't trapped in 'always grind' either; everyone benefits.","relearn":"Valuing care over pure hustle lifts men too; equality helps all genders.","persona":"any","source":"value care"},
  {"id":"ec-1103","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: you can disagree with a 'men vs women' joke without making it a fight. Try it?","prompt":"What do you think?","options":["Yes","Keep it light","Reframe gently"],"affirm":"A light 'it's not them vs us, really' reframes without a fight; gentle beats combative here.","relearn":"You can reframe the 'us vs them' story lightly, not as a fight; it works better.","persona":"any","source":"light reframe"},
  {"id":"ec-1104","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: a daughter and a son raised with the same hopes both walk taller. Picture that?","prompt":"What do you think?","options":["Yes","Same hopes","Both walk taller"],"affirm":"Equal expectations let a son show feeling and a daughter chase ambition; both children gain.","relearn":"Equal hopes for sons and daughters lift both children; equality is not zero-sum.","persona":"any","source":"same hopes"},
  {"id":"ec-1105","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: 'how can we make this fairer for all of us?' is a question worth asking out loud. Ask it?","prompt":"What do you think?","options":["Yes","Ask it","For all of us"],"affirm":"That one question turns equality into a shared project everyone owns, instead of a side to pick.","relearn":"Asking 'fairer for all of us?' makes equality a shared project, not a side.","persona":"any","source":"shared question"},
  {"id":"ec-1106","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: the room you make fair today is the normal someone younger inherits. Set the bar?","prompt":"What do you think?","options":["Yes","Set the bar","For the next ones"],"affirm":"What you treat as normal becomes the baseline for those after you; equal rooms compound over time.","relearn":"Normalising fairness now sets the baseline the next people inherit.","persona":"any","source":"set the normal"},
  {"id":"ec-1107","cat":"equality-lifts-everyone","type":"reflect","hook":"Lensy: noticing who never gets asked their view, then asking them, costs you nothing. Do it?","prompt":"What do you think?","options":["Yes","Ask them","Costs nothing"],"affirm":"Turning to the person who's never asked widens the room's thinking; small move, real gain for all.","relearn":"Asking the never-asked person widens the room; equality lifts the group.","persona":"any","source":"ask the unasked"},
  {"id":"ec-1108","cat":"equality-lifts-everyone","type":"branch","hook":"A senior colleague says hiring more women 'isn't fair to the men'.","options":[{"text":"Reframe: fair hiring grows the talent pool, so the best rise","consequence":"You shift it from a loss to a shared gain.","outcome":"reframed","best":true},{"text":"Nod along to avoid friction","consequence":"Naming it as a shared gain, not men losing, would have moved the room."}],"debrief":"Fair hiring isn't men losing seats; it widens the pool so the strongest rise for everyone.","relearn":"Fair hiring grows the talent pool; it isn't men losing out.","persona":"any","source":"reframe hiring"},
  {"id":"ec-1109","cat":"equality-lifts-everyone","type":"branch","hook":"A friend says he can't show stress because 'men have to be strong'.","options":[{"text":"Tell him equality frees him to ask for help too","consequence":"He sees fairness as something he gains from.","outcome":"opened-up","best":true},{"text":"Agree that men just have to tough it out","consequence":"Showing him equality lifts men too would have freed him from that rigid rule."}],"debrief":"Equality frees men from 'always strong, never struggling'; that's a gain, not a loss.","relearn":"Equality frees men from rigid roles; it lifts them, not just women.","persona":"Rohan","source":"men gain freedom"},
  {"id":"ec-1110","cat":"equality-lifts-everyone","type":"branch","hook":"At a family event, a cousin jokes 'equality means men have to lose'.","options":[{"text":"Keep it warm: 'it's fairness for all of us, no one loses'","consequence":"You defuse the zero-sum joke without a fight.","outcome":"defused","best":true},{"text":"Argue hard and turn it into a row","consequence":"A warm 'no one loses, it's for all of us' would have landed better than a row."}],"debrief":"Reframing the 'men lose' joke warmly defuses zero-sum thinking better than arguing.","relearn":"Reframe 'men lose' warmly as fairness for all; it isn't zero-sum.","persona":"any","source":"defuse warmly"},
  {"id":"ec-1111","cat":"equality-lifts-everyone","type":"branch","hook":"Your team plans to rotate the event-organising that always lands on one woman.","options":[{"text":"Back the rotation: it shares the load and frees her time","consequence":"The load is shared and the team runs fairer.","outcome":"rotated","best":true},{"text":"Say it's fine as it is","consequence":"Backing the rotation would have shared the load and freed her hours for bigger work."}],"debrief":"Sharing the always-one-person admin frees her time and makes the team fairer for all.","relearn":"Rotating shared admin frees one person's time and lifts the team.","persona":"any","source":"share the load"},
  {"id":"ec-1112","cat":"equality-lifts-everyone","type":"branch","hook":"A junior says 'equality talk just makes us all walk on eggshells'.","options":[{"text":"Show that a fairer room is actually easier for everyone","consequence":"He sees fairness as relief, not tension.","outcome":"reassured","best":true},{"text":"Tell him to just deal with it","consequence":"Showing him a fair room is calmer, not tenser, would have won him over."}],"debrief":"A fairer room is calmer for everyone; equality eases tension, it doesn't create it.","relearn":"A fairer room is better and calmer for everyone in it.","persona":"any","source":"fairer is easier"},
  {"id":"ec-1113","cat":"equality-lifts-everyone","type":"branch","hook":"A manager wants to scrap shared parental leave to 'save money'.","options":[{"text":"Note it keeps good people and helps families and the firm","consequence":"He weighs retention, not just cost.","outcome":"retained","best":true},{"text":"Stay quiet since it doesn't affect you","consequence":"Noting that shared leave retains talent and lifts families would have changed the call."}],"debrief":"Shared parental leave keeps good people and helps families; it's a gain, not just a cost.","relearn":"Shared parental leave is a win for families and firms, not just a cost.","persona":"any","source":"shared leave"},
  {"id":"ec-1114","cat":"equality-lifts-everyone","type":"branch","hook":"In a debate, someone says 'fairness for women means unfairness to men'.","options":[{"text":"Reframe: removing bias is fair to everyone, including men","consequence":"You break the false trade-off.","outcome":"reframed","best":true},{"text":"Concede the point to move on","consequence":"Breaking the false trade-off, fairness isn't unfairness to men, would have held the room."}],"debrief":"Removing bias is fair to everyone; one group's fairness isn't another's loss.","relearn":"Removing bias is fair to all; it isn't unfairness to men.","persona":"any","source":"break the trade-off"},
  {"id":"ec-1115","cat":"equality-lifts-everyone","type":"branch","hook":"Your hostel wants a 'no questions, just split chores evenly' rule.","options":[{"text":"Support it: shared chores make daily life lighter for all","consequence":"Everyone's load eases and resentment drops.","outcome":"shared","best":true},{"text":"Push to keep the old uneven split","consequence":"Supporting the even split would have eased everyone's load and cut resentment."}],"debrief":"Evenly shared chores make daily life lighter for everyone and cut quiet resentment.","relearn":"Sharing chores evenly lifts everyone; equality at home helps all.","persona":"any","source":"even chores"},
  {"id":"ec-1116","cat":"equality-lifts-everyone","type":"branch","hook":"A classmate says 'this fairness stuff isn't my problem to fix'.","options":[{"text":"Invite him in: 'a fairer batch helps you too, let's build it'","consequence":"He joins instead of opting out.","outcome":"joined","best":true},{"text":"Tell him fine, leave it to others","consequence":"Inviting him in, a fairer batch helps him too, would have made it everyone's project."}],"debrief":"Equality is built with everyone; inviting people in beats letting them opt out.","relearn":"Equality is built with everyone; invite people in, it helps them too.","persona":"any","source":"invite, don't exclude"},
  {"id":"ec-1117","cat":"equality-lifts-everyone","type":"branch","hook":"A teammate grabs all the visible credit and you could do the same.","options":[{"text":"Share credit openly so the whole team looks good","consequence":"Trust grows and you rise with the team.","outcome":"shared-credit","best":true},{"text":"Grab credit too, since they did","consequence":"Sharing credit would have built trust and lifted you with the team, not against it."}],"debrief":"Sharing credit isn't a loss; it builds trust and lifts the whole team, you included.","relearn":"Sharing credit grows trust and lifts everyone; it isn't zero-sum.","persona":"any","source":"share, don't grab"},
  {"id":"ec-1118","cat":"equality-lifts-everyone","type":"branch","hook":"An uncle insists 'a son who helps in the kitchen is being made soft'.","options":[{"text":"Reframe: he's learning life skills and a closer family","consequence":"You shift it from weakness to gain.","outcome":"reframed","best":true},{"text":"Agree to keep the peace","consequence":"Reframing it as life skills and closeness would have shown the son gains, not loses."}],"debrief":"A son sharing care gains skills and closeness; rigid roles cost boys too.","relearn":"Sharing care frees boys from rigid roles; it's a gain, not weakness.","persona":"any","source":"boys gain too"},
  {"id":"ec-1119","cat":"equality-lifts-everyone","type":"role-play","hook":"A friend says 'feminism just wants men to lose'.","setup":"Reframe it warmly. Say:","yourLine":[{"text":"\"It's fairness for all of us, men included, nobody has to lose for it.\"","best":true},{"text":"Get defensive or just agree with him"}],"relearn":"Reframe equality as fairness for everyone, men included; nobody loses.","persona":"Rohan","source":"reframe for a friend"},
  {"id":"ec-1120","cat":"equality-lifts-everyone","type":"role-play","hook":"A relative says 'why should boys do housework, that's not for them'.","setup":"Reframe it kindly. Say:","yourLine":[{"text":"\"Sharing chores teaches them life skills and makes the home lighter for all of us.\"","best":true},{"text":"Just drop it and let it slide"}],"relearn":"Sharing chores teaches boys life skills and lightens the home for everyone.","persona":"any","source":"chores reframe"},
  {"id":"ec-1121","cat":"equality-lifts-everyone","type":"role-play","hook":"A colleague calls a fairer-hiring plan 'unfair to guys like us'.","setup":"Reframe it evenly. Say:","yourLine":[{"text":"\"Fair hiring just widens the pool, the strongest still rise, that helps everyone.\"","best":true},{"text":"Agree it's a raw deal and move on"}],"relearn":"Fair hiring widens the pool so the strongest rise; it helps everyone.","persona":"any","source":"hiring reframe"},
  {"id":"ec-1122","cat":"equality-lifts-everyone","type":"role-play","hook":"A mate jokes that a man crying is 'pathetic'.","setup":"Push back gently. Say:","yourLine":[{"text":"\"Honestly, letting blokes feel stuff is good for us, it's not weakness.\"","best":true},{"text":"Laugh along to fit in"}],"relearn":"Letting men show feeling frees them from a rigid role; it isn't weakness.","persona":"Rohan","source":"men's feelings"},
  {"id":"ec-1123","cat":"equality-lifts-everyone","type":"role-play","hook":"Someone says 'equality's a women's thing, leave us out of it'.","setup":"Bring them in. Say:","yourLine":[{"text":"\"It's all of ours to build, and a fairer place is better for you too.\"","best":true},{"text":"Shrug and say it's not their problem"}],"relearn":"Equality is everyone's to build; a fairer place is better for them too.","persona":"any","source":"bring them in"},
  {"id":"ec-1124","cat":"equality-lifts-everyone","type":"role-play","hook":"A friend grumbles 'why bother, one fair person won't change anything'.","setup":"Encourage them. Say:","yourLine":[{"text":"\"Every fair room you make becomes normal for whoever's next, that adds up.\"","best":true},{"text":"Agree it's pointless and give up"}],"relearn":"Each fair room you build becomes the new normal for those after you.","persona":"any","source":"it adds up"},
  {"id":"ec-1125","cat":"equality-lifts-everyone","type":"role-play","hook":"A peer frames a campus fairness drive as 'us against the boys'.","setup":"Reframe it. Say:","yourLine":[{"text":"\"It's not against anyone, it's with everyone, a fairer batch lifts us all.\"","best":true},{"text":"Echo the 'us against them' framing"}],"relearn":"A fairness drive is built with everyone, not against the boys; all gain.","persona":"Zoya","source":"with, not against"},
  {"id":"ec-1126","cat":"equality-lifts-everyone","type":"match","hook":"Match each fair move to who it lifts.","relearn":"Fair moves like shared care, open credit and rotated admin lift everyone, men included.","persona":"any","source":"who it lifts","pairs":[{"left":"Dads sharing childcare","right":"Closer families and freer men"},{"left":"Credit shared openly","right":"More trust across the team"},{"left":"Admin tasks rotated","right":"One person's time freed up"},{"left":"Sons taught to cook","right":"Life skills for the next generation"},{"left":"Hiring without bias","right":"A wider, stronger talent pool"}]},
  {"id":"ec-1127","cat":"equality-lifts-everyone","type":"match","hook":"Match the zero-sum myth to the truth that lifts everyone.","relearn":"'Men lose', 'fixed pie' and 'women's issue' are myths; equality is a shared, growing gain.","persona":"any","source":"myth to truth","pairs":[{"left":"Equality means men lose","right":"Men gain freedom from rigid roles"},{"left":"It's a fixed pie to split","right":"Fairness grows the whole pie"},{"left":"It's only a women's issue","right":"Everyone has a part to build it"},{"left":"Fairness lowers the bar","right":"Removing bias raises the bar"},{"left":"Credit shared is credit lost","right":"Sharing credit builds the team"}]},
  {"id":"ec-1128","cat":"equality-lifts-everyone","type":"match","hook":"Match each rigid-role cost to the freedom equality brings.","relearn":"Equality frees men and women alike from rigid roles; both genders gain from it.","persona":"any","source":"rigid to free","pairs":[{"left":"'Men must never cry'","right":"Men free to feel and ask for help"},{"left":"'Women can't be ambitious'","right":"Women free to lead and aim high"},{"left":"'Dads don't do nappies'","right":"Fathers close to their kids"},{"left":"'Boys don't cook'","right":"Boys with real life skills"},{"left":"'Girls do all the housework'","right":"Shared load, more time for all"}]},
  {"id":"ec-1129","cat":"equality-lifts-everyone","type":"match","hook":"Match each fairer setup to the gain it brings the whole group.","relearn":"Fairer setups, hearing everyone, sharing care and credit, make the whole group better off.","persona":"any","source":"setup to gain","pairs":[{"left":"Everyone's voice heard","right":"Fewer blind spots, better calls"},{"left":"Care valued, not just hustle","right":"Less burnout for everyone"},{"left":"Chores split evenly at home","right":"A lighter daily load for all"},{"left":"Quieter people invited in","right":"Wider, richer ideas"},{"left":"Fair rules built to last","right":"Helps whoever comes next"}]},
  {"id":"ec-1130","cat":"equality-lifts-everyone","type":"match","hook":"Match each reframe to the worry it answers.","relearn":"Warm reframes turn 'men lose' worries into a shared-fairness frame that brings people in.","persona":"any","source":"reframe to worry","pairs":[{"left":"'Will men lose out?'","right":"No one loses, fairness lifts all"},{"left":"'Is this against the boys?'","right":"It's built with everyone, not against"},{"left":"'Does it lower standards?'","right":"It raises them by ending wasted talent"},{"left":"'Is it just elite city talk?'","right":"It lifts families in every town"},{"left":"'Is it my problem to fix?'","right":"A fairer place helps you too"}]},
  {"id":"ec-1131","cat":"equality-lifts-everyone","type":"match","hook":"Match the home change to who it frees.","relearn":"Equality at home, shared chores, care and decisions, frees and lifts everyone in the family.","persona":"any","source":"home change","pairs":[{"left":"Husband shares the cooking","right":"Wife gets hours back for her work"},{"left":"Both parents do school runs","right":"Dad grows closer to the kids"},{"left":"Decisions made together","right":"Everyone feels respected at home"},{"left":"Son and daughter same chores","right":"Both learn to run a home"},{"left":"Elders' care shared by all","right":"No single person burns out"}]},
  {"id":"ec-1132","cat":"equality-lifts-everyone","type":"match","hook":"Match each everyday fair act to the bias it quietly undoes.","relearn":"Small fair acts, crediting, rotating, inviting in, quietly undo the everyday biases that hold people back.","persona":"any","source":"act to bias","pairs":[{"left":"Credit the real author","right":"Undoes idea-stealing bias"},{"left":"Rotate the note-taking","right":"Undoes office-housework default"},{"left":"Hand the floor back","right":"Undoes the interruption pattern"},{"left":"Ask the man's senior assumption","right":"Undoes the seniority default"},{"left":"Praise calm assertiveness in all","right":"Undoes the 'bossy' double standard"}]},
  {"id":"ec-1133","cat":"equality-lifts-everyone","type":"sort","hook":"Sort: does this lift everyone, or is it a zero-sum myth?","items":[{"id":"a","text":"Dads getting parental leave"},{"id":"b","text":"'Every seat she gets, a man loses'"},{"id":"c","text":"Sons and daughters raised with equal hopes"},{"id":"d","text":"'Equality is a fixed pie to fight over'"},{"id":"e","text":"Hearing every voice in the room"},{"id":"f","text":"'Fairness for women is unfair to men'"}],"bins":[{"id":"lifts","label":"Lifts everyone","valence":"pos"},{"id":"myth","label":"Zero-sum myth","valence":"neg"}],"key":{"a":"lifts","b":"myth","c":"lifts","d":"myth","e":"lifts","f":"myth"},"relearn":"Shared leave, equal hopes and hearing everyone lift all; 'men lose' and 'fixed pie' are myths.","persona":"any","source":"lift vs myth"},
  {"id":"ec-1134","cat":"equality-lifts-everyone","type":"sort","hook":"Sort: who does this fair change gain for?","items":[{"id":"a","text":"Men free to show feelings"},{"id":"b","text":"Women free to lead and aim high"},{"id":"c","text":"Closer dads, hands-on with kids"},{"id":"d","text":"Daughters and sons, equal hopes"},{"id":"e","text":"A team that hears everyone"},{"id":"f","text":"A home with the load shared"}],"bins":[{"id":"men","label":"A gain men feel","valence":"pos"},{"id":"women","label":"A gain women feel","valence":"tell"},{"id":"all","label":"A gain everyone shares","valence":"neutral"}],"key":{"a":"men","b":"women","c":"men","d":"all","e":"all","f":"all"},"relearn":"Equality is a gain for men, for women and for everyone together; it's never zero-sum.","persona":"any","source":"who gains"},
  {"id":"ec-1135","cat":"equality-lifts-everyone","type":"sort","hook":"Sort: does this build equality with people, or against them?","items":[{"id":"a","text":"'Let's make this fairer for all of us'"},{"id":"b","text":"'It's us women against the men'"},{"id":"c","text":"Inviting a sceptical friend to help"},{"id":"d","text":"Mocking men who get it wrong"},{"id":"e","text":"Crediting everyone's part"},{"id":"f","text":"Shaming people into silence"}],"bins":[{"id":"with","label":"Built with people","valence":"pos"},{"id":"against","label":"Built against people","valence":"neg"}],"key":{"a":"with","b":"against","c":"with","d":"against","e":"with","f":"against"},"relearn":"Equality is built with people, inviting and crediting, not against them by mocking or shaming.","persona":"any","source":"with vs against"},
  {"id":"ec-1136","cat":"equality-lifts-everyone","type":"sort","hook":"Sort: a real equality gain, or just a slogan with nothing behind it?","items":[{"id":"a","text":"Actually rotating the office admin"},{"id":"b","text":"A poster saying 'we value women'"},{"id":"c","text":"Sharing credit in the meeting"},{"id":"d","text":"A hashtag, then business as usual"},{"id":"e","text":"Mentoring a junior into a stretch role"},{"id":"f","text":"A speech, then the same old habits"}],"bins":[{"id":"real","label":"Real change","valence":"pos"},{"id":"slogan","label":"Just a slogan","valence":"uhoh"}],"key":{"a":"real","b":"slogan","c":"real","d":"slogan","e":"real","f":"slogan"},"relearn":"Real change is rotating admin, sharing credit and mentoring; slogans without changed habits are optics.","persona":"any","source":"real vs slogan"},
  {"id":"ec-1137","cat":"equality-lifts-everyone","type":"sort","hook":"Sort: does this frame equality as a gain, or as a loss for men?","items":[{"id":"a","text":"'Men gain freedom from rigid roles'"},{"id":"b","text":"'Men will be pushed out'"},{"id":"c","text":"'A fairer team helps us all'"},{"id":"d","text":"'It's men's turn to suffer'"},{"id":"e","text":"'Sharing care brings dads closer'"},{"id":"f","text":"'Equality is men losing status'"}],"bins":[{"id":"gain","label":"A gain frame","valence":"pos"},{"id":"loss","label":"A loss frame","valence":"neg"}],"key":{"a":"gain","b":"loss","c":"gain","d":"loss","e":"gain","f":"loss"},"relearn":"Equality is a gain frame, freedom, closeness, fairer teams, never a 'men lose status' loss frame.","persona":"any","source":"gain vs loss"},
  {"id":"ec-1138","cat":"equality-lifts-everyone","type":"sort","hook":"Sort: who shares the job of building a fairer place?","items":[{"id":"a","text":"Men acting as everyday allies"},{"id":"b","text":"'Only women should care about this'"},{"id":"c","text":"Leaders modelling fairness"},{"id":"d","text":"'Leave it to the activists'"},{"id":"e","text":"Each of us in small daily acts"},{"id":"f","text":"'It's not my place to help'"}],"bins":[{"id":"shared","label":"Everyone's job","valence":"pos"},{"id":"optout","label":"Opting out","valence":"neg"}],"key":{"a":"shared","b":"optout","c":"shared","d":"optout","e":"shared","f":"optout"},"relearn":"Building fairness is everyone's job, men, leaders, each of us; opting out leaves it to a few.","persona":"any","source":"everyone's job"},
  {"id":"ec-1139","cat":"equality-lifts-everyone","type":"sort","hook":"Sort: does this widen the pie, or treat it as fixed?","items":[{"id":"a","text":"Fair hiring grows the talent pool"},{"id":"b","text":"'Her win is my loss'"},{"id":"c","text":"Lifting others lifts the whole team"},{"id":"d","text":"'There's only so much success to go round'"},{"id":"e","text":"Diverse teams find more ideas"},{"id":"f","text":"'One up means someone down'"}],"bins":[{"id":"widen","label":"Widens the pie","valence":"pos"},{"id":"fixed","label":"Fixed-pie myth","valence":"neg"}],"key":{"a":"widen","b":"fixed","c":"widen","d":"fixed","e":"widen","f":"fixed"},"relearn":"Fair hiring, lifting others and diverse teams widen the pie; 'fixed success to split' is a myth.","persona":"any","source":"widen vs fixed"},
  {"id":"ec-1140","cat":"equality-lifts-everyone","type":"spot","hook":"Spot the two zero-sum lines that frame equality as men losing.","scene":[{"id":"a","text":"'Every seat she takes, a man loses one'","trick":true},{"id":"b","text":"'Fair hiring widens the pool for all'","trick":false},{"id":"c","text":"'It's just men's turn to be pushed out'","trick":true},{"id":"d","text":"'Men gain freedom from rigid roles too'","trick":false},{"id":"e","text":"'A fairer team helps everyone in it'","trick":false}],"why":"'A man loses a seat' and 'men pushed out' are zero-sum framings; the rest show equality lifting all.","relearn":"'Men lose seats' and 'men pushed out' are zero-sum myths; equality lifts everyone.","persona":"any","source":"catch zero-sum"},
  {"id":"ec-1141","cat":"equality-lifts-everyone","type":"spot","hook":"Spot the two 'us against them' lines that pit the genders against each other.","scene":[{"id":"a","text":"'It's women versus men now'","trick":true},{"id":"b","text":"'Let's make this fairer for all of us'","trick":false},{"id":"c","text":"'We win when the boys lose'","trick":true},{"id":"d","text":"'Equality is built with everyone'","trick":false},{"id":"e","text":"'A fairer place is better for you too'","trick":false}],"why":"'Women versus men' and 'we win when boys lose' pit genders against each other; equality is built with all.","relearn":"Equality is built with people, not as 'us against them'; pitting genders is the myth.","persona":"any","source":"catch us-vs-them"},
  {"id":"ec-1142","cat":"equality-lifts-everyone","type":"spot","hook":"Spot the two lines that keep men trapped in a rigid role.","scene":[{"id":"a","text":"'Real men never cry or ask for help'","trick":true},{"id":"b","text":"'It's okay for blokes to feel things'","trick":false},{"id":"c","text":"'A man doing childcare is soft'","trick":true},{"id":"d","text":"'Hands-on dads build closer families'","trick":false},{"id":"e","text":"'Sharing care frees men too'","trick":false}],"why":"'Men never cry' and 'childcare is soft' trap men in rigid roles; equality frees them from both.","relearn":"Equality frees men from rigid roles; 'never cry' and 'care is soft' are the traps.","persona":"any","source":"catch rigid roles"},
  {"id":"ec-1143","cat":"equality-lifts-everyone","type":"spot","hook":"Spot the two slogan-only lines that change nothing.","scene":[{"id":"a","text":"'We posted a women's-day photo, done'","trick":true},{"id":"b","text":"'We rotated the admin this month'","trick":false},{"id":"c","text":"'Great speech, then same habits as ever'","trick":true},{"id":"d","text":"'We credited the real author openly'","trick":false},{"id":"e","text":"'We mentored a junior into a stretch role'","trick":false}],"why":"A photo and a speech with no changed habits are optics; rotating, crediting and mentoring are real change.","relearn":"Real change is shifting habits, not slogans; a photo or speech alone is just optics.","persona":"any","source":"catch optics"},
  {"id":"ec-1144","cat":"equality-lifts-everyone","type":"spot","hook":"Spot the two myths about who equality is for.","scene":[{"id":"a","text":"'Equality is only a women's issue'","trick":true},{"id":"b","text":"'Everyone has a part in building it'","trick":false},{"id":"c","text":"'Men can't really help with this'","trick":true},{"id":"d","text":"'Men leading on fairness is strength'","trick":false},{"id":"e","text":"'A fairer place is better for all of us'","trick":false}],"why":"'Only a women's issue' and 'men can't help' are myths; equality is everyone's to build, men included.","relearn":"Equality is everyone's to build; 'women's issue only' and 'men can't help' are myths.","persona":"any","source":"catch who-for myths"},
  {"id":"ec-1145","cat":"equality-lifts-everyone","type":"spot","hook":"Spot the two lines that wrongly treat success as a fixed pie.","scene":[{"id":"a","text":"'Her promotion means I missed out'","trick":true},{"id":"b","text":"'Lifting others lifts the whole team'","trick":false},{"id":"c","text":"'There's only so much success to go round'","trick":true},{"id":"d","text":"'Fair hiring grows the talent pool'","trick":false},{"id":"e","text":"'Diverse teams find more, not less'","trick":false}],"why":"'Her promotion means I missed out' and 'only so much success' treat it as fixed; the pie actually grows.","relearn":"Success isn't a fixed pie; lifting others and fair hiring grow it for everyone.","persona":"any","source":"catch fixed-pie"},
  {"id":"ec-1146","cat":"equality-lifts-everyone","type":"spot","hook":"Spot the two home-life lines that load it all onto one person.","scene":[{"id":"a","text":"'Housework's the wife's job, full stop'","trick":true},{"id":"b","text":"'We split the cooking and cleaning'","trick":false},{"id":"c","text":"'Caring for elders is only her duty'","trick":true},{"id":"d","text":"'We share the elder-care between us'","trick":false},{"id":"e","text":"'Decisions at home we make together'","trick":false}],"why":"'Housework is the wife's job' and 'elder-care only hers' load one person; sharing lifts everyone at home.","relearn":"Sharing home work and decisions lifts everyone; loading it on one person is the trap.","persona":"any","source":"catch home-load"},
  {"id":"ec-1147","cat":"equality-lifts-everyone","type":"spot","hook":"Spot the two lines that excuse opting out of building fairness.","scene":[{"id":"a","text":"'Not my place to help with this'","trick":true},{"id":"b","text":"'Each of us can do small fair acts'","trick":false},{"id":"c","text":"'Leave it to the activists'","trick":true},{"id":"d","text":"'Men make great everyday allies'","trick":false},{"id":"e","text":"'Leaders can model fairness daily'","trick":false}],"why":"'Not my place' and 'leave it to activists' excuse opting out; building fairness is everyone's daily job.","relearn":"Building fairness is everyone's job; 'not my place' and 'leave it to activists' are opt-outs.","persona":"any","source":"catch opt-outs"},
  {"id":"ec-1170","cat":"lead-the-room","type":"strike-rewrite","hook":"\"Only the most senior person in the room should set the agenda.\"","myth":{"un":"Only the most senior person in the room should set the agenda.","re":"Anyone can shape direction by naming the goal and a next step. Leadership isn't ranked by seat.","why":"Initiative, not seniority, is what actually moves a stuck group forward."},"relearn":"You can lead from any seat by naming the goal and a next step.","persona":"any","source":"agenda from any seat"},
  {"id":"ec-1171","cat":"lead-the-room","type":"strike-rewrite","hook":"\"A good leader has every answer ready.\"","myth":{"un":"A good leader has every answer ready.","re":"Strong leaders say 'I don't know yet, let's find out'. Curiosity invites the team in.","why":"Pretending certainty shuts people down; admitting a gap opens the floor."},"relearn":"Good leaders admit what they don't know and invite the team to find it.","persona":"any","source":"not every answer"},
  {"id":"ec-1172","cat":"lead-the-room","type":"strike-rewrite","hook":"\"Sharing credit makes you look like you did less.\"","myth":{"un":"Sharing credit makes you look like you did less.","re":"Naming who did what marks you as the leader who sees the whole team. It grows your standing.","why":"People trust and follow leaders who make others visible."},"relearn":"Sharing credit openly grows your standing as a leader, not shrinks it.","persona":"any","source":"credit grows you"},
  {"id":"ec-1173","cat":"lead-the-room","type":"strike-rewrite","hook":"\"If you're not naturally outgoing, you can't really lead.\"","myth":{"un":"If you're not naturally outgoing, you can't really lead.","re":"Quiet leaders lead by listening, asking the right question, and following through.","why":"Teams follow steadiness and trust, not volume."},"relearn":"Quiet leadership, such as listening, asking and following through, counts fully.","persona":"Zoya","source":"quiet can lead"},
  {"id":"ec-1174","cat":"lead-the-room","type":"strike-rewrite","hook":"\"Owning a mistake in front of the team makes you look weak.\"","myth":{"un":"Owning a mistake in front of the team makes you look weak.","re":"Saying 'that was my call, here's the fix' builds more trust than blaming anyone.","why":"A team that sees you take responsibility will take risks for you."},"relearn":"Owning your mistake openly builds trust; blaming others erodes it.","persona":"any","source":"own the mistake"},
  {"id":"ec-1175","cat":"lead-the-room","type":"strike-rewrite","hook":"\"Leadership means deciding everything yourself, fast.\"","myth":{"un":"Leadership means deciding everything yourself, fast.","re":"Good leaders pull the right people in before deciding. Shared input makes a stronger call.","why":"Solo speed often misses what the team could have caught."},"relearn":"Leaders pull people in before deciding; that makes a stronger call.","persona":"any","source":"decide with people"},
  {"id":"ec-1176","cat":"lead-the-room","type":"strike-rewrite","hook":"\"You should wait until you're an expert before you volunteer to lead anything.\"","myth":{"un":"You should wait until you're an expert before you volunteer to lead anything.","re":"You grow into a role by taking it; nobody feels fully ready the first time.","why":"Stretch comes from leading something a little beyond you."},"relearn":"You grow into leadership by taking it; nobody feels fully ready first.","persona":"any","source":"grow into it"},
  {"id":"ec-1177","cat":"lead-the-room","type":"strike-rewrite","hook":"\"A real leader never lets anyone see them hesitate.\"","myth":{"un":"A real leader never lets anyone see them hesitate.","re":"Thinking out loud, such as 'let me weigh this', models good judgement for the team.","why":"Visible reasoning teaches; a forced front teaches nothing."},"relearn":"Thinking out loud models good judgement; a forced front teaches nothing.","persona":"any","source":"think out loud"},
  {"id":"ec-1178","cat":"lead-the-room","type":"branch","hook":"Your hostel event committee: no one's confirmed who's booking the hall, and the date's close.","options":[{"text":"Message: 'I'll book the hall tonight. Can someone confirm the budget?'","consequence":"You close the gap and the rest falls into place.","outcome":"initiative","best":true},{"text":"Wait for the senior member to handle it","consequence":"Naming the next step yourself is the leadership the stuck group needed."}],"debrief":"Spotting the gap and naming the next step is everyday leadership, no title needed.","relearn":"Take initiative when there's a gap; that's leadership.","persona":"any","source":"book the hall"},
  {"id":"ec-1179","cat":"lead-the-room","type":"branch","hook":"You're a fresher intern. In standup, a quieter teammate's good idea got skipped over.","options":[{"text":"'Can we go back to Meera's point? I think it solves this.'","consequence":"You lift her idea and the team picks it up.","outcome":"lift","best":true},{"text":"Stay quiet: you're new, it's not your place","consequence":"Lifting a skipped idea is leadership from any seat; being new doesn't disqualify you."}],"debrief":"Bringing a skipped voice back into the room is a generous, respected form of leadership.","relearn":"Lifting others' ideas is a powerful form of leadership.","persona":"any","source":"go back to meera"},
  {"id":"ec-1180","cat":"lead-the-room","type":"branch","hook":"You led a group submission that scored badly. The professor asks who's responsible.","options":[{"text":"'That was my plan. I'll rework it with the team.'","consequence":"The team trusts you more and rallies to fix it.","outcome":"own","best":true},{"text":"Point out which teammate dropped the ball","consequence":"Blaming the team when it fails undercuts you; owning it builds trust."}],"debrief":"Owning the outcome and rallying the fix is what marks you as a leader.","relearn":"Owning mistakes builds you as a leader; blaming the team undercuts it.","persona":"any","source":"own the score"},
  {"id":"ec-1181","cat":"lead-the-room","type":"branch","hook":"Seniors offer you the lead on the inter-college fest stall, bigger than anything you've run.","options":[{"text":"Say yes and ask one mentor to check in with","consequence":"You grow into it with a little support.","outcome":"stretch","best":true},{"text":"Decline: you assume you're not ready","consequence":"Saying yes and growing into a stretch role beats declining on the assumption you're not ready."}],"debrief":"Stretch roles grow you; pairing a yes with light support is the smart way in.","relearn":"Say yes to stretch leadership roles; you grow into them.","persona":"Aarti","source":"fest stall lead"},
  {"id":"ec-1182","cat":"lead-the-room","type":"branch","hook":"You're chairing the club meeting and three people have done all the talking for ten minutes.","options":[{"text":"'I'd love to hear from those who haven't. Kabir, thoughts?'","consequence":"Quieter members open up and the plan improves.","outcome":"inclusive","best":true},{"text":"Let the confident few keep steering it","consequence":"Only hearing the loudest narrows the room; inviting quieter voices in leads it better."}],"debrief":"Deliberately drawing out the quieter voices is what inclusive leaders do.","relearn":"As a leader, deliberately invite the quieter voices in.","persona":"any","source":"hear from kabir"},
  {"id":"ec-1183","cat":"lead-the-room","type":"branch","hook":"A junior on your team is clearly capable but never puts herself forward for visible tasks.","options":[{"text":"Hand her a stretch task: 'I'll back you on this.'","consequence":"She steps up with your backing and grows.","outcome":"encourage","best":true},{"text":"Give the visible task to someone louder","consequence":"Defaulting to the loudest overlooks her; backing her into a stretch role grows the team."}],"debrief":"Encouraging a capable person into a bigger role is leadership in itself.","relearn":"Encouraging others into leadership is leadership in itself.","persona":"any","source":"back the junior"},
  {"id":"ec-1184","cat":"lead-the-room","type":"branch","hook":"You're stuck on a project decision and don't know the answer. The team's waiting on you.","options":[{"text":"'I'm not sure. Let's think it through together for five minutes.'","consequence":"The team solves it with you and trusts you more.","outcome":"trust","best":true},{"text":"Bluff a confident answer you're unsure about","consequence":"Faking certainty risks a wrong call; admitting doubt and asking builds trust."}],"debrief":"Asking for help and admitting doubt builds trust. It doesn't shrink you.","relearn":"Good leaders ask for help and admit doubt; it builds trust.","persona":"any","source":"think it together"},
  {"id":"ec-1185","cat":"lead-the-room","type":"branch","hook":"At a department presentation, a slide shows your data but only your name. Sana built it with you.","options":[{"text":"'Quick note. Sana built this analysis with me, full credit to her.'","consequence":"Sana is seen and the team trusts you more.","outcome":"credit","best":true},{"text":"Let it stand: correcting it feels awkward","consequence":"Sharing credit openly marks the leader; letting a miscredit stand quietly undercuts it."}],"debrief":"Crediting people openly in the room is one of the clearest leadership signals.","relearn":"Sharing credit openly builds you as a leader.","persona":"any","source":"full credit sana"},
  {"id":"ec-1186","cat":"lead-the-room","type":"branch","hook":"Your study group keeps going in circles with no decision. You're not the 'leader' of it.","options":[{"text":"'Let's pick one plan and try it a week. I'll write the steps.'","consequence":"The group finally moves, led from your seat.","outcome":"initiative","best":true},{"text":"Wait for the topper to take charge","consequence":"You don't need a title to break a stalemate; naming a plan is leading."}],"debrief":"Breaking a stalemate with a concrete plan is leadership without a title.","relearn":"Leadership is initiative and lifting others; you can lead from any seat.","persona":"Deepak","source":"break the circle"},
  {"id":"ec-1187","cat":"lead-the-room","type":"branch","hook":"A team event goes wrong on the day. Speaker cancelled last minute. You're the calmest one there.","options":[{"text":"Calmly reassign roles: 'who can fill 20 minutes?'","consequence":"Your steadiness steadies the whole team.","outcome":"steady","best":true},{"text":"Panic out loud and wait for instructions","consequence":"In a crisis the team follows steadiness; quietly organising the fix is leading."}],"debrief":"Calm, clear direction in a crisis is leadership, and it can be quiet.","relearn":"Lead in your own style; quiet, steady leadership counts as much as loud.","persona":"any","source":"speaker cancelled"},
  {"id":"ec-1188","cat":"lead-the-room","type":"branch","hook":"A teammate proposes a risky idea everyone's silently doubting. You think it has promise.","options":[{"text":"'I see what you're going for. Let's test the riskiest bit first.'","consequence":"You back the idea and make it safer to try.","outcome":"back","best":true},{"text":"Stay neutral so you're not blamed if it fails","consequence":"Hedging to stay safe isn't leading; backing a good idea and shaping it is."}],"debrief":"Backing a good idea and helping de-risk it is how leaders lift others.","relearn":"Lifting others' ideas and helping shape them is leadership.","persona":"any","source":"test the riskiest bit"},
  {"id":"ec-1189","cat":"lead-the-room","type":"branch","hook":"You're coordinating a campus drive. Halfway, you realise you over-promised on the timeline.","options":[{"text":"Tell the team early: 'My timeline was off. Here's a realistic one.'","consequence":"Trust holds because you flagged it early and honestly.","outcome":"honest","best":true},{"text":"Hide the slip and push everyone to the old date","consequence":"Owning the misjudgement early builds trust; hiding it erodes it."}],"debrief":"Owning a misjudgement early and resetting honestly is what keeps a team with you.","relearn":"Owning your own mistakes builds you as a leader.","persona":"any","source":"reset the timeline"},
  {"id":"ec-1190","cat":"lead-the-room","type":"branch","hook":"In a group of mostly seniors, you have a useful idea but feel too junior to say it.","options":[{"text":"Offer it: 'I'm newer here, but what if we tried this?'","consequence":"Your idea lands and you've led from the junior seat.","outcome":"voice","best":true},{"text":"Hold it back until you're more senior","consequence":"Waiting for seniority wastes a good idea; leading from any seat means voicing it now."}],"debrief":"You can lead from the most junior seat just by contributing the idea.","relearn":"You can lead from any seat, no title required.","persona":"Aarti","source":"junior seat idea"},
  {"id":"ec-1191","cat":"lead-the-room","type":"branch","hook":"Your project finished well. In the wrap-up, the praise is all flowing to you.","options":[{"text":"'Honestly, Riya's research carried this, and Tarun's design.'","consequence":"The team feels seen and stays motivated.","outcome":"share","best":true},{"text":"Accept all the praise quietly","consequence":"Hogging the spotlight undercuts you long-term; naming the team builds you."}],"debrief":"Naming the specific people behind the win is a leader making others bigger.","relearn":"Making others feel bigger, not smaller, is the best leadership.","persona":"any","source":"name riya and tarun"},
  {"id":"ec-1192","cat":"lead-the-room","type":"branch","hook":"A new committee has no chair. You'd be good at it but worry it'll look like grabbing power.","options":[{"text":"Offer: 'I'm happy to coordinate if the group's okay with it.'","consequence":"You step up cleanly, with the group's consent.","outcome":"offer","best":true},{"text":"Stay back so no one thinks you're pushy","consequence":"Offering to coordinate isn't grabbing power; stepping up with consent is leadership."}],"debrief":"Offering to lead openly, with the group's consent, is taking initiative, not grabbing.","relearn":"Taking initiative when there's a gap is leadership.","persona":"Zoya","source":"offer to coordinate"},
  {"id":"ec-1193","cat":"lead-the-room","type":"branch","hook":"You're running a workshop and one participant clearly knows more than you on a sub-topic.","options":[{"text":"'You know this better. Can you take the next five minutes?'","consequence":"You lift their expertise and the room benefits.","outcome":"lift","best":true},{"text":"Talk over them to stay the authority","consequence":"Clinging to authority shrinks the room; handing the floor to expertise is strong leadership."}],"debrief":"Handing the floor to someone who knows more makes you the leader who lifts others.","relearn":"Lifting others up is a respected form of leadership.","persona":"any","source":"hand the floor"},
  {"id":"ec-1194","cat":"lead-the-room","type":"branch","hook":"You proposed a plan, but a teammate's counter-plan is clearly better. The group's watching you.","options":[{"text":"'Yours is stronger. Let's go with it.'","consequence":"The group trusts your judgement more, not less.","outcome":"yield","best":true},{"text":"Defend your plan to avoid looking wrong","consequence":"Defending a weaker plan to save face undercuts you; backing the better one builds you."}],"debrief":"Backing the better idea over your own ego is exactly what trustworthy leaders do.","relearn":"Sharing credit and backing the best idea builds you as a leader.","persona":"any","source":"yours is stronger"},
  {"id":"ec-1195","cat":"lead-the-room","type":"branch","hook":"A teammate freezes mid-presentation in front of the panel. You're sitting beside them.","options":[{"text":"Gently pick up the thread: 'And to add to that point…'","consequence":"You cover for them smoothly and they recover.","outcome":"cover","best":true},{"text":"Let the silence hang so they sort it out alone","consequence":"Leaving them stranded isn't leading; quietly bridging the gap lifts the whole team."}],"debrief":"Quietly covering for a stumbling teammate is leadership that lifts others.","relearn":"Lifting and supporting others is a powerful form of leadership.","persona":"any","source":"pick up the thread"},
  {"id":"ec-1196","cat":"lead-the-room","type":"branch","hook":"You can run a project the 'usual loud' way, or in your own quieter, methodical style.","options":[{"text":"Lead methodically: clear notes, one-to-one check-ins, steady follow-through","consequence":"Your style works and the team delivers.","outcome":"authentic","best":true},{"text":"Force a loud, charismatic style that isn't you","consequence":"Quiet, methodical leading counts as much as loud; a fake style burns you out."}],"debrief":"Leading in your own style beats imitating one that isn't you.","relearn":"Lead in your own style; quiet leadership counts as much as loud.","persona":"any","source":"methodical style"},
  {"id":"ec-1197","cat":"lead-the-room","type":"role-play","hook":"A capable teammate keeps underselling her work in the team chat.","setup":"Lift her up. Say:","yourLine":[{"text":"\"That analysis was sharp. You should present it yourself in the review.\"","best":true},{"text":"Say nothing; let her keep downplaying it"}],"relearn":"Lifting others by naming their strengths is a generous form of leadership.","persona":"any","source":"present it yourself"},
  {"id":"ec-1198","cat":"lead-the-room","type":"role-play","hook":"You over-committed your team to a deadline you now know is too tight.","setup":"Own it early. Say:","yourLine":[{"text":"\"That deadline was my misjudgement. Let's reset it together so it's doable.\"","best":true},{"text":"Push the team harder and stay quiet about the slip"}],"relearn":"Owning your own mistake early builds trust; hiding it erodes it.","persona":"any","source":"reset together"},
  {"id":"ec-1199","cat":"lead-the-room","type":"role-play","hook":"You're unsure how to solve a problem your team is looking to you for.","setup":"Ask for help openly. Say:","yourLine":[{"text":"\"I don't have this one figured out. Let's crack it together.\"","best":true},{"text":"Bluff a confident answer you're not sure about"}],"relearn":"Good leaders ask for help and admit doubt; it builds trust.","persona":"any","source":"crack it together"},
  {"id":"ec-1200","cat":"lead-the-room","type":"role-play","hook":"A quieter teammate hasn't spoken in the whole planning meeting.","setup":"Invite them in. Say:","yourLine":[{"text":"\"Nikhil, you've been thinking. What's your read on this?\"","best":true},{"text":"Keep moving and only ask the people already talking"}],"relearn":"Deliberately inviting quieter voices in is inclusive leadership.","persona":"any","source":"nikhil your read"},
  {"id":"ec-1201","cat":"lead-the-room","type":"role-play","hook":"You're being offered a leadership role that stretches you and you feel underqualified.","setup":"Say yes to growth. Say:","yourLine":[{"text":"\"I'd like to take it on. I'll learn fast and ask when I'm stuck.\"","best":true},{"text":"\"I'm probably not ready. Give it to someone else.\""}],"relearn":"Say yes to stretch roles; you grow into them.","persona":"Aarti","source":"learn fast"},
  {"id":"ec-1202","cat":"lead-the-room","type":"role-play","hook":"In the wrap-up, the credit for a win is landing only on you.","setup":"Share the credit. Say:","yourLine":[{"text":"\"This was really a team effort. Anaya's idea was the turning point.\"","best":true},{"text":"Accept all the credit and move on"}],"relearn":"Sharing credit and naming people builds you as a leader.","persona":"any","source":"anaya turning point"},
  {"id":"ec-1203","cat":"lead-the-room","type":"role-play","hook":"A capable friend keeps saying she's 'not leadership material' before a club election.","setup":"Encourage her in. Say:","yourLine":[{"text":"\"You'd be great at this. Stand for it, and I'll back you.\"","best":true},{"text":"Agree she should sit it out to be safe"}],"relearn":"Encouraging others into leadership is leadership in itself.","persona":"any","source":"stand for it"},
  {"id":"ec-1204","cat":"lead-the-room","type":"role-play","hook":"Nobody's stepping up to coordinate a stalled group assignment.","setup":"Take initiative. Say:","yourLine":[{"text":"\"I'll map out the steps and split them. Shout if you want a different bit.\"","best":true},{"text":"Wait and hope someone more senior takes charge"}],"relearn":"Take initiative when there's a gap; that's leadership from any seat.","persona":"any","source":"map the steps"},
  {"id":"ec-1205","cat":"lead-the-room","type":"reflect","hook":"Lensy: leadership is something you can practise from any seat, starting today. What's true for you?","prompt":"What do you think?","options":["I can lead from where I am","No title needed","I'll take one initiative"],"affirm":"Leadership grows from small initiatives taken right where you are, no title, no waiting.","relearn":"You can lead from any seat; no title required.","persona":"any","source":"from any seat"},
  {"id":"ec-1206","cat":"lead-the-room","type":"reflect","hook":"Lensy: the kind of leader you'd want to follow. What do they do with credit?","prompt":"What feels right?","options":["Share it openly","Name the people","Make others bigger"],"affirm":"The leaders people most want to follow give credit generously and make others feel bigger.","relearn":"Sharing credit and making others bigger is the best kind of leadership.","persona":"any","source":"credit reflection"},
  {"id":"ec-1207","cat":"lead-the-room","type":"reflect","hook":"Lensy: your leadership style doesn't have to be loud to be real. How would you lead?","prompt":"What's your style?","options":["Quietly and steadily","By listening first","In my own way"],"affirm":"Quiet, listening, steady leadership is just as real and respected as the loud kind. Lead your way.","relearn":"Lead in your own style; quiet leadership counts as much as loud.","persona":"any","source":"your style"},
  {"id":"ec-1208","cat":"lead-the-room","type":"reflect","hook":"Lensy: a leader who says 'I don't know yet'. Does that feel weak or strong to you?","prompt":"What do you think?","options":["Strong and honest","Builds trust","Invites the team in"],"affirm":"Admitting you don't have every answer invites the team in and builds the trust real leaders rely on.","relearn":"Admitting doubt and asking for help builds trust as a leader.","persona":"any","source":"i dont know yet"},
  {"id":"ec-1209","cat":"lead-the-room","type":"reflect","hook":"Lensy: when a role stretches you and you don't feel ready, what's the move?","prompt":"What feels right?","options":["Say yes and grow","Learn on the way","Ask for support"],"affirm":"Nobody feels fully ready first; saying yes and growing into it is how leaders are made.","relearn":"Say yes to stretch leadership roles; you grow into them.","persona":"any","source":"stretch reflection"},
  {"id":"ec-1210","cat":"lead-the-room","type":"reflect","hook":"Lensy: when something goes wrong on your watch, where does a good leader put the focus?","prompt":"What do you think?","options":["Own it and fix it","Not on blame","Reset together"],"affirm":"Owning the outcome and turning to the fix, not the blame, is what keeps a team behind you.","relearn":"Owning mistakes, not blaming the team, builds you as a leader.","persona":"any","source":"own and fix"},
  {"id":"ec-1211","cat":"lead-the-room","type":"reflect","hook":"Lensy: noticing who hasn't spoken yet in a room. Is that a leader's job?","prompt":"What feels true?","options":["Yes, draw them in","Hear everyone","It's on the leader"],"affirm":"Noticing the unheard and drawing them in is exactly the work of an inclusive leader.","relearn":"Deliberately invite the quieter voices in; that's inclusive leading.","persona":"any","source":"who hasnt spoken"},
  {"id":"ec-1212","cat":"lead-the-room","type":"reflect","hook":"Lensy: encouraging a friend to step into a role she's good at. Is that leadership too?","prompt":"What do you think?","options":["Yes, it counts","Lift others up","Back them"],"affirm":"Spotting potential and backing someone into a role is leadership in itself. You grow leaders.","relearn":"Encouraging others into leadership is leadership in itself.","persona":"any","source":"encourage reflection"},
  {"id":"ec-1213","cat":"lead-the-room","type":"sort","hook":"Sort: everyday leadership, or just bossiness?","items":[{"id":"a","text":"Helping the team agree a direction"},{"id":"b","text":"Bossing people around to feel in control"},{"id":"c","text":"Giving credit generously"},{"id":"d","text":"Taking all the credit for the team's work"},{"id":"e","text":"Asking the quieter members for their view"},{"id":"f","text":"Talking over anyone who disagrees"}],"bins":[{"id":"leadership","label":"Leadership","valence":"pos"},{"id":"bossy","label":"Just bossy","valence":"neg"}],"key":{"a":"leadership","b":"bossy","c":"leadership","d":"bossy","e":"leadership","f":"bossy"},"relearn":"Finding direction, crediting and inviting input is leadership; controlling and credit-grabbing is just bossiness.","persona":"any","source":"leadership vs bossy"},
  {"id":"ec-1214","cat":"lead-the-room","type":"sort","hook":"Sort: builds you as a leader, or undercuts it?","items":[{"id":"a","text":"Owning your own mistakes"},{"id":"b","text":"Blaming the team when it fails"},{"id":"c","text":"Sharing the credit by name"},{"id":"d","text":"Hogging the spotlight"},{"id":"e","text":"Asking for help when stuck"},{"id":"f","text":"Pretending you know everything"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"undercuts","label":"Undercuts it","valence":"neg"}],"key":{"a":"builds","b":"undercuts","c":"builds","d":"undercuts","e":"builds","f":"undercuts"},"relearn":"Owning mistakes, sharing credit and asking for help build you; blaming, spotlight-hogging and faking certainty undercut it.","persona":"any","source":"leader habits"},
  {"id":"ec-1215","cat":"lead-the-room","type":"sort","hook":"Sort: a leadership move from any seat, or just waiting?","items":[{"id":"a","text":"Naming the next step when no one else does"},{"id":"b","text":"Waiting for someone senior to decide"},{"id":"c","text":"Bringing a skipped idea back into the room"},{"id":"d","text":"Staying quiet because you're junior"},{"id":"e","text":"Offering to coordinate the stalled task"},{"id":"f","text":"Assuming it's not your place to step in"}],"bins":[{"id":"lead","label":"Leading","valence":"pos"},{"id":"wait","label":"Just waiting","valence":"uhoh"}],"key":{"a":"lead","b":"wait","c":"lead","d":"wait","e":"lead","f":"wait"},"relearn":"Naming steps, lifting ideas and offering to coordinate is leading from any seat; waiting for a title isn't.","persona":"any","source":"lead vs wait"},
  {"id":"ec-1216","cat":"lead-the-room","type":"sort","hook":"Sort: makes the team bigger, or smaller?","items":[{"id":"a","text":"Crediting people by name"},{"id":"b","text":"Letting the loudest dominate"},{"id":"c","text":"Inviting quieter voices in"},{"id":"d","text":"Cutting people off mid-point"},{"id":"e","text":"Backing a good idea that isn't yours"},{"id":"f","text":"Dismissing ideas to push your own"}],"bins":[{"id":"bigger","label":"Bigger","valence":"pos"},{"id":"smaller","label":"Smaller","valence":"neg"}],"key":{"a":"bigger","b":"smaller","c":"bigger","d":"smaller","e":"bigger","f":"smaller"},"relearn":"Crediting, inviting and backing others' ideas grows the team; dominating and dismissing shrinks it.","persona":"any","source":"bigger team"},
  {"id":"ec-1217","cat":"lead-the-room","type":"sort","hook":"Sort: a quiet leadership move, or a missed chance?","items":[{"id":"a","text":"Sending clear notes after a chaotic meeting"},{"id":"b","text":"Staying silent when you spot a fix"},{"id":"c","text":"Checking in one-to-one with a stuck teammate"},{"id":"d","text":"Letting a confused plan run on"},{"id":"e","text":"Quietly bridging a teammate who froze"},{"id":"f","text":"Waiting to be told to help"}],"bins":[{"id":"quiet","label":"Quiet leading","valence":"pos"},{"id":"missed","label":"Missed chance","valence":"uhoh"}],"key":{"a":"quiet","b":"missed","c":"quiet","d":"missed","e":"quiet","f":"missed"},"relearn":"Clear notes, one-to-one check-ins and bridging a frozen teammate are quiet leadership; staying silent misses the chance.","persona":"any","source":"quiet leading"},
  {"id":"ec-1218","cat":"lead-the-room","type":"sort","hook":"Sort: a leader handing out work fairly, or hoarding the visible bits?","items":[{"id":"a","text":"Rotating who presents to the panel"},{"id":"b","text":"Always presenting yourself"},{"id":"c","text":"Giving a junior a stretch task"},{"id":"d","text":"Keeping all the high-visibility work"},{"id":"e","text":"Sharing the spotlight tasks around"},{"id":"f","text":"Leaving juniors only the admin"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"hoard","label":"Hoarding","valence":"neg"}],"key":{"a":"fair","b":"hoard","c":"fair","d":"hoard","e":"fair","f":"hoard"},"relearn":"Rotating visible work and handing juniors stretch tasks is fair leadership; hoarding the spotlight isn't.","persona":"any","source":"fair work"},
  {"id":"ec-1219","cat":"lead-the-room","type":"sort","hook":"Sort: grows you into a leader, or keeps you stuck?","items":[{"id":"a","text":"Saying yes to a stretch role"},{"id":"b","text":"Declining because you feel unready"},{"id":"c","text":"Volunteering to coordinate a gap"},{"id":"d","text":"Waiting until you're 'expert enough'"},{"id":"e","text":"Asking a mentor to check in"},{"id":"f","text":"Hiding so no one notices you"}],"bins":[{"id":"grows","label":"Grows you","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"uhoh"}],"key":{"a":"grows","b":"stuck","c":"grows","d":"stuck","e":"grows","f":"stuck"},"relearn":"Saying yes to stretch, volunteering and asking a mentor grow you; declining and hiding keep you stuck.","persona":"any","source":"grow vs stuck"},
  {"id":"ec-1220","cat":"lead-the-room","type":"sort","hook":"Sort: a leader sharing the floor, or grabbing it?","items":[{"id":"a","text":"Handing the mic to someone who knows more"},{"id":"b","text":"Talking over the expert to stay in charge"},{"id":"c","text":"Asking 'what does everyone think?'"},{"id":"d","text":"Answering every question yourself"},{"id":"e","text":"Pausing to let a slow speaker finish"},{"id":"f","text":"Filling every silence with your own voice"}],"bins":[{"id":"share","label":"Sharing","valence":"pos"},{"id":"grab","label":"Grabbing","valence":"neg"}],"key":{"a":"share","b":"grab","c":"share","d":"grab","e":"share","f":"grab"},"relearn":"Handing the floor to others and pausing for them is leadership; grabbing every turn isn't.","persona":"any","source":"share the floor"},
  {"id":"ec-1221","cat":"lead-the-room","type":"match","hook":"Match the leadership move to what it builds in a team.","relearn":"Each leadership move builds something specific: trust, courage, direction, inclusion or growth.","persona":"any","source":"move to effect","pairs":[{"left":"Owning your own mistake","right":"Builds trust"},{"left":"Backing a hesitant teammate","right":"Builds their courage"},{"left":"Naming a clear next step","right":"Gives the team direction"},{"left":"Inviting the quietest voice","right":"Builds an inclusive room"},{"left":"Saying yes to a stretch role","right":"Grows your own range"}]},
  {"id":"ec-1222","cat":"lead-the-room","type":"match","hook":"Match each leadership style to how it shows up in a room.","relearn":"Leadership comes in many real styles: quiet or loud, all of them count.","persona":"any","source":"style to look","pairs":[{"left":"Quiet leadership","right":"Listens first, then steers"},{"left":"By-example leadership","right":"Does the unglamorous bit too"},{"left":"Lifting leadership","right":"Puts others' names forward"},{"left":"Steady leadership","right":"Keeps calm when it goes wrong"},{"left":"Initiative leadership","right":"Moves first on a gap"}]},
  {"id":"ec-1223","cat":"lead-the-room","type":"match","hook":"Match the leader's line to the moment it fits.","relearn":"The right leadership line depends on the moment: crediting, inviting, owning or backing.","persona":"any","source":"line to moment","pairs":[{"left":"\"Full credit to Sara on this\"","right":"Sharing a win"},{"left":"\"What's your read, Kabir?\"","right":"Drawing in a quiet voice"},{"left":"\"That was my call to fix\"","right":"Owning a mistake"},{"left":"\"I'll back you, go for it\"","right":"Encouraging someone in"},{"left":"\"Let's pick one and try it\"","right":"Breaking a stalemate"}]},
  {"id":"ec-1224","cat":"lead-the-room","type":"match","hook":"Match the leadership myth to the truth that replaces it.","relearn":"Each leadership myth has a clear truth: no title needed, doubt builds trust, credit grows you.","persona":"any","source":"myth to truth","pairs":[{"left":"Leadership needs a title","right":"You can lead from any seat"},{"left":"Leaders never show doubt","right":"Admitting doubt builds trust"},{"left":"Sharing credit weakens you","right":"It grows your standing"},{"left":"Only loud people lead","right":"Quiet leadership counts fully"},{"left":"Wait till you're an expert","right":"You grow into the role"}]},
  {"id":"ec-1225","cat":"lead-the-room","type":"match","hook":"Match each team situation to the leadership move it calls for.","relearn":"Reading the situation tells you the move: a gap needs initiative, a stumble needs cover.","persona":"any","source":"situation to move","pairs":[{"left":"No one's deciding","right":"Name a next step"},{"left":"A teammate froze on stage","right":"Quietly pick up the thread"},{"left":"Loud few dominating","right":"Invite a quiet voice in"},{"left":"A skipped good idea","right":"Bring it back to the room"},{"left":"Better counter-plan than yours","right":"Back the better idea"}]},
  {"id":"ec-1226","cat":"lead-the-room","type":"match","hook":"Match the leader's habit to what it signals to the team.","relearn":"Leadership habits signal something: shared credit signals trust, asking for help signals openness.","persona":"any","source":"habit to signal","pairs":[{"left":"Shares credit by name","right":"Signals 'I see you'"},{"left":"Asks for help when stuck","right":"Signals it's safe to not know"},{"left":"Rotates the visible tasks","right":"Signals fairness"},{"left":"Owns the bad call","right":"Signals you can take risks"},{"left":"Invites the quiet voices","right":"Signals everyone belongs"}]},
  {"id":"ec-1227","cat":"lead-the-room","type":"match","hook":"Match each leadership choice to its long-run effect on the team.","relearn":"Lifting choices grow a team over time; dominating ones quietly shrink it.","persona":"any","source":"choice to effect","pairs":[{"left":"Crediting openly over months","right":"A team that stays motivated"},{"left":"Mentoring a junior","right":"A future leader"},{"left":"Sharing stretch tasks","right":"A team that grows together"},{"left":"Letting one person dominate","right":"A team that goes quiet"},{"left":"Hoarding every spotlight","right":"A team that disengages"}]},
  {"id":"ec-1235","cat":"lead-the-room","type":"spot","hook":"Spot the two lines that are bossiness dressed up as leadership, not the real thing.","scene":[{"id":"a","text":"\"Do it my way because I said so.\"","trick":true},{"id":"b","text":"\"Let's agree a direction together.\"","trick":false},{"id":"c","text":"\"I'll take the credit for this one.\"","trick":true},{"id":"d","text":"\"Great catch. That's your idea, run with it.\"","trick":false},{"id":"e","text":"\"What does everyone else think?\"","trick":false}],"why":"'My way, I said so' and grabbing credit are bossiness; the others are real leadership.","relearn":"Controlling and credit-grabbing is bossiness; finding direction and crediting is leadership.","persona":"any","source":"bossy not leader"},
  {"id":"ec-1228","cat":"lead-the-room","type":"spot","hook":"Spot the two moves that shrink the team instead of leading it.","scene":[{"id":"a","text":"Inviting the quietest member to speak","trick":false},{"id":"b","text":"Cutting a teammate off mid-point","trick":true},{"id":"c","text":"Naming who did what in the win","trick":false},{"id":"d","text":"Letting the loudest run every meeting","trick":true},{"id":"e","text":"Backing a good idea that isn't yours","trick":false}],"why":"Cutting people off and letting the loudest dominate shrink the team; inviting, crediting and backing others grow it.","relearn":"Cutting people off and letting the loudest dominate shrink a team.","persona":"any","source":"shrink the team"},
  {"id":"ec-1229","cat":"lead-the-room","type":"spot","hook":"Spot the two lines that fake leadership instead of building it.","scene":[{"id":"a","text":"\"I never make mistakes, so don't question me.\"","trick":true},{"id":"b","text":"\"That was my call. Here's the fix.\"","trick":false},{"id":"c","text":"\"When it failed, it was the team's fault.\"","trick":true},{"id":"d","text":"\"I'm not sure. Let's figure it out together.\"","trick":false},{"id":"e","text":"\"Honestly, Riya's research carried this.\"","trick":false}],"why":"'Never wrong' and blaming the team fake leadership; the others build it.","relearn":"Owning mistakes and admitting doubt build a leader; never-wrong and blame fake it.","persona":"any","source":"fake leadership"},
  {"id":"ec-1230","cat":"lead-the-room","type":"spot","hook":"Spot the two excuses for not leading from where you sit.","scene":[{"id":"a","text":"\"I'm too junior to suggest anything.\"","trick":true},{"id":"b","text":"\"I'll map the steps and split them.\"","trick":false},{"id":"c","text":"\"Not my place. Wait for someone senior.\"","trick":true},{"id":"d","text":"\"Let's go back to Meera's skipped point.\"","trick":false},{"id":"e","text":"\"I'll coordinate the stalled task.\"","trick":false}],"why":"'Too junior' and 'not my place' are excuses; mapping steps, lifting a skipped idea and coordinating are leading from any seat.","relearn":"You can lead from any seat; 'too junior' and 'not my place' are just excuses.","persona":"any","source":"excuses to wait"},
  {"id":"ec-1231","cat":"lead-the-room","type":"spot","hook":"Spot the two lines that hoard the floor instead of sharing it.","scene":[{"id":"a","text":"\"Let me answer every question myself.\"","trick":true},{"id":"b","text":"\"You know this better. Take five minutes.\"","trick":false},{"id":"c","text":"\"I'll talk over anyone who disagrees.\"","trick":true},{"id":"d","text":"\"Take your time, finish your point.\"","trick":false},{"id":"e","text":"\"What's everyone's read on this?\"","trick":false}],"why":"Answering everything yourself and talking over others hoard the floor; handing it over and pausing for people share it.","relearn":"Handing the floor to others and pausing for them is leadership; hoarding it isn't.","persona":"any","source":"hoard the floor"},
  {"id":"ec-1232","cat":"lead-the-room","type":"spot","hook":"Spot the two moves that keep you stuck instead of growing you as a leader.","scene":[{"id":"a","text":"Declining a stretch role on a hunch you're unready","trick":true},{"id":"b","text":"Saying yes and asking a mentor to check in","trick":false},{"id":"c","text":"Hiding so no one hands you anything","trick":true},{"id":"d","text":"Volunteering to coordinate a clear gap","trick":false},{"id":"e","text":"Taking on a task a little beyond you","trick":false}],"why":"Declining stretch roles and hiding keep you stuck; the others grow you.","relearn":"Saying yes to stretch and volunteering grow you; declining and hiding keep you stuck.","persona":"any","source":"stuck moves"},
  {"id":"ec-1233","cat":"lead-the-room","type":"spot","hook":"Spot the two lines that take credit instead of sharing it.","scene":[{"id":"a","text":"\"I basically did this whole thing alone.\"","trick":true},{"id":"b","text":"\"Anaya's idea was the turning point.\"","trick":false},{"id":"c","text":"\"No need to mention the others.\"","trick":true},{"id":"d","text":"\"Tarun's design carried the look.\"","trick":false},{"id":"e","text":"\"Full credit to the team on this.\"","trick":false}],"why":"Claiming you did it all and erasing the others take credit; naming people and crediting the team share it.","relearn":"Sharing and naming credit builds you; claiming it all undercuts you.","persona":"any","source":"take vs share credit"},
  {"id":"ec-1234","cat":"lead-the-room","type":"spot","hook":"Spot the two responses that fail a teammate who's struggling on stage.","scene":[{"id":"a","text":"Letting the awkward silence hang for them","trick":true},{"id":"b","text":"Gently picking up the thread for them","trick":false},{"id":"c","text":"Seizing the spotlight to outshine them","trick":true},{"id":"d","text":"Adding 'to build on that point…'","trick":false},{"id":"e","text":"Steadying the room with a calm aside","trick":false}],"why":"Letting them flounder and grabbing the spotlight fail them; the others lift them.","relearn":"Lifting and bridging a struggling teammate is leadership; abandoning or upstaging them isn't.","persona":"any","source":"teammate on stage"},
  {"id":"ec-1260","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"prove-it-again","relearn":"Re-proving themselves each time is the 'prove-it-again' bias, not weaker skill.","hook":"\"If she keeps having to re-prove herself, maybe she's just not that good.\"","myth":{"un":"If she keeps having to re-prove herself, she's probably not that good.","re":"Being asked to prove it again and again is a known bias; the same proof is taken on trust from others.","why":"The repeated burden is the bias, not a sign of weaker skill."}},
  {"id":"ec-1261","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"likeability","relearn":"Disliking a woman for the same confidence we admire in a man is the likeability bias.","hook":"\"She's good at the job, I just find her a bit much.\"","myth":{"un":"She's competent, I just find her a bit much.","re":"Liking a confident man but finding the same woman 'a bit much' is the likeability bias talking.","why":"The discomfort tracks her gender, not her actual behaviour."}},
  {"id":"ec-1262","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"luck-vs-skill","relearn":"Crediting her wins to luck or the team, his to skill, is attribution bias.","hook":"\"She got the deal: good luck and a strong team. He got his on pure skill.\"","myth":{"un":"Her win was luck and the team; his was pure skill.","re":"Putting her success down to luck or others, and his to ability, is attribution bias.","why":"The same result gets read as skill for him, fluke for her."}},
  {"id":"ec-1263","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"abrasive-feedback","relearn":"Feedback that polices a woman's tone instead of her work is gendered, not helpful.","hook":"\"Her review said 'abrasive' and 'too aggressive' but nothing about the actual work.\"","myth":{"un":"'Abrasive' and 'too aggressive' is fair feedback on her.","re":"Reviews that police a woman's tone while skipping her results are gendered feedback.","why":"Men with the same style get called direct, not abrasive."}},
  {"id":"ec-1264","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"smile-more","relearn":"Telling a woman to smile or soften is tone-policing, not professional advice.","hook":"\"Someone told her she'd go further if she just smiled more.\"","myth":{"un":"She'd go further if she smiled more and softened up.","re":"Telling a woman to smile or soften, while never saying it to men, is tone-policing.","why":"Her face and warmth aren't the job; the advice only flows one way."}},
  {"id":"ec-1265","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"motherhood-penalty","relearn":"Skipping a mother for a stretch role 'for her own good' is the motherhood penalty.","hook":"\"Don't give her the big project: she's a new mum, she won't want the pressure.\"","myth":{"un":"Don't offer her the stretch role; as a new mum she won't want it.","re":"Deciding for a mother that she can't handle big work is the motherhood penalty: ask, don't assume.","why":"Assuming her choices for her quietly sidelines her career."}},
  {"id":"ec-1266","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"diversity-hire","relearn":"Calling a qualified woman a 'diversity hire' erases her merit; it's a bias, not a fact.","hook":"\"She only got in because they needed more women, a diversity hire.\"","myth":{"un":"She only got the role to fill a women's quota.","re":"Branding a qualified woman a 'diversity hire' erases the merit that got her in.","why":"It assumes she couldn't have earned it, which is the bias."}},
  {"id":"ec-1267","cat":"spot-counter-bias","type":"strike-rewrite","persona":"Rohan","source":"hepeating","relearn":"A woman's idea ignored, then praised from a man, is 'hepeating': re-credit her.","hook":"\"Her idea got nothing; he said it ten minutes later and the room loved it.\"","myth":{"un":"If her idea only landed when he said it, it wasn't ready when she did.","re":"An idea ignored from her, then praised from a man, is 'hepeating': same idea, different messenger.","why":"The room rewarded the speaker's gender, not the idea's timing."}},
  {"id":"ec-1268","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"benevolent-sexism","relearn":"'Protecting' a woman out of hard work is benevolent sexism; let her choose.","hook":"\"I didn't send her to the tough client site. I was protecting her.\"","myth":{"un":"Keeping her off the tough assignment was me protecting her.","re":"'Protecting' a woman out of demanding work is benevolent sexism; it still costs her the chance.","why":"Kindly-meant gatekeeping is still gatekeeping."}},
  {"id":"ec-1270","cat":"spot-counter-bias","type":"strike-rewrite","persona":"Aarti","source":"marriage-question","relearn":"Asking only women about marriage plans in interviews is biased and off-limits.","hook":"\"In my interview they asked when I plan to marry, never asked the men.\"","myth":{"un":"Asking a woman candidate about marriage plans is just normal small talk.","re":"Quizzing only women on marriage or kids in hiring is bias. It judges her on a future, not the work.","why":"It treats her life plans as a risk it never weighs for men."}},
  {"id":"ec-1272","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"competence-penalty","relearn":"A woman seen as competent OR likeable, rarely both, is the double-bind, not reality.","hook":"\"Warm women seem soft; tough women seem cold. Can't she just be both?\"","myth":{"un":"A woman is either warm or tough; she can't really be both.","re":"Being forced to choose warm-but-weak or strong-but-cold is the double-bind women face, not a real limit.","why":"Men are allowed to be both at once; the trap is the bias."}},
  {"id":"ec-1273","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"glass-cliff","relearn":"Handing women leadership only in a crisis sets them up to fail: the 'glass cliff'.","hook":"\"They finally made her head of the failing division nobody else wanted.\"","myth":{"un":"She got the top job, so the bias clearly didn't touch her.","re":"Promoting women mainly into failing units they're likely to be blamed for is the 'glass cliff'.","why":"The title comes with the highest chance of falling, by design."}},
  {"id":"ec-1274","cat":"spot-counter-bias","type":"spot","persona":"any","source":"meeting-floor","relearn":"Cutting her off and answering for her are the floor-grabbing red flags to catch.","hook":"Spot the two things stealing her floor.","scene":[{"id":"a","text":"He cuts across her mid-sentence to finish her point","trick":true},{"id":"b","text":"The chair asks her to keep going","trick":false},{"id":"c","text":"He answers a question that was put to her","trick":true},{"id":"d","text":"Her point is noted with her name on it","trick":false},{"id":"e","text":"Everyone waits for her to land the thought","trick":false}],"why":"Cutting across her and answering for her grab her floor; the others hand it back."},
  {"id":"ec-1275","cat":"spot-counter-bias","type":"spot","persona":"any","source":"hiring-bias","relearn":"Judging her on looks and marriage, not the CV, are the hiring red flags to catch.","hook":"Spot the two biased moves in this hiring chat.","scene":[{"id":"a","text":"\"She's qualified, but is she planning a family soon?\"","trick":true},{"id":"b","text":"\"Let's score every CV on the same rubric.\"","trick":false},{"id":"c","text":"\"She looked a bit too glamorous to be serious.\"","trick":true},{"id":"d","text":"\"Her project results match the role well.\"","trick":false},{"id":"e","text":"\"Both finalists get the same task to try.\"","trick":false}],"why":"Weighing her family plans and her looks is bias; scoring the work fairly isn't."},
  {"id":"ec-1324","cat":"spot-counter-bias","type":"spot","persona":"any","source":"praise-bias","relearn":"Praising her looks and her tidiness, not her work, are the red flags to catch.","hook":"Spot the two backhanded 'compliments'.","scene":[{"id":"a","text":"\"You're so well organised. You'd run a lovely home.\"","trick":true},{"id":"b","text":"\"Your analysis caught the error nobody saw.\"","trick":false},{"id":"c","text":"\"You look great today. That's half the battle won.\"","trick":true},{"id":"d","text":"\"Your plan moved the project a week ahead.\"","trick":false},{"id":"e","text":"\"Strong call on the vendor, saved us money.\"","trick":false}],"why":"Praising her home-making and looks sidelines her work; the result-based praise doesn't."},
  {"id":"ec-1276","cat":"spot-counter-bias","type":"spot","persona":"any","source":"task-allocation","relearn":"Defaulting notes and party-planning to women are the task red flags to catch.","hook":"Spot the two times work gets defaulted by gender.","scene":[{"id":"a","text":"\"Priya, you'll take the minutes again, yeah?\"","trick":true},{"id":"b","text":"\"Let's rotate who runs the standup this month.\"","trick":false},{"id":"c","text":"\"The women can sort the farewell party.\"","trick":true},{"id":"d","text":"\"Whoever's free grabs the client deck.\"","trick":false},{"id":"e","text":"\"We'll share the on-call evenly.\"","trick":false}],"why":"Defaulting minutes and party-planning to women is bias; rotating and sharing isn't."},
  {"id":"ec-1277","cat":"spot-counter-bias","type":"spot","persona":"any","source":"credit-bias","relearn":"Re-crediting her idea and renaming her work are the credit red flags to catch.","hook":"Spot the two moves that take her credit.","scene":[{"id":"a","text":"The boss thanks Arjun for 'his' framework. Neha built it","trick":true},{"id":"b","text":"\"That was Neha's design, credit to her.\"","trick":false},{"id":"c","text":"Her slide gets renamed under a colleague's name","trick":true},{"id":"d","text":"Her name stays on the doc she authored","trick":false},{"id":"e","text":"\"Neha walk us through your model.\"","trick":false}],"why":"Mis-thanking a man and renaming her work steal her credit; the others keep it hers."},
  {"id":"ec-1278","cat":"spot-counter-bias","type":"spot","persona":"any","source":"who-gets-stretch","relearn":"Steering visible work to the men are the opportunity red flags to catch.","hook":"Spot the two times the good work skips her.","scene":[{"id":"a","text":"The keynote slot goes to Vikram 'who presents better'","trick":true},{"id":"b","text":"The stretch project is offered to whoever wants it","trick":false},{"id":"c","text":"She's handed the admin while men get the client","trick":true},{"id":"d","text":"Visible roles rotate across the team","trick":false},{"id":"e","text":"Mentoring is open to everyone who asks","trick":false}],"why":"Defaulting the visible work to men is bias; rotating and opening it up isn't."},
  {"id":"ec-1279","cat":"spot-counter-bias","type":"spot","persona":"any","source":"assumptions","relearn":"Assuming the man leads and the woman serves are the role-assumption red flags.","hook":"Spot the two wrong gender assumptions.","scene":[{"id":"a","text":"Greeting the junior man as the lead, ignoring her","trick":true},{"id":"b","text":"Asking the room who's heading the project","trick":false},{"id":"c","text":"Assuming she's the assistant, not the engineer","trick":true},{"id":"d","text":"Checking each person's actual role first","trick":false},{"id":"e","text":"Addressing whoever introduced themselves as lead","trick":false}],"why":"Assuming the man leads and she serves are biases; asking instead of assuming isn't."},
  {"id":"ec-1280","cat":"spot-counter-bias","type":"spot","persona":"any","source":"interview-panel","relearn":"Reading her drive as 'aggressive' and his as 'leadership' is the red flag.","hook":"Spot the two double-standard judgements.","scene":[{"id":"a","text":"\"She's a bit aggressive\": same drive he's praised for","trick":true},{"id":"b","text":"\"Both showed strong initiative.\"","trick":false},{"id":"c","text":"\"He's a natural leader; she's bossy\": same behaviour","trick":true},{"id":"d","text":"\"Let's go on the rubric, not vibes.\"","trick":false},{"id":"e","text":"\"Each gave a clear, specific answer.\"","trick":false}],"why":"Reading her drive as aggression and her lead as bossiness is the double standard; the rest judge fairly."},
  {"id":"ec-1281","cat":"spot-counter-bias","type":"spot","persona":"Rohan","source":"banter-bias","relearn":"A sexist 'joke' and a talk-over are the red flags to catch, kindly.","hook":"Spot the two things worth calling in.","scene":[{"id":"a","text":"\"Cute that she thinks she can lead this\": as a 'joke'","trick":true},{"id":"b","text":"A laugh at someone's self-deprecating story","trick":false},{"id":"c","text":"Talking over her every time she starts","trick":true},{"id":"d","text":"Ribbing that everyone, including her, is in on","trick":false},{"id":"e","text":"Asking her to say more about her idea","trick":false}],"why":"The 'joke' at her expense and the constant talk-over are biases to call in; shared banter isn't."},
  {"id":"ec-1282","cat":"spot-counter-bias","type":"spot","persona":"any","source":"mansplaining","relearn":"Explaining her own field to her and doubting her data are the red flags.","hook":"Spot the two times her expertise is doubted.","scene":[{"id":"a","text":"He explains her own speciality back to her, slowly","trick":true},{"id":"b","text":"A colleague asks her a genuine question to learn","trick":false},{"id":"c","text":"\"Are you sure?\" to her data, never to his","trick":true},{"id":"d","text":"Everyone's numbers get the same sanity-check","trick":false},{"id":"e","text":"She's invited to lead the technical review","trick":false}],"why":"Explaining her field to her and doubting only her data assume she knows less; the rest don't."},
  {"id":"ec-1283","cat":"spot-counter-bias","type":"spot","persona":"any","source":"return-from-leave","relearn":"Quietly demoting and doubting her after leave are the maternal-wall red flags.","hook":"Spot the two ways she's sidelined after maternity leave.","scene":[{"id":"a","text":"Her accounts quietly reassigned 'to be kind'","trick":true},{"id":"b","text":"A check-in on what support she'd like","trick":false},{"id":"c","text":"\"Is she still really committed now?\" assumed, not asked","trick":true},{"id":"d","text":"Her old projects handed straight back to her","trick":false},{"id":"e","text":"A flexible plan agreed together","trick":false}],"why":"Stripping her work 'to be kind' and doubting her commitment are the maternal wall; asking and restoring aren't."},
  {"id":"ec-1284","cat":"spot-counter-bias","type":"spot","persona":"Zoya","source":"inclusion-bias","relearn":"Mis-gendering and freezing out a queer colleague are the red flags to catch.","hook":"Spot the two ways a colleague gets excluded.","scene":[{"id":"a","text":"Her partner pointedly left out of the 'plus-ones'","trick":true},{"id":"b","text":"The invite asks everyone's plus-one by name","trick":false},{"id":"c","text":"Her pronouns 'forgotten' again after being told","trick":true},{"id":"d","text":"Her correction noted and used from then on","trick":false},{"id":"e","text":"She's drawn into the off-site planning","trick":false}],"why":"Excluding her partner and ignoring her pronouns are exclusion; including and correcting aren't."},
  {"id":"ec-1285","cat":"spot-counter-bias","type":"spot","persona":"any","source":"pay-bias","relearn":"'She doesn't need it' and 'she won't ask' are the pay-gap red flags to catch.","hook":"Spot the two biased reasons behind a pay gap.","scene":[{"id":"a","text":"\"He's got a family to support, give him more.\"","trick":true},{"id":"b","text":"\"Pay the band for the role, same for all.\"","trick":false},{"id":"c","text":"\"She won't ask, so we needn't raise hers.\"","trick":true},{"id":"d","text":"\"Benchmark every offer to the market.\"","trick":false},{"id":"e","text":"\"Same level, same range, no exceptions.\"","trick":false}],"why":"'He needs it more' and 'she won't ask' justify a gap; banding pay to the role doesn't."},
  {"id":"ec-1286","cat":"spot-counter-bias","type":"spot","persona":"any","source":"networking-bias","relearn":"Deals settled in men-only spaces are the access red flags to catch.","hook":"Spot the two times she's locked out of the room that matters.","scene":[{"id":"a","text":"Key calls made on the boys' smoke break","trick":true},{"id":"b","text":"Decisions taken in the open team meeting","trick":false},{"id":"c","text":"The deal sealed at a men-only dinner","trick":true},{"id":"d","text":"Notes shared so anyone absent stays looped","trick":false},{"id":"e","text":"Mentoring offered across the whole team","trick":false}],"why":"Settling work in men-only spaces locks her out; open meetings and shared notes don't."},
  {"id":"ec-1287","cat":"spot-counter-bias","type":"sort","persona":"any","source":"bias-or-fair","relearn":"Tone-policing and 'diversity hire' are bias; one rubric and rotation are fair.","hook":"Sort each into bias or fair treatment.","items":[{"id":"a","text":"Telling only the women to 'smile more'"},{"id":"b","text":"Same review rubric for everyone"},{"id":"c","text":"Calling a qualified woman a 'diversity hire'"},{"id":"d","text":"Rotating the visible projects"},{"id":"e","text":"Asking only her about marriage plans"},{"id":"f","text":"Crediting ideas to whoever had them"}],"bins":[{"id":"bias","label":"Everyday bias","valence":"neg"},{"id":"fair","label":"Fair treatment","valence":"pos"}],"key":{"a":"bias","b":"fair","c":"bias","d":"fair","e":"bias","f":"fair"}},
  {"id":"ec-1288","cat":"spot-counter-bias","type":"sort","persona":"any","source":"label-double-bind","relearn":"The same trait is a leader's word for men, a slur for women.","hook":"Sort how the SAME trait gets labelled by gender.","items":[{"id":"a","text":"A man states his view: 'confident'"},{"id":"b","text":"A woman states hers: 'bossy'"},{"id":"c","text":"A man pushes back: 'principled'"},{"id":"d","text":"A woman pushes back: 'difficult'"},{"id":"e","text":"A man is ambitious: 'driven'"},{"id":"f","text":"A woman is ambitious: 'ruthless'"}],"bins":[{"id":"praised","label":"Praised (men)","valence":"pos"},{"id":"penalised","label":"Penalised (women)","valence":"neg"}],"key":{"a":"praised","b":"penalised","c":"praised","d":"penalised","e":"praised","f":"penalised"}},
  {"id":"ec-1289","cat":"spot-counter-bias","type":"sort","persona":"any","source":"counter-or-worsen","relearn":"Calling in, amplifying and rotating counter bias; mocking and silence don't.","hook":"Sort: does it counter bias, or let it stand?","items":[{"id":"a","text":"Quietly re-crediting her idea to her"},{"id":"b","text":"Publicly mocking the person who slipped"},{"id":"c","text":"Repeating her point to amplify it"},{"id":"d","text":"Shrugging: 'not my problem'"},{"id":"e","text":"Rotating the note-taking fairly"},{"id":"f","text":"Saying nothing, every time"}],"bins":[{"id":"counters","label":"Counters bias","valence":"pos"},{"id":"lets","label":"Lets it stand","valence":"neg"}],"key":{"a":"counters","b":"lets","c":"counters","d":"lets","e":"counters","f":"lets"}},
  {"id":"ec-1290","cat":"spot-counter-bias","type":"sort","persona":"any","source":"attribution-bias","relearn":"Her win read as luck and his as skill is attribution bias.","hook":"Sort how a win gets explained by gender.","items":[{"id":"a","text":"Her big result: 'she got lucky'"},{"id":"b","text":"His big result: 'pure skill'"},{"id":"c","text":"Her promotion: 'good timing'"},{"id":"d","text":"His promotion: 'he earned it'"},{"id":"e","text":"Her idea worked: 'the team carried it'"},{"id":"f","text":"His idea worked: 'great instincts'"}],"bins":[{"id":"discount","label":"Discounted (her)","valence":"neg"},{"id":"credit","label":"Credited (him)","valence":"pos"}],"key":{"a":"discount","b":"credit","c":"discount","d":"credit","e":"discount","f":"credit"}},
  {"id":"ec-1291","cat":"spot-counter-bias","type":"sort","persona":"any","source":"office-housework","relearn":"Notes and cleanup default to women; lead and demo stay visible.","hook":"Sort the task by who it usually gets defaulted to.","items":[{"id":"a","text":"Taking the minutes"},{"id":"b","text":"Pitching to the client"},{"id":"c","text":"Organising the farewell"},{"id":"d","text":"Leading the design review"},{"id":"e","text":"Tidying the shared drive"},{"id":"f","text":"Demoing at the all-hands"}],"bins":[{"id":"defaulted","label":"Defaulted to women","valence":"uhoh"},{"id":"visible","label":"Kept high-visibility","valence":"pos"}],"key":{"a":"defaulted","b":"visible","c":"defaulted","d":"visible","e":"defaulted","f":"visible"}},
  {"id":"ec-1292","cat":"spot-counter-bias","type":"sort","persona":"any","source":"benevolent-or-respect","relearn":"'Protecting' her out of chances is benevolent sexism.","hook":"Sort: benevolent sexism, or respect?","items":[{"id":"a","text":"'Sparing' her the late trip, unasked"},{"id":"b","text":"Asking if she wants the late trip"},{"id":"c","text":"Keeping her off 'stressful' accounts"},{"id":"d","text":"Offering her the big account openly"},{"id":"e","text":"Deciding a new mum 'won't want' it"},{"id":"f","text":"Letting her decide on the role"}],"bins":[{"id":"benevolent","label":"Benevolent sexism","valence":"uhoh"},{"id":"respect","label":"Real respect","valence":"pos"}],"key":{"a":"benevolent","b":"respect","c":"benevolent","d":"respect","e":"benevolent","f":"respect"}},
  {"id":"ec-1293","cat":"spot-counter-bias","type":"role-play","persona":"Rohan","source":"call-in-joke","relearn":"Call in a sexist 'joke' lightly but clearly, on the spot.","hook":"A teammate jokes she 'only leads because she's the diversity pick'.","setup":"Call it in, lightly but clearly. Say:","yourLine":[{"text":"\"She leads because she's good at it. Let's drop that one.\"","best":true},{"text":"Laugh it off so it's not awkward"}]},
  {"id":"ec-1294","cat":"spot-counter-bias","type":"role-play","persona":"any","source":"reclaim-after-interrupt","relearn":"Calmly reclaim the floor when you're cut off; you don't have to wait.","hook":"You're cut off mid-point for the third time today.","setup":"Reclaim the floor, calmly. Say:","yourLine":[{"text":"\"Let me finish my point, then I'd love your take.\"","best":true},{"text":"Trail off and let it go again"}]},
  {"id":"ec-1295","cat":"spot-counter-bias","type":"role-play","persona":"any","source":"recredit-hepeat","relearn":"Re-credit an idea to the woman who first said it.","hook":"A man repeats Neha's idea and the room finally claps.","setup":"Put the credit back. Say:","yourLine":[{"text":"\"Glad it landed. That was Neha's idea earlier.\"","best":true},{"text":"Say nothing and let him keep it"}]},
  {"id":"ec-1296","cat":"spot-counter-bias","type":"role-play","persona":"Zoya","source":"name-tone-policing","relearn":"Name tone-policing gently and turn it back to the work.","hook":"Your manager says you'd 'get further if you smiled more'.","setup":"Name it, kindly. Say:","yourLine":[{"text":"\"I'd rather be judged on the work. How's it looking?\"","best":true},{"text":"Apologise and promise to smile more"}]},
  {"id":"ec-1297","cat":"spot-counter-bias","type":"role-play","persona":"Rohan","source":"interrupt-the-interruption","relearn":"Interrupt the interruption and hand the floor back to her.","hook":"A colleague keeps talking over Priya in the review.","setup":"Hand the floor back. Say:","yourLine":[{"text":"\"Hang on. Priya wasn't done. Go on, Priya.\"","best":true},{"text":"Let it slide; he'll stop eventually"}]},
  {"id":"ec-1298","cat":"spot-counter-bias","type":"role-play","persona":"any","source":"redirect-the-question","relearn":"Redirect a question answered for her back to her.","hook":"Someone answers a technical question that was clearly put to her.","setup":"Send it back to her. Say:","yourLine":[{"text":"\"Actually that's Meera's call. Meera, what do you think?\"","best":true},{"text":"Let him keep answering for her"}]},
  {"id":"ec-1299","cat":"spot-counter-bias","type":"role-play","persona":"Aarti","source":"refuse-default-notes","relearn":"Decline the defaulted notes and suggest rotating, without over-apologising.","hook":"You're asked to take the minutes 'as usual'. Always you.","setup":"Suggest a fair rotation. Say:","yourLine":[{"text":"\"I did them last time. Shall we rotate it round?\"","best":true},{"text":"\"Sorry, sure, I'll do them again.\""}]},
  {"id":"ec-1300","cat":"spot-counter-bias","type":"branch","persona":"any","source":"witness-credit-theft","relearn":"Re-credit an idea on the spot to the person who actually had it.","hook":"In the all-hands, the lead thanks Arjun for a plan Sneha built.","options":[{"text":"Note warmly that it was Sneha's plan","consequence":"The room re-credits her; she's seen.","outcome":"corrected","best":true},{"text":"Tell Sneha privately she was robbed","consequence":"She feels backed, but the room still credits the wrong person."},{"text":"Say nothing, not worth the fuss","consequence":"Her work stays under his name and the pattern repeats."}],"debrief":"Crediting it in the moment fixes the record where everyone can hear it."},
  {"id":"ec-1301","cat":"spot-counter-bias","type":"branch","persona":"any","source":"own-bias-check","relearn":"Catch your own gendered label and reframe it before it lands.","hook":"Writing a review, you almost call her 'abrasive' for being direct.","options":[{"text":"Swap it for what you'd write of a man: 'direct'","consequence":"You catch your own double standard.","outcome":"self-aware","best":true},{"text":"Leave 'abrasive' in: it's just the right word","consequence":"A gendered label lands in her record."},{"text":"Drop the note but quietly mark her down","consequence":"The bias still hits her score, just unstated."}],"debrief":"Checking your own labels matters as much as catching others'."},
  {"id":"ec-1302","cat":"spot-counter-bias","type":"branch","persona":"any","source":"allocate-stretch","relearn":"Offer the stretch role openly; don't assume a mum won't want it.","hook":"A visible project's free; you assume the new mum won't want the pressure.","options":[{"text":"Offer it to her and let her decide","consequence":"She chooses for herself; the role stays open.","outcome":"fair","best":true},{"text":"Quietly give it to someone 'freer'","consequence":"She's sidelined by an assumption she never answered."},{"text":"Hint she'd struggle, so she withdraws","consequence":"You engineer the 'no' and call it her choice."}],"debrief":"Ask, don't assume. The motherhood penalty runs on unasked assumptions."},
  {"id":"ec-1303","cat":"spot-counter-bias","type":"branch","persona":"Rohan","source":"call-in-not-out","relearn":"Call a repeat interrupter in privately: a chance to change, not a public hit.","hook":"A teammate keeps cutting women off; you want it to stop.","options":[{"text":"Have a quiet word naming the pattern","consequence":"He hears it without humiliation and adjusts.","outcome":"called-in","best":true},{"text":"Call him out hard next meeting","consequence":"He gets defensive; little changes."},{"text":"Hope someone else says something","consequence":"Nobody does; the interrupting carries on."}],"debrief":"Calling in privately gives a real chance to change; public shaming rarely does."},
  {"id":"ec-1304","cat":"spot-counter-bias","type":"branch","persona":"any","source":"diversity-hire-slur","relearn":"Shut down the 'diversity hire' slur by pointing back to her merit.","hook":"At lunch someone calls a new colleague 'just a diversity hire'.","options":[{"text":"Point to the work that got her in","consequence":"The slur is checked; her merit stands.","outcome":"defended","best":true},{"text":"Nod along to keep the peace","consequence":"The slur spreads and follows her into the team."},{"text":"Agree she got 'a bit of a leg up'","consequence":"You add weight to a bias with no basis."}],"debrief":"Naming her merit ends the 'diversity hire' framing fast."},
  {"id":"ec-1305","cat":"spot-counter-bias","type":"branch","persona":"any","source":"panel-double-standard","relearn":"Flag a double standard by checking it against a man's review.","hook":"On a panel, a strong woman is marked down as 'too aggressive'.","options":[{"text":"Ask if we'd say that about a man with her record","consequence":"The panel rechecks; the gendered mark is dropped.","outcome":"rechecked","best":true},{"text":"Let the score stand to avoid friction","consequence":"A biased mark sinks a qualified candidate."},{"text":"Add a note that she 'seemed intense'","consequence":"You stack a second gendered judgement on top."}],"debrief":"The 'would we say it about a man?' test surfaces the double standard fast."},
  {"id":"ec-1306","cat":"spot-counter-bias","type":"branch","persona":"any","source":"who-plans-party","relearn":"Rotate the 'office housework' instead of defaulting it to women.","hook":"\"The girls will sort the team lunch, right?\" lands in the chat.","options":[{"text":"Suggest a rota so it's shared by all","consequence":"The load spreads; nobody's defaulted by gender.","outcome":"shared","best":true},{"text":"Let the women just handle it again","consequence":"The unpaid organising keeps landing on the same people."},{"text":"Volunteer one woman so the rest are off","consequence":"It's still defaulted by gender, just to fewer."}],"debrief":"A simple rota turns defaulted 'office housework' into shared work."},
  {"id":"ec-1307","cat":"spot-counter-bias","type":"reflect","persona":"any","source":"notice-your-rooms","relearn":"Notice the everyday biases in your own rooms. Naming them is the first power.","hook":"Lensy: think of a room you're in often. Whose voice gets the floor, the credit, the admin?","prompt":"What pattern do you notice?","options":["I see who's talked over","I see who gets the admin","I see who gets the credit","Honestly, I'd never looked"],"affirm":"Seeing the pattern is the first power; once you've named it, you can start to counter it."},
  {"id":"ec-1308","cat":"spot-counter-bias","type":"reflect","persona":"any","source":"caught-own-bias","relearn":"We all carry biases; catching your own is growth, not guilt.","hook":"Lensy: ever caught yourself making a gendered assumption, like who'd lead, who'd take notes?","prompt":"How did it sit with you?","options":["Yes, and I reframed it","Yes, still working on it","Not yet, but I'll watch for it","I'd like to get better at it"],"affirm":"Catching your own assumptions is growth, not guilt. Everyone carries some, and you're checking yours."},
  {"id":"ec-1309","cat":"spot-counter-bias","type":"reflect","persona":"any","source":"call-in-comfort","relearn":"You get to choose how you call bias in. Your style still counts.","hook":"Lensy: calling bias in can be a quiet word or a light line in the moment. Both work.","prompt":"Which feels more like you?","options":["A quiet private word","A light line on the spot","Depends on the room","Still finding my way"],"affirm":"There's no single right way. Your style of calling it in counts as much as anyone's."},
  {"id":"ec-1310","cat":"spot-counter-bias","type":"reflect","persona":"any","source":"unsee-it","relearn":"Once you can see everyday bias, you can name and counter it.","hook":"Lensy: once you can spot the everyday stuff, you can't unsee it, and you can counter it.","prompt":"Where are you with that?","options":["I see it clearly now","I'm starting to","I want to see it better","It changes how I look at rooms"],"affirm":"Once it's visible, it stays visible, and seeing it is what lets you counter it."},
  {"id":"ec-1311","cat":"spot-counter-bias","type":"reflect","persona":"Aarti","source":"tone-on-you","relearn":"Being tone-policed says more about the bias than about you.","hook":"Lensy: been told you're 'too much' or to 'smile more'? That label is about the bias, not you.","prompt":"What do you want to remember?","options":["The work speaks for me","I won't shrink for it","I can name it next time","I belong in the room"],"affirm":"That label is about the bias, not about you. You don't have to shrink to fit it."},
  {"id":"ec-1312","cat":"spot-counter-bias","type":"reflect","persona":"any","source":"small-counters","relearn":"Small counters, like re-crediting, amplifying and rotating, add up to a fairer room.","hook":"Lensy: the small moves, like re-crediting, amplifying and rotating the admin, add up.","prompt":"Which one will you try?","options":["Re-credit an idea","Amplify a point","Suggest a rota","All of them, over time"],"affirm":"Small counters, repeated, are what shift a room over time. Any one is a real start."},
  {"id":"ec-1313","cat":"spot-counter-bias","type":"reflect","persona":"Rohan","source":"ally-not-savior","relearn":"Spotting bias isn't about being the hero; follow the lead of those affected.","hook":"Lensy: spotting bias for others isn't about being the hero. It's backing their lead.","prompt":"What feels right to you?","options":["Ask how they want backing","Amplify, don't centre myself","Follow their lead","Act, then check in"],"affirm":"Backing someone's lead, not taking it over, is what makes allyship land. That instinct is right."},
  {"id":"ec-1314","cat":"spot-counter-bias","type":"match","persona":"any","source":"bias-to-name","relearn":"Each everyday bias has a name. Naming it makes it easier to counter.","hook":"Match each move to the bias it shows.","pairs":[{"left":"Her idea praised only when he repeats it","right":"Hepeating"},{"left":"Notes always defaulted to the women","right":"Office housework"},{"left":"Her win called luck, his called skill","right":"Attribution bias"},{"left":"'You'd go further if you smiled'","right":"Tone-policing"},{"left":"'Don't give the new mum the big role'","right":"Motherhood penalty"}]},
  {"id":"ec-1315","cat":"spot-counter-bias","type":"match","persona":"any","source":"counter-move","relearn":"Each bias has a clean counter-move you can use in the moment.","hook":"Match each bias to the move that counters it.","pairs":[{"left":"Her point ignored in the meeting","right":"Amplify and credit it"},{"left":"She's cut off mid-sentence","right":"Interrupt the interruption"},{"left":"Notes default to her again","right":"Suggest a rota"},{"left":"Her idea re-credited to a man","right":"Re-credit it to her"},{"left":"A sexist 'joke' lands","right":"Call it in lightly"}]},
  {"id":"ec-1316","cat":"spot-counter-bias","type":"match","persona":"any","source":"same-trait-label","relearn":"The same trait gets a leader's word for a man and a slur for a woman.","hook":"Match the man's praised label to the woman's penalised one for the SAME trait.","pairs":[{"left":"Confident (him)","right":"Bossy (her)"},{"left":"Driven (him)","right":"Ruthless (her)"},{"left":"Principled (him)","right":"Difficult (her)"},{"left":"Direct (him)","right":"Abrasive (her)"},{"left":"Passionate (him)","right":"Emotional (her)"}]},
  {"id":"ec-1317","cat":"spot-counter-bias","type":"match","persona":"any","source":"call-in-script","relearn":"Each bias moment has a kind, clear line you can actually say.","hook":"Match the moment to a line that calls it in.","pairs":[{"left":"He answers a question put to her","right":"\"Let's hear her take on it.\""},{"left":"Her plan credited to him","right":"\"That was actually her plan.\""},{"left":"Only women asked to plan the party","right":"\"Shall we rotate this one?\""},{"left":"She's marked 'too aggressive'","right":"\"Would we say that about a man?\""},{"left":"\"Smile more,\" they tell her","right":"\"Judge the work, not the face.\""}]},
  {"id":"ec-1318","cat":"spot-counter-bias","type":"match","persona":"any","source":"bias-vs-fair","relearn":"Tell the biased move from its fair twin in the same situation.","hook":"Match each biased move to its fair twin.","pairs":[{"left":"Ask only her about marriage plans","right":"Ask every candidate the same questions"},{"left":"Default the minutes to her","right":"Rotate the minutes round the team"},{"left":"Greet the man as the lead","right":"Ask who's actually leading"},{"left":"Call her 'a diversity hire'","right":"Point to the work she did"},{"left":"Credit her idea to a man","right":"Credit the idea to whoever had it"}]},
  {"id":"ec-1319","cat":"spot-counter-bias","type":"match","persona":"any","source":"who-said-it","relearn":"Benevolent-sounding lines can still gatekeep; the respectful version asks.","hook":"Match the 'protective' line to its respectful version.","pairs":[{"left":"\"I'll spare her the late trip.\"","right":"\"Do you want the late trip?\""},{"left":"\"She won't want that pressure.\"","right":"\"Would you like this role?\""},{"left":"\"Too stressful for a new mum.\"","right":"\"Here's the project. Your call.\""},{"left":"\"I'll keep her off the tough client.\"","right":"\"This client's open if you want it.\""},{"left":"\"Better not to overload her.\"","right":"\"What would you like to take on?\""}]},
  {"id":"ec-1320","cat":"spot-counter-bias","type":"match","persona":"any","source":"trait-double-standard","relearn":"Spot how identical workplace behaviour gets a split judgement by gender.","hook":"Match the behaviour to how it's judged by gender.","pairs":[{"left":"Negotiates pay firmly","right":"'Assertive' man / 'greedy' woman"},{"left":"Sets a clear boundary","right":"'Decisive' man / 'cold' woman"},{"left":"Shares a strong opinion","right":"'Leader' man / 'bossy' woman"},{"left":"Stays late often","right":"'Committed' man / 'neglecting home' woman"},{"left":"Asks for a promotion","right":"'Ambitious' man / 'pushy' woman"}]},
  {"id":"ec-1321","cat":"spot-counter-bias","type":"match","persona":"any","source":"spot-then-act","relearn":"Spotting a bias is step one; pairing it with an action is what counters it.","hook":"Match what you spotted to what you'd do next.","pairs":[{"left":"You spot her being talked over","right":"Hand the floor back to her"},{"left":"You spot the admin defaulting to women","right":"Propose a fair rota"},{"left":"You spot your own gendered label","right":"Reframe it before it lands"},{"left":"You spot a 'joke' at her expense","right":"Call it in lightly"},{"left":"You spot her credit going to him","right":"Set the record straight"}]},
  {"id":"ec-1322","cat":"spot-counter-bias","type":"strike-rewrite","persona":"any","source":"meritocracy-myth","relearn":"'Pure meritocracy' assumes bias is gone; naming bias is how merit actually wins.","hook":"\"We hire on merit alone, so bias can't be a factor here.\"","myth":{"un":"We pick on merit alone, so bias can't creep in.","re":"Believing you're already bias-free is exactly when bias slips through unchecked.","why":"Merit only wins when you actively check the bias around it."}},
  {"id":"ec-1323","cat":"spot-counter-bias","type":"strike-rewrite","persona":"Rohan","source":"not-my-problem","relearn":"Staying neutral on bias quietly sides with it; spotting it is everyone's job.","hook":"\"It's not my place to say anything. I'm not the one affected.\"","myth":{"un":"It's not my place to flag bias I'm not affected by.","re":"Staying 'neutral' lets the bias stand; using your standing to call it in is allyship.","why":"Silence from people not affected is what lets the pattern repeat."}},
  {"id":"ec-1325","cat":"spot-counter-bias","type":"sort","persona":"any","source":"interview-questions","relearn":"Marriage, age and looks are off-limits; skills and results are fair.","hook":"Sort the interview question: biased or fair to ask?","items":[{"id":"a","text":"\"When do you plan to get married?\""},{"id":"b","text":"\"Walk me through this project's result.\""},{"id":"c","text":"\"Won't kids slow you down here?\""},{"id":"d","text":"\"How would you tackle this problem?\""},{"id":"e","text":"\"Aren't you a bit young to lead men?\""},{"id":"f","text":"\"What's a deadline you saved?\""}],"bins":[{"id":"biased","label":"Biased to ask","valence":"neg"},{"id":"fair","label":"Fair to ask","valence":"pos"}],"key":{"a":"biased","b":"fair","c":"biased","d":"fair","e":"biased","f":"fair"}},
  {"id":"ec-1326","cat":"spot-counter-bias","type":"sort","persona":"any","source":"ally-or-bystander","relearn":"Amplifying and handing back the floor are ally moves.","hook":"Sort: an ally move, or bystanding?","items":[{"id":"a","text":"Repeating her point and crediting her"},{"id":"b","text":"Watching her get talked over, silently"},{"id":"c","text":"Handing the floor back after she's cut off"},{"id":"d","text":"Assuming someone else will speak up"},{"id":"e","text":"Naming whose idea it really was"},{"id":"f","text":"Hoping it blows over on its own"}],"bins":[{"id":"ally","label":"Active ally move","valence":"pos"},{"id":"bystander","label":"Just bystanding","valence":"neg"}],"key":{"a":"ally","b":"bystander","c":"ally","d":"bystander","e":"ally","f":"bystander"}},
  {"id":"ec-1327","cat":"spot-counter-bias","type":"sort","persona":"any","source":"real-change-optics","relearn":"Sharing tasks, credit and mentoring is real change; slogans are optics.","hook":"Sort: real change on bias, or just optics?","items":[{"id":"a","text":"Rotating who takes the notes"},{"id":"b","text":"A 'we value women' poster, nothing else"},{"id":"c","text":"Mentoring people who get overlooked"},{"id":"d","text":"One women's-day photo a year"},{"id":"e","text":"Crediting ideas to whoever had them"},{"id":"f","text":"A slogan, with the same old habits"}],"bins":[{"id":"real","label":"Real change","valence":"pos"},{"id":"optics","label":"Just optics","valence":"uhoh"}],"key":{"a":"real","b":"optics","c":"real","d":"optics","e":"real","f":"optics"}},
  {"id":"ec-1328","cat":"spot-counter-bias","type":"sort","persona":"any","source":"feedback-quality","relearn":"Specific, work-based feedback helps; tone-policing is biased.","hook":"Sort: useful feedback, or gendered noise?","items":[{"id":"a","text":"\"Your report missed the Q3 figures.\""},{"id":"b","text":"\"You come across as a bit abrasive.\""},{"id":"c","text":"\"Tighten the intro and it's strong.\""},{"id":"d","text":"\"You should smile more in reviews.\""},{"id":"e","text":"\"Great structure. Add the source.\""},{"id":"f","text":"\"You're just a little too intense.\""}],"bins":[{"id":"useful","label":"Useful feedback","valence":"pos"},{"id":"gendered","label":"Gendered noise","valence":"neg"}],"key":{"a":"useful","b":"gendered","c":"useful","d":"gendered","e":"useful","f":"gendered"}},
  {"id":"ec-1350","cat":"tools-and-help","type":"match","persona":"any","source":"the toolkit","hook":"Match each toolkit move to the moment it's for.","pairs":[{"left":"Reclaim your point","right":"You got talked over"},{"left":"Amplify and credit","right":"Her idea got ignored"},{"left":"Call it in kindly","right":"A quiet sexist dig"},{"left":"Rotate the admin","right":"Notes always fall to one person"},{"left":"Point to redress","right":"A colleague is being harassed"}],"relearn":"Each toolkit move fits a moment: reclaim, amplify, call in, rotate, or route to help."},
  {"id":"ec-1351","cat":"tools-and-help","type":"match","persona":"any","source":"help routes","hook":"Match the need to where help lives (India).","pairs":[{"left":"Harassment at work","right":"Your office Internal Committee"},{"left":"A woman in distress","right":"Women Helpline 181"},{"left":"Your rights, in depth","right":"Know Your Rights (g51)"},{"left":"An ally to back you up","right":"A trusted colleague"},{"left":"It's getting to you","right":"A campus counsellor"}],"relearn":"Internal Committee for harassment, 181 for distress, g51 for rights, and people who can back you up."},
  {"id":"ec-1352","cat":"tools-and-help","type":"match","persona":"any","source":"call in vs out","hook":"Match the kind 'call-in' line to the bias it meets.","pairs":[{"left":"\"Let her finish, then you\"","right":"He keeps cutting in"},{"left":"\"That was Priya's idea first\"","right":"Her point got re-credited"},{"left":"\"Let's rotate who takes notes\"","right":"Notes default to the women"},{"left":"\"Same drive in a man we'd call focus\"","right":"She's labelled 'bossy'"},{"left":"\"Want to lead this one?\"","right":"He's overlooked for stretch work"}],"relearn":"A kind call-in line meets each bias directly without humiliating anyone."},
  {"id":"ec-1353","cat":"tools-and-help","type":"match","persona":"any","source":"toolkit vs not","hook":"Match each move to whether it's a toolkit move or not.","pairs":[{"left":"Reclaiming your point calmly","right":"A toolkit move"},{"left":"Shrinking and over-apologising","right":"Not a toolkit move"},{"left":"Crediting whoever had the idea","right":"An amplify move"},{"left":"Humiliating someone publicly","right":"A harmful move"},{"left":"Pointing a target to redress","right":"The right help move"}],"relearn":"Reclaiming, crediting and routing to help are toolkit moves; shrinking and humiliating aren't."},
  {"id":"ec-1354","cat":"tools-and-help","type":"match","persona":"any","source":"document it","hook":"Match each step to what it does when you note an incident.","pairs":[{"left":"Write down date and time","right":"Keeps the facts straight"},{"left":"Save the messages","right":"Keeps a record you can show"},{"left":"Tell one trusted person","right":"You're not carrying it alone"},{"left":"Note who else saw it","right":"Witnesses can back you up"},{"left":"Find your Internal Committee","right":"A clear route to redress"}],"relearn":"Noting facts, saving proof, telling someone and finding the route turn a vague worry into action."},
  {"id":"ec-1355","cat":"tools-and-help","type":"match","persona":"any","source":"reclaim scripts","hook":"Match the situation to a calm reclaim line you can use.","pairs":[{"left":"Cut off mid-sentence","right":"\"Let me finish my point\""},{"left":"Idea repeated as his","right":"\"Glad you agree, that was my point\""},{"left":"Asked to take notes again","right":"\"I took them last time, your turn\""},{"left":"Dismissed as 'too much'","right":"\"I'm being clear, not difficult\""},{"left":"Talked over in a call","right":"\"I'll pick up where I was\""}],"relearn":"A short calm line lets you reclaim the floor without apologising for taking up space."},
  {"id":"ec-1356","cat":"tools-and-help","type":"match","persona":"any","source":"ally moves","hook":"Match each ally move to the moment it lands.","pairs":[{"left":"Repeat and credit her point","right":"Her idea was skipped"},{"left":"Hand the floor back","right":"He cut her off"},{"left":"Offer to take the notes","right":"Admin keeps falling to her"},{"left":"Back her up out loud","right":"She's being dismissed"},{"left":"Include the sidelined teammate","right":"Someone's being left out"}],"relearn":"Amplifying, handing the floor back, sharing admin, backing up and including are ally actions."},
  {"id":"ec-1357","cat":"tools-and-help","type":"match","persona":"any","source":"who does what","hook":"Match each role to what it can actually do for you.","pairs":[{"left":"Internal Committee","right":"Looks into a harassment complaint"},{"left":"Women Helpline 181","right":"Helps a woman in distress, any hour"},{"left":"A mentor","right":"Opens doors and vouches for you"},{"left":"An ally colleague","right":"Backs you up in the room"},{"left":"Know Your Rights (g51)","right":"Explains your rights in depth"}],"relearn":"Knowing what each route does means you reach for the right one when you need it."},
  {"id":"ec-1358","cat":"tools-and-help","type":"match","persona":"any","source":"confidence drills","hook":"Match each tiny practice to the confidence it builds.","pairs":[{"left":"Speak in the first five minutes","right":"Beats the silence habit"},{"left":"Drop the 'sorry, just'","right":"Your point lands fuller"},{"left":"Apply without every box ticked","right":"You stop self-rejecting"},{"left":"Say your idea once more","right":"It gets remembered as yours"},{"left":"Say yes to one stretch task","right":"You grow into the bigger room"}],"relearn":"Small repeated practices, not a personality change, are what grow confidence."},
  {"id":"ec-1359","cat":"tools-and-help","type":"match","persona":"any","source":"helping a friend","hook":"Match what your friend needs to the move that helps.","pairs":[{"left":"\"Did that even count?\"","right":"\"What he did wasn't okay\""},{"left":"\"I don't want a fuss\"","right":"\"Your call, I'll back you either way\""},{"left":"\"Who do I even tell?\"","right":"\"Your Internal Committee, or 181\""},{"left":"\"Maybe it's just me\"","right":"\"It's not on you, it's on him\""},{"left":"\"I feel alone in this\"","right":"\"I'm with you, you're not alone\""}],"relearn":"A friend in distress needs belief, choice, a route, no blame, and company."},
  {"id":"ec-1360","cat":"tools-and-help","type":"match","persona":"any","source":"name the move","hook":"Match the everyday situation to the toolkit move's name.","pairs":[{"left":"Repeating her point and crediting her","right":"Amplify"},{"left":"Handing the floor back to who was cut off","right":"Interrupt the interruption"},{"left":"Sharing out the note-taking","right":"Rotate the admin"},{"left":"Naming a dig kindly in private","right":"Call it in"},{"left":"Finishing your own sentence","right":"Reclaim"}],"relearn":"Naming the move, amplify, interrupt, rotate, call in, reclaim, makes it easier to reach for."},
  {"id":"ec-1361","cat":"tools-and-help","type":"sort","persona":"any","source":"the toolkit","hook":"Sort: a confidence-toolkit move, or a shrink move?","items":[{"id":"a","text":"Finishing your point when cut off"},{"id":"b","text":"Trailing off with 'never mind'"},{"id":"c","text":"Stating your idea without 'just'"},{"id":"d","text":"Apologising before every sentence"},{"id":"e","text":"Saying yes to a stretch role"},{"id":"f","text":"Waiting for a perfect gap that never comes"}],"bins":[{"id":"tool","label":"Toolkit move","valence":"pos"},{"id":"shrink","label":"Shrink move","valence":"neg"}],"key":{"a":"tool","b":"shrink","c":"tool","d":"shrink","e":"tool","f":"shrink"},"relearn":"Finishing your point, dropping 'just' and saying yes to stretch are toolkit moves; trailing off and over-apologising shrink you."},
  {"id":"ec-1362","cat":"tools-and-help","type":"sort","persona":"any","source":"call in vs out","hook":"Sort: calling bias in (kind), or just shaming (harsh)?","items":[{"id":"a","text":"A quiet word after the meeting"},{"id":"b","text":"Mocking him in front of everyone"},{"id":"c","text":"\"Let her finish, then you\""},{"id":"d","text":"\"Wow, sexist much?\" to shame him"},{"id":"e","text":"\"That landed off, can we redo it?\""},{"id":"f","text":"Posting screenshots to humiliate"}],"bins":[{"id":"in","label":"Call in (kind)","valence":"pos"},{"id":"out","label":"Shame (harsh)","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Calling bias in gives a chance to change; shaming and humiliating just punish and rarely shift anything."},
  {"id":"ec-1363","cat":"tools-and-help","type":"sort","persona":"any","source":"help routes","hook":"Sort: a sanctioned India help route, or not a route at all?","items":[{"id":"a","text":"Your office Internal Committee"},{"id":"b","text":"Just venting and doing nothing"},{"id":"c","text":"Women Helpline 181"},{"id":"d","text":"Telling her to handle it alone"},{"id":"e","text":"Know Your Rights (g51)"},{"id":"f","text":"Hoping it sorts itself out"}],"bins":[{"id":"route","label":"A real route","valence":"pos"},{"id":"none","label":"Not a route","valence":"neg"}],"key":{"a":"route","b":"none","c":"route","d":"none","e":"route","f":"none"},"relearn":"The Internal Committee, Women Helpline 181 and Know Your Rights are real routes; venting or hoping aren't."},
  {"id":"ec-1364","cat":"tools-and-help","type":"sort","persona":"any","source":"ally moves","hook":"Sort: active allyship, or just quiet bystanding?","items":[{"id":"a","text":"Repeating and crediting her point"},{"id":"b","text":"Watching and saying nothing"},{"id":"c","text":"Backing her up out loud"},{"id":"d","text":"Assuming someone else will step in"},{"id":"e","text":"Handing the floor back to her"},{"id":"f","text":"Feeling bad but staying silent"}],"bins":[{"id":"ally","label":"Active ally","valence":"pos"},{"id":"by","label":"Bystander","valence":"neg"}],"key":{"a":"ally","b":"by","c":"ally","d":"by","e":"ally","f":"by"},"relearn":"Amplifying, backing up and handing the floor back are allyship; watching and waiting for others is bystanding."},
  {"id":"ec-1365","cat":"tools-and-help","type":"sort","persona":"any","source":"reclaim the floor","hook":"Sort: reclaims the floor, or hands it away?","items":[{"id":"a","text":"\"Let me finish my point\""},{"id":"b","text":"\"Sorry, it's probably nothing\""},{"id":"c","text":"\"I'll pick up where I was\""},{"id":"d","text":"Going quiet and letting it slide"},{"id":"e","text":"\"One sec, I wasn't done\""},{"id":"f","text":"\"Never mind, it's fine\""}],"bins":[{"id":"keep","label":"Reclaims it","valence":"pos"},{"id":"give","label":"Gives it away","valence":"neg"}],"key":{"a":"keep","b":"give","c":"keep","d":"give","e":"keep","f":"give"},"relearn":"Short clear lines reclaim the floor; 'sorry, never mind' and going quiet hand it away."},
  {"id":"ec-1366","cat":"tools-and-help","type":"sort","persona":"any","source":"first response","hook":"Sort: helps a friend who's being harassed, or makes it worse?","items":[{"id":"a","text":"\"That wasn't okay, and not your fault\""},{"id":"b","text":"\"Sure you didn't lead him on?\""},{"id":"c","text":"\"Your call, I'll back you either way\""},{"id":"d","text":"\"Just ignore it, don't make a scene\""},{"id":"e","text":"\"Your IC or 181 can help\""},{"id":"f","text":"\"It's probably not a big deal\""}],"bins":[{"id":"help","label":"Helps","valence":"pos"},{"id":"hurt","label":"Makes it worse","valence":"neg"}],"key":{"a":"help","b":"hurt","c":"help","d":"hurt","e":"help","f":"hurt"},"relearn":"Belief, choice and a route help; blame, 'ignore it' and minimising make it worse."},
  {"id":"ec-1367","cat":"tools-and-help","type":"sort","persona":"any","source":"office housework","hook":"Sort: a fair way to share office admin, or a default stuck on one person?","items":[{"id":"a","text":"Rotating note-taking each meeting"},{"id":"b","text":"\"You're good at notes, you do it\""},{"id":"c","text":"A shared roster for the chai run"},{"id":"d","text":"Always asking the youngest woman"},{"id":"e","text":"Volunteers tracked so it's even"},{"id":"f","text":"Whoever 'naturally' organises gets it"}],"bins":[{"id":"fair","label":"Shared fairly","valence":"pos"},{"id":"stuck","label":"Defaulted","valence":"neg"}],"key":{"a":"fair","b":"stuck","c":"fair","d":"stuck","e":"fair","f":"stuck"},"relearn":"Rotating and rostering admin shares it fairly; 'you're good at it' and asking the same person defaults it."},
  {"id":"ec-1368","cat":"tools-and-help","type":"sort","persona":"any","source":"confidence vs arrogance","hook":"Sort: confidence (takes space, respects others), or arrogance (tramples)?","items":[{"id":"a","text":"Stating your view, then asking theirs"},{"id":"b","text":"Talking over everyone to win"},{"id":"c","text":"Owning your idea and crediting help"},{"id":"d","text":"Taking sole credit for a team win"},{"id":"e","text":"Holding your point under pushback"},{"id":"f","text":"Dismissing anyone who disagrees"}],"bins":[{"id":"conf","label":"Confidence","valence":"pos"},{"id":"arr","label":"Arrogance","valence":"neg"}],"key":{"a":"conf","b":"arr","c":"conf","d":"arr","e":"conf","f":"arr"},"relearn":"Confidence takes your space and respects others'; arrogance grabs space by trampling them."},
  {"id":"ec-1369","cat":"tools-and-help","type":"sort","persona":"any","source":"real vs optics","hook":"Sort: real equality work, or just optics?","items":[{"id":"a","text":"Rotating who gets the visible projects"},{"id":"b","text":"A poster in the pantry"},{"id":"c","text":"Mentoring an overlooked junior"},{"id":"d","text":"A one-day slogan campaign"},{"id":"e","text":"Tracking who gets interrupted"},{"id":"f","text":"Saying 'we value women' and changing nothing"}],"bins":[{"id":"real","label":"Real change","valence":"pos"},{"id":"optics","label":"Just optics","valence":"neg"}],"key":{"a":"real","b":"optics","c":"real","d":"optics","e":"real","f":"optics"},"relearn":"Rotating visible work, mentoring and tracking interruptions are real; posters and slogans without change are optics."},
  {"id":"ec-1370","cat":"tools-and-help","type":"sort","persona":"any","source":"spotting the route","hook":"Sort: a workplace harassment matter, or a general distress call?","items":[{"id":"a","text":"A boss demands favours for a promotion"},{"id":"b","text":"A woman is unsafe at home tonight"},{"id":"c","text":"Crude comments in the team chat"},{"id":"d","text":"A friend in distress with nowhere to turn"},{"id":"e","text":"A senior keeps cornering an intern"},{"id":"f","text":"A woman stranded and frightened, late"}],"bins":[{"id":"ic","label":"Internal Committee","valence":"neutral"},{"id":"line","label":"Women Helpline 181","valence":"neutral"}],"key":{"a":"ic","b":"line","c":"ic","d":"line","e":"ic","f":"line"},"relearn":"Workplace harassment goes to the Internal Committee; a woman in distress anywhere can call Women Helpline 181."},
  {"id":"ec-1417","cat":"tools-and-help","type":"sort","persona":"any","source":"your rights at work","hook":"Sort: something a safe workplace owes you, or a myth you're told to accept?","items":[{"id":"a","text":"A workplace free of harassment"},{"id":"b","text":"\"Harassment is the price of the job\""},{"id":"c","text":"A route to report without punishment"},{"id":"d","text":"\"Reporting just ends your career\""},{"id":"e","text":"To be believed when you raise it"},{"id":"f","text":"\"You must have invited it\""}],"bins":[{"id":"owed","label":"Owed to you","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"owed","b":"myth","c":"owed","d":"myth","e":"owed","f":"myth"},"relearn":"Safety, a punishment-free route and being believed are owed to you; the rest are myths to reject."},
  {"id":"ec-1371","cat":"tools-and-help","type":"branch","persona":"Mehta","source":"harassment redress","hook":"An intern says a senior keeps making her uncomfortable, but fears no one will believe her.","options":[{"text":"Believe her and walk her to the Internal Committee","consequence":"She feels backed, with a real channel.","best":true},{"text":"Say she may have misread it","consequence":"She doubts herself and stays quiet."},{"text":"Say it's not yours to get into","consequence":"She's left alone, no route."}],"debrief":"Believe the person first, then point them to the Internal Committee.","relearn":"Believe a harassment report first, then route to the Internal Committee, never wave it away."},
  {"id":"ec-1372","cat":"tools-and-help","type":"branch","persona":"any","source":"reclaim the floor","hook":"You're three sentences into your idea when a colleague talks right over you.","options":[{"text":"Say \"let me finish my point\" and continue","consequence":"You hold the floor and your idea lands.","best":true},{"text":"Stop and let him take it","consequence":"Your point is lost."},{"text":"Snap \"will you ever shut up?\"","consequence":"It turns into a clash."}],"debrief":"A short, calm reclaim keeps the floor without apology and without a fight.","relearn":"When talked over, calmly say you'll finish your point, no perfect gap or apology needed."},
  {"id":"ec-1373","cat":"tools-and-help","type":"branch","persona":"any","source":"amplify and credit","hook":"A quieter colleague's idea is ignored, then repeated by someone louder as their own.","options":[{"text":"Say \"building on Anjali's earlier point...\"","consequence":"Her idea is credited and heard.","best":true},{"text":"Let it slide to avoid awkwardness","consequence":"Her idea stays uncredited."},{"text":"Call the louder one a thief out loud","consequence":"It derails into conflict."}],"debrief":"Amplifying, crediting the original voice, hands credit back without a fight.","relearn":"When an idea is re-credited, name who said it first and build on it, that's amplifying, not accusing."},
  {"id":"ec-1374","cat":"tools-and-help","type":"branch","persona":"any","source":"office housework","hook":"For the fourth meeting running, you're asked to 'just take the notes, you're good at it'.","options":[{"text":"Suggest rotating notes from now on","consequence":"The admin gets shared.","best":true},{"text":"Sigh and take them again","consequence":"The default sticks."},{"text":"Refuse flatly and storm out","consequence":"It reads as a tantrum."}],"debrief":"Note-taking isn't naturally one person's job; a rotation makes it shared.","relearn":"Office admin should rotate, not default to you; suggest a roster rather than absorbing it again."},
  {"id":"ec-1375","cat":"tools-and-help","type":"branch","persona":"Rohan","source":"be the ally","hook":"In your group, a mate makes a 'jokey' comment that lands on the one woman present.","options":[{"text":"Say lightly \"that one's not on, let's not\"","consequence":"You name it and the room resets.","best":true},{"text":"Laugh along to keep things smooth","consequence":"Silence reads as agreement."},{"text":"Wait and hope she handles it","consequence":"You leave her to carry it."}],"debrief":"Calling a 'joke' in lightly but clearly is everyday allyship, no speech needed.","relearn":"Name a sexist 'joke' lightly but clearly; silence leaves it on the person it targets."},
  {"id":"ec-1376","cat":"tools-and-help","type":"branch","persona":"any","source":"impostor moment","hook":"A great role is posted, but you don't tick every box, and you're about to skip it.","options":[{"text":"Apply anyway and show the fit you have","consequence":"You give yourself the chance.","best":true},{"text":"Wait until you meet every line","consequence":"You'll keep waiting forever."},{"text":"Apply but open with all your gaps","consequence":"You undercut yourself."}],"debrief":"You rarely need every requirement; applying at a partial fit is normal.","relearn":"Apply even without every box ticked; self-rejecting first just does the bias's work."},
  {"id":"ec-1377","cat":"tools-and-help","type":"branch","persona":"any","source":"distress route","hook":"A friend messages at midnight: she's unsafe and doesn't know who to call.","options":[{"text":"Stay with her and share Women Helpline 181","consequence":"She has company and an any-hour route.","best":true},{"text":"Tell her to decide tomorrow","consequence":"She's left alone in the moment."},{"text":"Take over every decision for her","consequence":"She loses her say."}],"debrief":"A woman in distress can reach Women Helpline 181 any hour; stay with her and let her choose.","relearn":"For a woman in distress, share Women Helpline 181 and stay present, support, don't take over."},
  {"id":"ec-1378","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"never the price","hook":"\"If you want to keep this job, harassment is just something you put up with.\"","myth":{"un":"Harassment is the price you pay to keep a job.","re":"Harassment is never the price of a job; you have rights and real redress through your Internal Committee.","why":"Your workplace owes you a safe place to work, full stop."},"relearn":"Harassment is never the price of a job; an Internal Committee exists precisely so you don't have to endure it."},
  {"id":"ec-1379","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"reporting myth","hook":"\"Reporting harassment will just brand you a troublemaker and end your career.\"","myth":{"un":"Reporting harassment only ruins the person who reports it.","re":"You have a right to report through your Internal Committee, and the process exists to protect you, not punish you.","why":"The fault and the consequences belong with the harasser, not the person reporting."},"relearn":"Reporting is a right, not a black mark; the redress process is built to protect the person who speaks up."},
  {"id":"ec-1380","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"toolkit myth","hook":"\"Confidence is something you're just born with, you either have it or you don't.\"","myth":{"un":"Confidence is a fixed trait you either have or don't.","re":"Confidence is a set of practised moves, speaking early, finishing your point, applying anyway, that anyone can build.","why":"It grows by doing; each time you use a move it gets easier."},"relearn":"Confidence is built, not born; it's a toolkit of small moves that get easier every time you practise them."},
  {"id":"ec-1381","cat":"tools-and-help","type":"strike-rewrite","persona":"Rohan","source":"calling in myth","hook":"\"If someone's being sexist, the only real answer is to call them out hard in public.\"","myth":{"un":"The only way to counter bias is a harsh public call-out.","re":"You can call it in, kindly and often privately, giving a chance to change instead of just shaming.","why":"Calling in shifts behaviour more often than humiliation does."},"relearn":"Calling bias in, kind and often private, is a real counter; public shaming isn't the only or best option."},
  {"id":"ec-1382","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"ally myth","hook":"\"Being an ally just means you believe in equality in your head.\"","myth":{"un":"Allyship is just privately believing in equality.","re":"Allyship is action, amplifying, backing people up, sharing the load, not a belief you hold quietly.","why":"Belief that never moves into action leaves the room exactly as biased as before."},"relearn":"Allyship is what you do, amplify, back up, share the load, not just what you believe."},
  {"id":"ec-1383","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"asking for help myth","hook":"\"Asking for help or admitting doubt makes you look weak and unfit to lead.\"","myth":{"un":"Good leaders never ask for help or admit doubt.","re":"Asking for help and admitting doubt builds trust; it's a strength of real leaders, not a weakness.","why":"People follow leaders who are honest about limits more than ones who fake certainty."},"relearn":"Asking for help and owning doubt build trust; pretending to know everything is the weaker move."},
  {"id":"ec-1384","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"not your fault","hook":"\"If you're getting harassed, you must have given the wrong signal somehow.\"","myth":{"un":"Harassment happens because the target gave the wrong signal.","re":"Harassment is never the target's fault; the responsibility sits entirely with the person who does it.","why":"No signal, outfit or tone makes anyone responsible for another person's behaviour."},"relearn":"Harassment is never your fault; the fault and the fix sit with the harasser, not the person targeted."},
  {"id":"ec-1385","cat":"tools-and-help","type":"reflect","persona":"any","source":"equipped","hook":"Lensy: you've got a real toolkit now, reclaim, amplify, call in, route to help. Feel that?","prompt":"What's landing?","options":["I'm equipped","I have moves now","I can change the room"],"affirm":"Reclaiming, amplifying, calling in and knowing the routes are exactly the tools that make a room fairer.","relearn":"Your toolkit is reclaim, amplify, call in and route to help, real moves that make any room fairer."},
  {"id":"ec-1386","cat":"tools-and-help","type":"reflect","persona":"any","source":"pick a move","hook":"Lensy: which toolkit move do you most want to get comfortable with first?","prompt":"Pick one to start.","options":["Reclaiming my point","Amplifying others","Calling bias in kindly","Rotating the admin"],"affirm":"Any one of these, practised, makes the next room a little fairer, and the move gets easier each time.","relearn":"Pick one toolkit move and practise it; it gets easier each time and makes the next room fairer."},
  {"id":"ec-1387","cat":"tools-and-help","type":"reflect","persona":"any","source":"reclaim line","hook":"Lensy: keep one short reclaim line ready, so next time you're cut off you don't freeze.","prompt":"Which line feels like yours?","options":["\"Let me finish my point\"","\"I'll pick up where I was\"","\"One sec, I wasn't done\""],"affirm":"Having a line ready means you reclaim the floor on reflex, no perfect gap and no apology needed.","relearn":"Keep one short reclaim line ready so you can hold the floor without freezing or apologising."},
  {"id":"ec-1388","cat":"tools-and-help","type":"reflect","persona":"any","source":"knowing the route","hook":"Lensy: just knowing where help lives, the Internal Committee, Women Helpline 181, changes how safe a room feels.","prompt":"How does that sit?","options":["Good to know it's there","I'd know where to point a friend","Less alone"],"affirm":"Knowing the routes means you can back yourself or a friend the moment it's needed, that's real power.","relearn":"Knowing the routes, the Internal Committee and Women Helpline 181, lets you back yourself or a friend fast."},
  {"id":"ec-1416","cat":"tools-and-help","type":"reflect","persona":"any","source":"ally identity","hook":"Lensy: being the ally is a daily habit of small actions, not a badge you earn once.","prompt":"What feels true?","options":["I can do the small stuff daily","Trying beats freezing","I'll adjust when I slip"],"affirm":"Small daily actions, amplify, back up, include, are exactly what allyship is; trying and adjusting is the whole job.","relearn":"Allyship is a daily habit of small actions; trying beats freezing, and you adjust when you slip."},
  {"id":"ec-1389","cat":"tools-and-help","type":"reflect","persona":"Aarti","source":"claim your space","hook":"Lensy: your voice belongs in every room you're in, the same as anyone's. Sitting with that?","prompt":"What's true for you?","options":["My voice belongs here","I'll take my space","I don't have to shrink"],"affirm":"You belong in the conversation, and taking your space, with respect for others', is exactly the point.","relearn":"Your voice belongs in every room; take your space, with respect for others', and don't shrink."},
  {"id":"ec-1390","cat":"tools-and-help","type":"reflect","persona":"any","source":"call in style","hook":"Lensy: calling bias in is kinder and often more effective in private, on your terms, not a public showdown.","prompt":"Which fits you?","options":["A quiet word after","A light line in the moment","A note to the chair later"],"affirm":"Calling in, kind and often private, gives a real chance to change, and any of these styles can be yours.","relearn":"Calling bias in, kind and often private, gives a real chance to change; pick the style that fits you."},
  {"id":"ec-1391","cat":"tools-and-help","type":"reflect","persona":"any","source":"share the load","hook":"Lensy: spotting who always ends up with the notes and the chai run is the first step to sharing it.","prompt":"What do you notice?","options":["It falls on the same people","We could rotate it","I'll suggest a roster"],"affirm":"Noticing the default is how you change it, admin should rotate, and naming that out loud starts the shift.","relearn":"Spotting who always gets the admin is step one; admin should rotate, so name it and suggest a roster."},
  {"id":"ec-1392","cat":"tools-and-help","type":"reflect","persona":"any","source":"backing a friend","hook":"Lensy: if a friend ever says 'did that even count?', the first gift is believing her.","prompt":"What would you offer?","options":["I'd believe her","I'd let her choose","I'd stay with her"],"affirm":"Belief, choice and company are the first things a friend needs, the route to help comes right after.","relearn":"A friend in distress needs belief, choice and company first; the route to help comes right after."},
  {"id":"ec-1393","cat":"tools-and-help","type":"reflect","persona":"any","source":"confidence is built","hook":"Lensy: confidence isn't a thing you're born with, it's the moves you practise. Which will you rep?","prompt":"Pick a rep for this week.","options":["Speak in the first five minutes","Drop 'sorry, just'","Apply at a partial fit"],"affirm":"Each rep makes the next one easier, that's how confidence is built, not a personality you wait to be handed.","relearn":"Confidence is built by reps, not handed to you; each practice makes the next one easier."},
  {"id":"ec-1394","cat":"tools-and-help","type":"reflect","persona":"any","source":"not zero-sum","hook":"Lensy: every toolkit move makes the room fairer for everyone in it, you included. Feel that?","prompt":"What lands?","options":["A fairer room helps all of us","I gain too","Not against anyone"],"affirm":"A fairer room lifts everyone in it; the toolkit is built with people, never against anyone.","relearn":"A fairer room lifts everyone in it; the toolkit is built with people, never against anyone."},
  {"id":"ec-1395","cat":"tools-and-help","type":"reflect","persona":"any","source":"male ally","hook":"Lensy: men leading on equality is strength, and the toolkit is everyone's to carry. Sitting with that?","prompt":"What's true?","options":["This is my job too","Leading on it is strength","Everyone's room to fix"],"affirm":"Equality is everyone's work; men carrying the toolkit, amplifying, backing up, is strength, not a loss.","relearn":"Equality is everyone's work; men carrying the toolkit is strength, not a loss."},
  {"id":"ec-1396","cat":"tools-and-help","type":"reflect","persona":"any","source":"document it","hook":"Lensy: if something ever crosses a line, noting the facts early makes any later step far easier.","prompt":"What would you keep?","options":["Date and time","The messages","Who else saw it"],"affirm":"A simple record, facts, messages, witnesses, turns a vague worry into something you can clearly act on.","relearn":"Noting facts, messages and witnesses early turns a vague worry into something you can clearly act on."},
  {"id":"ec-1397","cat":"tools-and-help","type":"reflect","persona":"Zoya","source":"inclusive toolkit","hook":"Lensy: the toolkit spans everyone, including queer and sidelined colleagues, no one's left out.","prompt":"What feels right?","options":["It's for all of us","I'll include who's sidelined","Allyship spans identities"],"affirm":"Including the person being sidelined, whoever they are, is core to the toolkit; allyship spans every identity.","relearn":"The toolkit and allyship span every identity; including whoever's sidelined is core to it."},
  {"id":"ec-1398","cat":"tools-and-help","type":"reflect","persona":"any","source":"carry it forward","hook":"Lensy: voice, leadership, bias-radar, allyship, and the routes to help. Carry all of it forward?","prompt":"What will you carry?","options":["My voice and moves","Spotting and calling in","Knowing the routes","All of it"],"affirm":"Carry your voice, your moves, your bias-radar and the routes to help, and you can make any room fairer.","relearn":"Carry your voice, your moves, your bias-radar and the routes to help into every room."},
  {"id":"ec-1399","cat":"tools-and-help","type":"reflect","persona":"any","source":"start small","hook":"Lensy: you don't need to fix everything at once, one move in one room this week is plenty.","prompt":"What's your one thing?","options":["Reclaim once","Amplify someone","Suggest a rotation"],"affirm":"One real move in one room is how change starts, and the next one always comes easier than the first.","relearn":"One real move in one room is how change starts; the next comes easier than the first."},
  {"id":"ec-1400","cat":"tools-and-help","type":"reflect","persona":"any","source":"trust yourself","hook":"Lensy: if a room keeps making you feel small, that's a signal about the room, not a verdict on you.","prompt":"What sits with you?","options":["It's the room, not me","I can name it","I can find my people"],"affirm":"Being boxed in by bias is no flaw in you; you can name it, use your moves, and find people who back you.","relearn":"A room that makes you feel small is a signal about the room, not a verdict on you."},
  {"id":"ec-1401","cat":"tools-and-help","type":"spot","persona":"any","source":"first response","hook":"A friend confides she's being harassed. Spot the 2 lines that make it harder for her.","scene":[{"id":"a","text":"\"That wasn't okay, and not your fault\"","trick":false},{"id":"b","text":"\"Sure you didn't encourage it?\"","trick":true},{"id":"c","text":"\"Your call, I'll back you\"","trick":false},{"id":"d","text":"\"Just ignore it, don't make a scene\"","trick":true},{"id":"e","text":"\"Your IC or 181 can help\"","trick":false}],"why":"Blaming her and telling her to stay quiet are the harmful lines; belief, choice and a route help.","relearn":"Believe a friend, let her choose, point to a route; blame and 'just ignore it' make it harder."},
  {"id":"ec-1402","cat":"tools-and-help","type":"spot","persona":"any","source":"fake toolkit","hook":"Spot the 2 moves that wear a 'confidence' label but really trample others.","scene":[{"id":"a","text":"State your view, then ask theirs","trick":false},{"id":"b","text":"Talk over everyone to win","trick":true},{"id":"c","text":"Hold your point under pushback","trick":false},{"id":"d","text":"Take sole credit for a team's work","trick":true},{"id":"e","text":"Own your idea and credit help","trick":false}],"why":"Talking over people and grabbing all the credit are arrogance, not confidence.","relearn":"Confidence takes your space and respects others'; talking over people and grabbing credit is arrogance."},
  {"id":"ec-1403","cat":"tools-and-help","type":"spot","persona":"any","source":"call in vs shame","hook":"You want to counter a sexist dig. Spot the 2 lines that humiliate instead of calling in.","scene":[{"id":"a","text":"\"A quiet word: that landed off\"","trick":false},{"id":"b","text":"\"Wow, sexist much?\" in front of all","trick":true},{"id":"c","text":"\"Let her finish, then you go\"","trick":false},{"id":"d","text":"Posting his words online to shame him","trick":true},{"id":"e","text":"\"Can we redo that bit?\"","trick":false}],"why":"Public mockery and shaming-by-screenshot humiliate; calling in is kind and gives a chance to change.","relearn":"Calling bias in is kind and often private; public mockery and shaming are not toolkit moves."},
  {"id":"ec-1404","cat":"tools-and-help","type":"spot","persona":"any","source":"wrong route","hook":"A colleague faces harassment at work. Spot the 2 'routes' that aren't real help.","scene":[{"id":"a","text":"Go to your office Internal Committee","trick":false},{"id":"b","text":"Just vent and do nothing","trick":true},{"id":"c","text":"Note the dates, save the messages","trick":false},{"id":"d","text":"Tell her to sort it alone","trick":true},{"id":"e","text":"Point her to Know Your Rights (g51)","trick":false}],"why":"Venting-and-nothing and 'sort it alone' aren't routes; the Committee, documenting and g51 are.","relearn":"The Internal Committee, documenting and Know Your Rights are routes; venting or 'handle it alone' aren't."},
  {"id":"ec-1405","cat":"tools-and-help","type":"spot","persona":"any","source":"shrink tells","hook":"Spot the 2 habits that shrink your message in a meeting.","scene":[{"id":"a","text":"Stating your point without 'just'","trick":false},{"id":"b","text":"\"Sorry, this is probably silly\"","trick":true},{"id":"c","text":"Finishing your sentence when cut off","trick":false},{"id":"d","text":"Trailing off into \"never mind\"","trick":true},{"id":"e","text":"Saying your idea once more to be heard","trick":false}],"why":"The pre-apology and trailing off shrink your message; stating it plainly keeps it strong.","relearn":"Pre-apologising and trailing off shrink your point; state it directly and finish it."},
  {"id":"ec-1406","cat":"tools-and-help","type":"spot","persona":"any","source":"fake ally","hook":"Spot the 2 'ally' moves that are really just bystanding.","scene":[{"id":"a","text":"Repeating and crediting her point","trick":false},{"id":"b","text":"Feeling bad but staying silent","trick":true},{"id":"c","text":"Handing the floor back to who was cut off","trick":false},{"id":"d","text":"Assuming someone else will step in","trick":true},{"id":"e","text":"Backing her up out loud","trick":false}],"why":"Silent sympathy and assuming others will act are bystanding, not allyship.","relearn":"Amplifying and backing up are allyship; staying silent or waiting for others is just bystanding."},
  {"id":"ec-1407","cat":"tools-and-help","type":"spot","persona":"any","source":"office housework","hook":"Spot the 2 lines that quietly default the admin onto one person.","scene":[{"id":"a","text":"\"Let's rotate notes each week\"","trick":false},{"id":"b","text":"\"You're neater, you do it\"","trick":true},{"id":"c","text":"\"I'll take the chai run this time\"","trick":false},{"id":"d","text":"\"She always organises, leave it to her\"","trick":true},{"id":"e","text":"\"Let's track it so it stays even\"","trick":false}],"why":"'You're neater, you do it' and 'leave it to her' default admin; rotating and tracking share it.","relearn":"Admin should be rotated and tracked, not defaulted with 'you do it' or 'leave it to her'."},
  {"id":"ec-1408","cat":"tools-and-help","type":"role-play","persona":"any","source":"reclaim the floor","hook":"You're cut off mid-point in a team meeting.","setup":"Reclaim the floor, calm and clear. Say:","yourLine":[{"text":"\"Let me finish my point, then I'd love your take.\"","best":true},{"text":"\"Sorry, you go ahead, mine wasn't important.\""}],"relearn":"When cut off, calmly finish your point, then invite them, you don't have to hand the floor away."},
  {"id":"ec-1409","cat":"tools-and-help","type":"role-play","persona":"any","source":"amplify and credit","hook":"A colleague's good idea was skipped, then echoed by someone else as their own.","setup":"Amplify and credit the original. Say:","yourLine":[{"text":"\"To credit it, that was Riya's idea first, let's build on it.\"","best":true},{"text":"Stay quiet so no one feels awkward."}],"relearn":"Name who had the idea first and build on it; amplifying hands the credit back."},
  {"id":"ec-1410","cat":"tools-and-help","type":"role-play","persona":"any","source":"office housework","hook":"You're asked to take the minutes for the fifth meeting in a row.","setup":"Propose a fair rotation. Say:","yourLine":[{"text":"\"I've had the last few, can we rotate notes from now on?\"","best":true},{"text":"\"Fine, I'll do it again,\" and say nothing."}],"relearn":"Note-taking should rotate; proposing a roster shares the admin instead of absorbing it again."},
  {"id":"ec-1411","cat":"tools-and-help","type":"role-play","persona":"any","source":"call it in","hook":"A teammate calls a woman's clear leadership 'bossy' in the group chat.","setup":"Call it in, kindly. Say:","yourLine":[{"text":"\"Same drive in a guy we'd call decisive, let's drop 'bossy'.\"","best":true},{"text":"React with a laughing emoji and move on."}],"relearn":"The 'bossy' label is the double standard; name it kindly and the same assertiveness reads as leadership."},
  {"id":"ec-1412","cat":"tools-and-help","type":"role-play","persona":"Mehta","source":"harassment redress","hook":"A student tells you a senior is harassing her and she's scared to report.","setup":"Back her and point to the route. Say:","yourLine":[{"text":"\"I believe you, it's not your fault, and your IC can act on it.\"","best":true},{"text":"\"Are you sure? Maybe don't rock the boat.\""}],"relearn":"Believe her, say it's not her fault, and point to the Internal Committee, that's how you back a target."},
  {"id":"ec-1413","cat":"tools-and-help","type":"role-play","persona":"any","source":"distress route","hook":"A friend messages that she's unsafe and doesn't know who to call.","setup":"Stay with her and share the route. Say:","yourLine":[{"text":"\"I'm here. You can call the Women Helpline 181 right now, any hour.\"","best":true},{"text":"\"Try to sleep, we'll figure it out tomorrow.\""}],"relearn":"For a woman in distress, share Women Helpline 181 and stay present, it's open any hour."},
  {"id":"ec-1414","cat":"tools-and-help","type":"role-play","persona":"Rohan","source":"be the ally","hook":"In your friend group, a 'joke' lands on the one woman present.","setup":"Call it in, light but clear. Say:","yourLine":[{"text":"\"That one's not really on, mate, let's leave it.\"","best":true},{"text":"Laugh along so it doesn't get awkward."}],"relearn":"Name a sexist 'joke' lightly but clearly; laughing along leaves it on the person it targets."},
  {"id":"ec-1415","cat":"tools-and-help","type":"role-play","persona":"Aarti","source":"claim your voice","hook":"In a seminar you have a half-formed idea but worry it's not polished enough.","setup":"Claim your space anyway. Say:","yourLine":[{"text":"\"I'm still shaping this, but here's where I'd start...\"","best":true},{"text":"Say nothing and wait until it's perfect."}],"relearn":"A half-formed thought is still worth voicing; you belong in the conversation before it's perfect."},
];

